#!/usr/bin/env node
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { EVENT_TYPES, EventType, OfficerRole } from './core/types.js';
import { KnowledgeUpdateProposal } from './crew/types.js';
import { NumberOneMcpServer } from './harness/mcp-server.js';
import { NumberOneAgent } from './harness/number-one.js';
import { installHarnessShims } from './harness/shims.js';
import { atomicWriteFileSync, readTextFileSafe } from './utils/fs-helpers.js';
import { redactObjectDeep, redactSecrets } from './utils/redactor.js';
import { generateShellHook } from './watchers/command-runner.js';
import { isGitRepository, recordGitHookEvent, SupportedGitHook } from './watchers/git-hooks.js';

interface ParsedArgs {
  command: string;
  positionals: string[];
  flags: Record<string, string | boolean | string[]>;
  passthrough: string[];
}

const FORBIDDEN_FLAG_KEYS = new Set([
  '__proto__',
  'prototype',
  'constructor',
  'toString',
  'valueOf',
  'hasOwnProperty'
]);

const BOOLEAN_FLAGS = new Set([
  'json',
  'foreground',
  'no-hooks',
  'no-shims',
  'local-only',
  'dry-run',
  'allow-exec',
  'help',
  'version',
  'force'
]);

const VALID_EVENT_TYPE_SET = new Set<string>(EVENT_TYPES);
const VALID_GIT_HOOKS = new Set<string>(['post-commit', 'post-checkout', 'post-merge', 'pre-push']);
const VALID_SEVERITIES = new Set<string>(['low', 'medium', 'high', 'critical']);
const VALID_DIRECTIVE_SEVERITIES = new Set<string>(['advisory', 'mandatory', 'blocking']);
const VALID_ISSUE_KINDS = new Set<string>([
  'bug',
  'crash',
  'story',
  'epic',
  'task',
  'debt',
  'security',
  'infra',
  'release'
]);
const VALID_PARTY_MODES = new Set<string>(['roundtable', 'specialist', 'auto-triage']);
const VALID_OFFICERS = new Set<string>(['engineering', 'security', 'bridge']);

class CliInputError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'CliInputError';
  }
}

function getPackageVersion(): string {
  try {
    const raw = fs.readFileSync(new URL('../package.json', import.meta.url), 'utf8');
    const parsed = JSON.parse(raw) as { version?: unknown };
    if (typeof parsed.version === 'string' && parsed.version.trim()) {
      return parsed.version.trim();
    }
  } catch {
    // ignore
  }
  return '1.0.0';
}

function assertSafeFlagKey(key: string): void {
  if (!key || FORBIDDEN_FLAG_KEYS.has(key) || key.length > 64) {
    throw new CliInputError(`Rejected invalid or unsafe CLI flag name: "--${key}"`);
  }
}

function assertEnumFlag<T extends string>(
  raw: string | undefined,
  allowed: Set<string>,
  flagName: string,
  fallback: T
): T {
  if (raw === undefined) return fallback;
  if (!allowed.has(raw)) {
    throw new CliInputError(
      `Invalid value "${raw}" for --${flagName}. Allowed: ${Array.from(allowed).join(', ')}`
    );
  }
  return raw as T;
}

export function parseCliArgs(argv: string[]): ParsedArgs {
  const dashDashIdx = argv.indexOf('--');
  const mainArgs = dashDashIdx === -1 ? argv : argv.slice(0, dashDashIdx);
  const passthrough = dashDashIdx === -1 ? [] : argv.slice(dashDashIdx + 1);

  let command = '';
  const positionals: string[] = [];
  const flags = Object.create(null) as Record<string, string | boolean | string[]>;

  for (let i = 0; i < mainArgs.length; i++) {
    const tok = mainArgs[i]!;
    if (tok === '-h') {
      flags.help = true;
      continue;
    }
    if (tok === '-v' || tok === '-V') {
      flags.version = true;
      continue;
    }
    if (tok.startsWith('--')) {
      const eqIdx = tok.indexOf('=');
      if (eqIdx !== -1) {
        const k = tok.slice(2, eqIdx);
        assertSafeFlagKey(k);
        const v = tok.slice(eqIdx + 1);
        if (BOOLEAN_FLAGS.has(k)) {
          flags[k] = v !== 'false' && v !== '0';
        } else {
          pushFlag(flags, k, v);
        }
      } else {
        const k = tok.slice(2);
        assertSafeFlagKey(k);
        if (BOOLEAN_FLAGS.has(k)) {
          flags[k] = true;
        } else {
          const next = mainArgs[i + 1];
          if (next !== undefined && !next.startsWith('--')) {
            pushFlag(flags, k, next);
            i++;
          } else {
            flags[k] = true;
          }
        }
      }
    } else if (!command) {
      command = tok;
    } else {
      positionals.push(tok);
    }
  }

  if (!command) {
    command = flags.version ? 'version' : 'help';
  }

  return { command, positionals, flags, passthrough };
}

function pushFlag(
  flags: Record<string, string | boolean | string[]>,
  key: string,
  val: string
): void {
  const existing = flags[key];
  if (existing === undefined) {
    flags[key] = val;
  } else if (Array.isArray(existing)) {
    existing.push(val);
  } else if (typeof existing === 'string') {
    flags[key] = [existing, val];
  } else {
    flags[key] = val;
  }
}

function flagStr(flags: ParsedArgs['flags'], key: string): string | undefined {
  const v = flags[key];
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v[v.length - 1];
  return undefined;
}

function flagList(flags: ParsedArgs['flags'], key: string): string[] {
  const v = flags[key];
  if (Array.isArray(v)) return v.flatMap((x) => x.split(',').map((s) => s.trim()).filter(Boolean));
  if (typeof v === 'string') return v.split(',').map((s) => s.trim()).filter(Boolean);
  return [];
}

function flagBool(flags: ParsedArgs['flags'], key: string): boolean {
  return flags[key] === true || flags[key] === 'true';
}

function parsePositiveIntFlag(raw: string | undefined, name: string): number | undefined {
  if (raw === undefined) return undefined;
  if (!/^\d+$/.test(raw)) {
    throw new CliInputError(`--${name} must be a positive integer (received: "${raw}")`);
  }
  const parsed = Number.parseInt(raw, 10);
  if (!Number.isSafeInteger(parsed) || parsed <= 0) {
    throw new CliInputError(`--${name} must be a positive integer (received: "${raw}")`);
  }
  return parsed;
}

function parseNonNegativeIntFlag(raw: string | undefined, name: string, fallback: number): number {
  if (raw === undefined) return fallback;
  if (!/^\d+$/.test(raw)) {
    throw new CliInputError(`--${name} must be a non-negative integer (received: "${raw}")`);
  }
  const parsed = Number.parseInt(raw, 10);
  if (!Number.isSafeInteger(parsed) || parsed < 0) {
    throw new CliInputError(`--${name} must be a non-negative integer (received: "${raw}")`);
  }
  return parsed;
}

function parsePlainJsonObject(
  raw: string,
  label: string,
  redact = true
): Record<string, unknown> {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (err) {
    throw new CliInputError(
      `Invalid JSON for ${label}: ${err instanceof Error ? err.message : String(err)}`
    );
  }
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    throw new CliInputError(`${label} must be a JSON object.`);
  }
  return (redact ? redactObjectDeep(parsed) : parsed) as Record<string, unknown>;
}

function printOutput(data: unknown, asJson: boolean): void {
  if (asJson) {
    process.stdout.write(JSON.stringify(data, null, 2) + '\n');
  } else if (typeof data === 'string') {
    process.stdout.write(data + '\n');
  } else {
    process.stdout.write(JSON.stringify(data, null, 2) + '\n');
  }
}

function printError(message: string, asJson: boolean): void {
  const safe = redactSecrets(message);
  if (asJson) {
    process.stderr.write(JSON.stringify({ error: safe }) + '\n');
  } else {
    console.error(safe);
  }
}

function requireInitialized(agent: NumberOneAgent, workspace: string, asJson: boolean): boolean {
  if (!agent.store.isInitialized()) {
    printError(`Number One is not attached to ${workspace}. Run: n1 attach`, asJson);
    return false;
  }
  return true;
}

function printHelp(): void {
  process.stdout.write(`
Number One (n1) v${getPackageVersion()} — Harness-Agnostic Event-Sourced Workspace Curator & Bridge Crew

USAGE:
  n1 <command> [options]

CORE WORKSPACE & STREAM COMMANDS:
  attach [path]          Attach Number One to a workspace (.numberone/, Git hooks, shims)
  status                 Show stream position, watcher daemon, KPIs, and sync summary
  doctor                 Diagnose toolchain, stream integrity, daemon, and persistence config
  watch [--foreground]   Watch workspace filesystem changes in real time (or 'watch stop')
  reconcile              Detect & record offline manual file edits since last projection
  exec [--timeout-ms N] -- <command> [args...]
                         Run a command while recording crashes/logs & auto-capturing fix lessons
  replay [--until-seq N] Deterministically rebuild workspace state from atomic stream events
  documentary [--out F]  Generate chronological Workspace Documentary markdown
  verify [--local-only]  Verify cryptographic hash chain, fallback blobs, and remote mirrors

INSTITUTIONAL MEMORY & AUTHORITY COMMANDS:
  brief                  Print Number One's authoritative System of Record (SoR) brief
  consult --intent "..." Query lessons learned, failed attempts, and active directives
  arbitrate --action ... Submit a proposed plan/action for authoritative Number One verdict
  think "<thought>"      Record intermediate AI/human thinking into the stream
  dead-end --approach .. Record a failed approach so it is never retried across sessions
  lesson --title ...     Capture a durable Lesson Learned
  decision --title ...   Record an Architecture/Process Decision (ADR)
  directive --title ...  Issue an authoritative Number One directive superseding local context
  issue open|resolve     Track Scrum issues synced with .numberone / GitHub / Jira
  record --type ...      Append any atomic event directly to the stream
  ingest <file>          Ingest JSONL/Markdown transcripts from any AI harness

BRIDGE CREW (BMAD PARTY MODE) & CONTINUOUS EVOLUTION:
  party --topic "..."    Convene Bridge Crew roundtable (Round 1 Audit, Round 2 Challenge Verification,
                         SoR Precedent Correlation, Decision Matrix & Ranked Remediation Plan)
  officer <role>         Invoke single specialist officer (engineering | security | bridge)
  evolve --file <json> [--allow-exec]
                         Submit a factually-proven KPI-gated expertise update proposal
  evolve audit <role> [--threshold N] [--force]
                         Audit officer KPI history for broken-practice regressions
  evolve revert <role> <practiceId> [--reason "..."]
                         Revert an evolved officer practice

DISTRIBUTED PERSISTENCE & HARNESS INTEGRATION:
  sync [push|pull|both]  Sync distributed stream with GitHub Issues/Projects v2 & Jira Scrum
  shims                  Install/refresh AGENTS.md, CLAUDE.md, Cursor, Copilot, and .mcp.json
  shell-hook [bash|zsh]  Print shell hook for capturing terminal crashes automatically
  mcp                    Start JSON-RPC 2.0 MCP Server on stdio for any AI harness

GLOBAL OPTIONS:
  --workspace <path>     Target workspace directory (defaults to current working directory)
  --json                 Emit machine-readable JSON output
  --version, -v          Print Number One version
  --help, -h             Show this help message
`);
}

export async function runCli(argv: string[]): Promise<number> {
  const wantsJson = argv.includes('--json') || argv.includes('--json=true');
  let parsed: ParsedArgs;
  try {
    parsed = parseCliArgs(argv);
  } catch (err) {
    printError(err instanceof Error ? err.message : String(err), wantsJson);
    return 1;
  }

  try {
    return await executeCliCommand(parsed);
  } catch (err) {
    if (err instanceof CliInputError) {
      printError(err.message, flagBool(parsed.flags, 'json'));
      return 1;
    }
    throw err;
  }
}

async function executeCliCommand(parsed: ParsedArgs): Promise<number> {
  const { command, positionals, flags, passthrough } = parsed;
  const asJson = flagBool(flags, 'json');

  if (flagBool(flags, 'version') || command === 'version') {
    const version = getPackageVersion();
    printOutput(asJson ? { name: 'numberone', version } : version, asJson);
    return 0;
  }

  if (flagBool(flags, 'help') || command === 'help') {
    printHelp();
    return 0;
  }

  const workspace = path.resolve(
    flagStr(flags, 'workspace') ?? (command === 'attach' && positionals[0] ? positionals[0] : process.cwd())
  );
  const agent = new NumberOneAgent(workspace);

  switch (command) {
    case 'attach': {
      const backfill = parseNonNegativeIntFlag(flagStr(flags, 'backfill'), 'backfill', 25);
      const res = agent.attach({
        workspaceName: flagStr(flags, 'name'),
        installHooks: !flagBool(flags, 'no-hooks'),
        installShims: !flagBool(flags, 'no-shims'),
        backfillGitCommits: backfill,
        harness: flagStr(flags, 'harness') ?? 'cli'
      });
      if (asJson) {
        printOutput(res, true);
      } else {
        console.log(`Attached Number One to ${workspace}`);
        console.log(`  Stream: .numberone/stream/events/ (seq #${res.attachedEvent.seq})`);
        console.log(`  Indexed files: ${res.initialFilesIndexed}`);
        console.log(`  Git hooks installed: ${res.gitHooksInstalled.join(', ') || 'none'}`);
        console.log(`  Git commits backfilled: ${res.gitCommitsBackfilled}`);
        console.log(`  Harness shims updated: ${res.shimsInstalled.join(', ') || 'none'}`);
      }
      return 0;
    }

    case 'status': {
      if (!requireInitialized(agent, workspace, asJson)) return 1;
      const state = agent.getState();
      const head = agent.store.getHead();
      const daemonStatus = agent.daemon.getStatus();
      const summary = {
        workspaceRoot: workspace,
        head,
        daemon: daemonStatus,
        harnessesSeen: state.harnessesSeen,
        counts: {
          filesTracked: Object.keys(state.files).length,
          lessons: Object.keys(state.lessons).length,
          decisions: Object.keys(state.decisions).length,
          activeDirectives: Object.values(state.directives).filter((d) => d.active).length,
          openIssues: Object.values(state.issues).filter((i) => i.status !== 'resolved').length,
          unresolvedCrashes: state.crashes.filter((c) => !c.resolvedByEventId).length,
          partySessions: Object.keys(state.partySessions).length
        },
        officerKpis: {
          engineering: state.officers.engineering.currentKpiScore,
          security: state.officers.security.currentKpiScore,
          bridge: state.officers.bridge.currentKpiScore
        },
        syncState: state.syncState
      };
      printOutput(summary, asJson);
      return 0;
    }

    case 'doctor': {
      const initialized = agent.store.isInitialized();
      let gitVersion: string | null = null;
      try {
        gitVersion = execFileSync('git', ['--version'], {
          encoding: 'utf8',
          stdio: ['ignore', 'pipe', 'ignore']
        }).trim();
      } catch {
        gitVersion = null;
      }
      const inGitRepo = isGitRepository(workspace);
      const localIntegrity = initialized ? agent.store.verifyIntegrity() : null;
      const daemon = initialized ? agent.daemon.getStatus() : null;
      const config = initialized ? agent.store.readConfig() : null;
      const backends = {
        directory: Boolean(config?.persistence.directory?.enabled),
        github: {
          enabled: Boolean(config?.persistence.github?.enabled),
          tokenPresent: Boolean(
            config?.persistence.github?.tokenEnvVar
              ? process.env[config.persistence.github.tokenEnvVar]
              : process.env.GITHUB_TOKEN || process.env.GH_TOKEN
          )
        },
        jira: {
          enabled: Boolean(config?.persistence.jira?.enabled),
          credentialsPresent: Boolean(
            (config?.persistence.jira?.emailEnvVar
              ? process.env[config.persistence.jira.emailEnvVar]
              : process.env.JIRA_EMAIL) &&
              (config?.persistence.jira?.apiTokenEnvVar
                ? process.env[config.persistence.jira.apiTokenEnvVar]
                : process.env.JIRA_API_TOKEN)
          )
        }
      };

      const healthy = !initialized || Boolean(localIntegrity?.valid);
      const report = {
        version: getPackageVersion(),
        nodeVersion: process.versions.node,
        platform: process.platform,
        workspaceRoot: workspace,
        initialized,
        gitAvailable: Boolean(gitVersion),
        gitVersion,
        isGitRepository: inGitRepo,
        streamIntegrity: localIntegrity,
        daemon,
        backends,
        healthy
      };
      printOutput(report, asJson);
      return healthy ? 0 : 2;
    }

    case 'watch': {
      if (positionals[0] === 'stop') {
        const res = agent.daemon.stop();
        printOutput(res, asJson);
        return 0;
      }
      if (!agent.store.isInitialized()) agent.attach({ installShims: false });

      if (flagBool(flags, 'foreground')) {
        const watcher = agent.createWatcher({
          persistent: true,
          onEvent: (ev) => {
            if (asJson) {
              process.stdout.write(JSON.stringify(ev) + '\n');
            } else {
              console.log(`[#${ev.seq}] ${ev.type}: ${ev.summary}`);
            }
          }
        });
        const offline = watcher.reconcileOfflineChanges(agent.getState());
        if (!asJson && offline.length > 0) {
          console.log(`Reconciled ${offline.length} offline file change(s).`);
        }
        watcher.start();
        if (!asJson) console.log(`Number One watching ${workspace}... (Ctrl+C to stop)`);

        await new Promise<void>((resolve) => {
          const keepAlive = setInterval(() => {
            // Keeps event loop alive even if all subdir watchers temporarily close
          }, 60_000);
          const shutdown = () => {
            clearInterval(keepAlive);
            process.removeListener('SIGINT', shutdown);
            process.removeListener('SIGTERM', shutdown);
            watcher.stop(true);
            resolve();
          };
          process.on('SIGINT', shutdown);
          process.on('SIGTERM', shutdown);
        });
        return 0;
      }

      const thisFile = fileURLToPath(import.meta.url);
      const status = agent.daemon.startDetached(thisFile);
      printOutput(status, asJson);
      return 0;
    }

    case 'reconcile': {
      if (!requireInitialized(agent, workspace, asJson)) return 1;
      const events = agent.reconcileOfflineChanges();
      printOutput({ reconciledCount: events.length, events }, asJson);
      return 0;
    }

    case 'exec': {
      const useDirectArgv = passthrough.length > 0;
      const cmdParts = useDirectArgv ? passthrough : positionals;
      const cmd = cmdParts.join(' ').trim();
      if (!cmd) {
        printError('Usage: n1 exec [--timeout-ms N] -- <command> [args...]', asJson);
        return 1;
      }
      const timeoutMs = parsePositiveIntFlag(flagStr(flags, 'timeout-ms'), 'timeout-ms');
      const res = await agent.runCommand({
        command: cmd,
        argv: useDirectArgv ? passthrough : undefined,
        harness: flagStr(flags, 'harness') ?? 'cli',
        sessionId: flagStr(flags, 'session'),
        tags: flagList(flags, 'tags'),
        silent: asJson,
        timeoutMs
      });
      if (asJson) {
        printOutput(
          {
            exitCode: res.exitCode,
            signal: res.signal,
            timedOut: res.timedOut,
            durationMs: res.durationMs,
            endEventId: res.endEvent.id,
            autoCapturedLessonId: res.autoCapturedLesson?.id ?? null
          },
          true
        );
      } else if (res.autoCapturedLesson) {
        console.log(`\n[Number One] Auto-captured verified Lesson Learned: ${res.autoCapturedLesson.summary}`);
      }
      return res.exitCode ?? 1;
    }

    case 'think': {
      const thought = flagStr(flags, 'thought') ?? positionals.join(' ');
      if (!thought) {
        printError('Usage: n1 think "<thought>"', asJson);
        return 1;
      }
      const ev = agent.recordThinking({
        thought,
        harness: flagStr(flags, 'harness') ?? 'cli',
        sessionId: flagStr(flags, 'session'),
        affectedPaths: flagList(flags, 'paths'),
        tags: flagList(flags, 'tags')
      });
      printOutput(ev, asJson);
      return 0;
    }

    case 'dead-end': {
      const approach = flagStr(flags, 'approach') ?? positionals[0] ?? '';
      const reason = flagStr(flags, 'reason') ?? positionals.slice(1).join(' ') ?? 'Did not work';
      if (!approach) {
        printError('Usage: n1 dead-end --approach "..." --reason "..."', asJson);
        return 1;
      }
      const ev = agent.recordFailedAttempt({
        approach,
        reason,
        harness: flagStr(flags, 'harness') ?? 'cli',
        affectedPaths: flagList(flags, 'paths'),
        tags: flagList(flags, 'tags')
      });
      printOutput(ev, asJson);
      return 0;
    }

    case 'lesson': {
      const title = flagStr(flags, 'title');
      if (!title) {
        printError(
          'Usage: n1 lesson --title "..." --problem "..." --root-cause "..." --resolution "..." --prevention "..."',
          asJson
        );
        return 1;
      }
      const severity = assertEnumFlag<'low' | 'medium' | 'high' | 'critical'>(
        flagStr(flags, 'severity'),
        VALID_SEVERITIES,
        'severity',
        'medium'
      );
      const ev = agent.captureLesson({
        title,
        problem: flagStr(flags, 'problem') ?? title,
        rootCause: flagStr(flags, 'root-cause') ?? 'Documented root cause',
        resolution: flagStr(flags, 'resolution') ?? '',
        preventionRule: flagStr(flags, 'prevention') ?? flagStr(flags, 'resolution') ?? title,
        failedApproaches: flagList(flags, 'failed'),
        errorSignatures: flagList(flags, 'error-sig'),
        affectedPaths: flagList(flags, 'paths'),
        tags: flagList(flags, 'tags'),
        severity,
        harness: flagStr(flags, 'harness') ?? 'cli'
      });
      printOutput(ev, asJson);
      return 0;
    }

    case 'decision': {
      const title = flagStr(flags, 'title');
      if (!title) {
        printError('Usage: n1 decision --title "..." --decision "..." --rationale "..."', asJson);
        return 1;
      }
      const ev = agent.recordDecision({
        title,
        decision: flagStr(flags, 'decision') ?? title,
        rationale: flagStr(flags, 'rationale') ?? '',
        alternativesRejected: flagList(flags, 'rejected'),
        consequences: flagList(flags, 'consequences'),
        affectedPaths: flagList(flags, 'paths'),
        tags: flagList(flags, 'tags'),
        harness: flagStr(flags, 'harness') ?? 'cli'
      });
      printOutput(ev, asJson);
      return 0;
    }

    case 'directive': {
      const title = flagStr(flags, 'title');
      const directive = flagStr(flags, 'directive');
      if (!title || !directive) {
        printError('Usage: n1 directive --title "..." --directive "..." --rationale "..."', asJson);
        return 1;
      }
      const severity = assertEnumFlag<'advisory' | 'mandatory' | 'blocking'>(
        flagStr(flags, 'severity'),
        VALID_DIRECTIVE_SEVERITIES,
        'severity',
        'mandatory'
      );
      const ev = agent.issueDirective({
        title,
        directive,
        rationale: flagStr(flags, 'rationale') ?? 'Authoritative Number One directive',
        scopePaths: flagList(flags, 'paths'),
        scopeTags: flagList(flags, 'tags'),
        forbiddenPatterns: flagList(flags, 'forbid'),
        requiredPatterns: flagList(flags, 'require'),
        severity,
        harness: flagStr(flags, 'harness') ?? 'cli'
      });
      printOutput(ev, asJson);
      return 0;
    }

    case 'issue': {
      const sub = positionals[0] ?? 'list';
      if (sub === 'open') {
        const title = flagStr(flags, 'title');
        if (!title) {
          printError('Usage: n1 issue open --title "..." [--kind bug|story|task|security|infra|release]', asJson);
          return 1;
        }
        const kind = assertEnumFlag<
          'bug' | 'crash' | 'story' | 'epic' | 'task' | 'debt' | 'security' | 'infra' | 'release'
        >(flagStr(flags, 'kind'), VALID_ISSUE_KINDS, 'kind', 'task');
        const priority = assertEnumFlag<'low' | 'medium' | 'high' | 'critical'>(
          flagStr(flags, 'priority'),
          VALID_SEVERITIES,
          'priority',
          'medium'
        );
        const officerRaw = flagStr(flags, 'officer');
        const ownerOfficer = officerRaw
          ? assertEnumFlag<OfficerRole>(officerRaw, VALID_OFFICERS, 'officer', 'engineering')
          : undefined;
        const ev = agent.openIssue({
          title,
          description: flagStr(flags, 'description') ?? title,
          kind,
          priority,
          ownerOfficer,
          affectedPaths: flagList(flags, 'paths'),
          tags: flagList(flags, 'tags')
        });
        printOutput(ev, asJson);
        return 0;
      }
      if (sub === 'resolve') {
        const issueId = positionals[1] ?? flagStr(flags, 'id');
        if (!issueId) {
          printError('Usage: n1 issue resolve <issueId> --resolution "..."', asJson);
          return 1;
        }
        const ev = agent.resolveIssue(issueId, flagStr(flags, 'resolution') ?? 'Resolved');
        printOutput(ev, asJson);
        return 0;
      }
      if (!requireInitialized(agent, workspace, asJson)) return 1;
      const state = agent.getState();
      printOutput(Object.values(state.issues), asJson);
      return 0;
    }

    case 'record': {
      const typeRaw = flagStr(flags, 'type');
      const summary = flagStr(flags, 'summary');
      if (!typeRaw || !summary) {
        printError('Usage: n1 record --type <EventType> --summary "..." [--payload \'{"k":"v"}\']', asJson);
        return 1;
      }
      if (!VALID_EVENT_TYPE_SET.has(typeRaw)) {
        throw new CliInputError(
          `Unknown event type "${typeRaw}". Valid types include: ${EVENT_TYPES.slice(0, 8).join(', ')}, ...`
        );
      }
      const type = typeRaw as EventType;
      const payloadRaw = flagStr(flags, 'payload');
      const payload = payloadRaw ? parsePlainJsonObject(payloadRaw, '--payload') : {};
      const ev = agent.recordEvent({
        type,
        actor: { kind: 'human', id: flagStr(flags, 'actor') ?? process.env.USER ?? 'operator' },
        harness: flagStr(flags, 'harness') ?? 'cli',
        sessionId: flagStr(flags, 'session'),
        summary,
        affectedPaths: flagList(flags, 'paths'),
        tags: flagList(flags, 'tags'),
        payload
      });
      printOutput(ev, asJson);
      return 0;
    }

    case 'brief': {
      if (!requireInitialized(agent, workspace, asJson)) return 1;
      const brief = agent.getAuthoritativeBrief(flagList(flags, 'paths'));
      printOutput(asJson ? { brief } : brief, asJson);
      return 0;
    }

    case 'consult': {
      if (!requireInitialized(agent, workspace, asJson)) return 1;
      const res = agent.consult({
        intent: flagStr(flags, 'intent') ?? positionals.join(' '),
        targetPaths: flagList(flags, 'paths'),
        errorText: flagStr(flags, 'error'),
        command: flagStr(flags, 'command'),
        tags: flagList(flags, 'tags')
      });
      printOutput(res, asJson);
      return 0;
    }

    case 'arbitrate': {
      const action = flagStr(flags, 'action') ?? positionals.join(' ');
      if (!action) {
        printError('Usage: n1 arbitrate --action "..." --intent "..." [--approach "..."] [--paths a,b]', asJson);
        return 1;
      }
      const res = agent.arbitrate(
        {
          action,
          intent: flagStr(flags, 'intent') ?? action,
          proposedApproach: flagStr(flags, 'approach'),
          command: flagStr(flags, 'command'),
          targetPaths: flagList(flags, 'paths'),
          tags: flagList(flags, 'tags'),
          harness: flagStr(flags, 'harness') ?? 'cli'
        },
        { recordAuditEvent: !flagBool(flags, 'dry-run') }
      );
      if (asJson) {
        printOutput(res, true);
      } else {
        console.log(res.authoritativeSummary);
      }
      return res.verdict === 'BLOCK' ? 2 : 0;
    }

    case 'replay': {
      if (!requireInitialized(agent, workspace, asJson)) return 1;
      const untilSeq = parsePositiveIntFlag(flagStr(flags, 'until-seq'), 'until-seq');
      const untilTimestamp = flagStr(flags, 'until-time');
      const state = agent.replay({
        untilSeq,
        untilTimestamp,
        persistSnapshot: untilSeq === undefined && !untilTimestamp
      });
      printOutput(state, asJson);
      return 0;
    }

    case 'documentary': {
      if (!requireInitialized(agent, workspace, asJson)) return 1;
      const doc = agent.buildDocumentary();
      const outPath = flagStr(flags, 'out');
      if (outPath) {
        const resolvedOut = path.resolve(outPath);
        atomicWriteFileSync(resolvedOut, doc.markdown);
        printOutput({ writtenTo: resolvedOut, chapters: doc.chapters.length }, asJson);
      } else {
        printOutput(asJson ? doc : doc.markdown, asJson);
      }
      return 0;
    }

    case 'party': {
      const topic = flagStr(flags, 'topic') ?? (positionals.join(' ') || 'Full Workspace Review');
      const rawOfficers = flagList(flags, 'officers');
      for (const o of rawOfficers) {
        if (!VALID_OFFICERS.has(o)) {
          throw new CliInputError(`Invalid officer "${o}" in --officers. Allowed: engineering, security, bridge`);
        }
      }
      const officers = rawOfficers as OfficerRole[];
      const mode = assertEnumFlag<'roundtable' | 'specialist' | 'auto-triage'>(
        flagStr(flags, 'mode'),
        VALID_PARTY_MODES,
        'mode',
        'roundtable'
      );
      const res = await agent.assembleCrew({
        topic,
        mode,
        officers: officers.length > 0 ? officers : undefined,
        targetPaths: flagList(flags, 'paths'),
        harness: flagStr(flags, 'harness') ?? 'cli'
      });
      if (asJson) {
        printOutput(res, true);
      } else {
        console.log(`Crew Session: ${res.partySessionId} | Mode: ${res.mode} | Topic: ${res.topic}`);
        console.log(`Officers: ${res.assembledOfficers.join(', ')}\n`);
        console.log('Decision Matrix:');
        for (const row of res.decisionMatrix) {
          console.log(
            `  - [${row.domainGate}] ${row.officerTitle}: ${row.mainKpiName}=${row.kpiScore}/100 (${row.checksPassed}/${row.checksApplicable} checks, ${row.blockingCount} blocker(s))`
          );
        }
        if (res.remediationPlan.length > 0) {
          console.log('\nRanked Remediation Plan:');
          for (const item of res.remediationPlan.slice(0, 8)) {
            console.log(
              `  #${item.rank} [${item.ownerOfficer}/${item.severity}${item.blocksRelease ? '/BLOCKING' : ''}] ${item.title}`
            );
            console.log(`      Action: ${item.action}`);
          }
        }
        console.log('\nRoundtable Log:');
        for (const t of res.roundtableTranscript) {
          console.log(`[Round ${t.round} | ${t.speaker} | ${t.kind}] ${t.message}`);
        }
      }
      return res.consensusReached ? 0 : 2;
    }

    case 'officer': {
      const role = positionals[0] as OfficerRole | undefined;
      if (!role || !VALID_OFFICERS.has(role)) {
        printError('Usage: n1 officer <engineering|security|bridge> [--topic "..."]', asJson);
        return 1;
      }
      const res = agent.assessOfficer(role, flagStr(flags, 'topic'), flagList(flags, 'paths'));
      printOutput(res, asJson);
      return 0;
    }

    case 'evolve': {
      const sub = positionals[0];
      if (sub === 'audit') {
        if (!requireInitialized(agent, workspace, asJson)) return 1;
        const role = positionals[1] as OfficerRole | undefined;
        if (!role || !VALID_OFFICERS.has(role)) {
          printError('Usage: n1 evolve audit <engineering|security|bridge> [--threshold N] [--force]', asJson);
          return 1;
        }
        const threshold = parsePositiveIntFlag(flagStr(flags, 'threshold'), 'threshold') ?? 5;
        const revertedIds = agent.auditOfficerRegressions(role, threshold, {
          forceRevertOnStrictnessDrop: flagBool(flags, 'force')
        });
        printOutput({ officer: role, threshold, revertedPracticeIds: revertedIds }, asJson);
        return 0;
      }
      if (sub === 'revert') {
        if (!requireInitialized(agent, workspace, asJson)) return 1;
        const role = positionals[1] as OfficerRole | undefined;
        const practiceId = positionals[2] ?? flagStr(flags, 'practice');
        if (!role || !VALID_OFFICERS.has(role) || !practiceId) {
          printError('Usage: n1 evolve revert <engineering|security|bridge> <practiceId> [--reason "..."]', asJson);
          return 1;
        }
        const reason = flagStr(flags, 'reason') ?? 'Manually reverted via CLI';
        const eventId = agent.revertOfficerPractice(role, practiceId, reason);
        printOutput({ officer: role, practiceId, reverted: true, eventId }, asJson);
        return 0;
      }

      const file = flagStr(flags, 'file') ?? positionals[0];
      if (!file) {
        printError('Usage: n1 evolve --file <proposal.json> [--allow-exec]', asJson);
        return 1;
      }
      const resolvedFile = path.resolve(file);
      const rawJson = readTextFileSafe(resolvedFile, 5_000_000);
      if (rawJson === null) {
        throw new CliInputError(`Proposal file not found or unreadable regular file: ${resolvedFile}`);
      }
      // Do NOT redact proposal test fixtures before matcher verification
      const proposal = parsePlainJsonObject(
        rawJson,
        resolvedFile,
        false
      ) as unknown as KnowledgeUpdateProposal;
      const verdict = agent.proposeKnowledgeUpdate(proposal, {
        allowCommandExecution: flagBool(flags, 'allow-exec')
      });
      printOutput(verdict, asJson);
      return verdict.accepted ? 0 : 2;
    }

    case 'sync': {
      if (!requireInitialized(agent, workspace, asJson)) return 1;
      const dir = positionals[0] ?? 'both';
      if (dir !== 'push' && dir !== 'pull' && dir !== 'both') {
        throw new CliInputError(`Invalid sync direction "${dir}". Expected push, pull, or both.`);
      }
      const push = dir === 'push' || dir === 'both' ? await agent.syncPush() : [];
      const pull = dir === 'pull' || dir === 'both' ? await agent.syncPull() : [];
      printOutput({ push, pull }, asJson);
      const hasErrors =
        push.some((r) => r.errors.length > 0) || pull.some((r) => r.errors.length > 0);
      return hasErrors ? 2 : 0;
    }

    case 'verify': {
      if (!requireInitialized(agent, workspace, asJson)) return 1;
      const report = await agent.verifyIntegrity(!flagBool(flags, 'local-only'));
      printOutput(report, asJson);
      return report.valid ? 0 : 2;
    }

    case 'ingest': {
      const file = positionals[0] ?? flagStr(flags, 'file');
      if (!file) {
        printError('Usage: n1 ingest <transcript.jsonl|notes.md> [--harness claude-code]', asJson);
        return 1;
      }
      const res = agent.ingestTranscript({
        filePath: file,
        harness: flagStr(flags, 'harness'),
        sessionId: flagStr(flags, 'session')
      });
      printOutput(res, asJson);
      return 0;
    }

    case 'git-hook': {
      const hook = positionals[0];
      if (!hook || !VALID_GIT_HOOKS.has(hook)) return 1;
      const hookArgs = passthrough.length > 0 ? passthrough : positionals.slice(1);
      const ev = recordGitHookEvent(agent.store, hook as SupportedGitHook, hookArgs);
      if (asJson) printOutput(ev, true);
      return 0;
    }

    case 'record-shell-failure': {
      const cmdRaw = process.env.N1_SHELL_CMD ?? flagStr(flags, 'command') ?? '';
      const exitCodeRaw = process.env.N1_SHELL_EXIT ?? flagStr(flags, 'exit-code') ?? '1';
      const shellName = process.env.N1_SHELL_NAME ?? 'shell';
      if (!cmdRaw) return 0;
      const cmd = redactSecrets(cmdRaw);
      const exitCode = Number.parseInt(exitCodeRaw, 10);
      const ev = agent.recordEvent({
        type: exitCode >= 128 ? 'exec.crashed' : 'exec.failed',
        actor: { kind: 'human', id: process.env.USER ?? 'operator' },
        harness: shellName,
        summary: `Command failed (exit ${exitCode}): ${cmd.slice(0, 140)}`,
        tags: ['exec', 'shell-hook', exitCode >= 128 ? 'crash' : 'failure'],
        payload: {
          command: cmd,
          exitCode: Number.isFinite(exitCode) ? exitCode : 1
        }
      });
      if (asJson) printOutput(ev, true);
      return 0;
    }

    case 'shell-hook': {
      const shell = positionals[0] === 'zsh' ? 'zsh' : 'bash';
      process.stdout.write(generateShellHook(shell) + '\n');
      return 0;
    }

    case 'shims': {
      const name = agent.store.readConfig()?.workspaceName ?? path.basename(workspace);
      const res = installHarnessShims(workspace, name);
      printOutput(res, asJson);
      return 0;
    }

    case 'mcp': {
      const server = new NumberOneMcpServer(agent);
      await server.startStdio();
      return 0;
    }

    default:
      printError(`Unknown command: ${command}`, asJson);
      if (!asJson) printHelp();
      return 1;
  }
}

function isInvokedAsCli(): boolean {
  const invoked = process.argv[1];
  if (!invoked) return false;
  const base = path.basename(invoked);
  if (base === 'numberone' || base === 'n1') return true;
  try {
    const invokedReal = fs.realpathSync(invoked);
    const selfReal = fs.realpathSync(fileURLToPath(import.meta.url));
    return invokedReal === selfReal;
  } catch {
    return path.resolve(invoked) === fileURLToPath(import.meta.url);
  }
}

if (isInvokedAsCli()) {
  runCli(process.argv.slice(2))
    .then((code) => {
      if (code !== 0) process.exitCode = code;
    })
    .catch((err) => {
      const wantsJson = process.argv.includes('--json') || process.argv.includes('--json=true');
      printError(err instanceof Error ? err.message : String(err), wantsJson);
      process.exitCode = 1;
    });
}

import path from 'node:path';
import { LessonEngine, LessonMatch } from './lesson-engine.js';
import { StreamStore } from './stream-store.js';
import {
  DecisionRecord,
  DirectiveRecord,
  StreamEvent,
  WorkspaceProjection
} from './types.js';
import { compileSafeRegex, matchGlobLinear, MAX_REGEX_INPUT_LENGTH } from '../utils/safe-regex.js';

export type AuthorityLevel =
  | 'L1_SOR_INVARIANT'
  | 'L2_NUMBER_ONE_DIRECTIVE'
  | 'L3_OFFICER_GATE'
  | 'L4_SESSION_CONTEXT';

export type ArbitrationVerdict = 'APPROVE' | 'APPROVE_WITH_CONDITIONS' | 'OVERRIDE' | 'BLOCK';

export interface ArbitrationProposal {
  action: string;
  intent: string;
  targetPaths?: string[];
  command?: string;
  proposedApproach?: string;
  sessionAssumptions?: string[];
  tags?: string[];
  harness?: string;
  sessionId?: string;
}

export interface AuthorityConflict {
  level: AuthorityLevel;
  sourceType: 'directive' | 'lesson' | 'failed_attempt' | 'decision';
  sourceId: string;
  eventId: string;
  severity: 'advisory' | 'mandatory' | 'blocking';
  message: string;
  authoritativeGuidance: string;
}

export interface ArbitrationResult {
  verdict: ArbitrationVerdict;
  supersedesSessionContext: boolean;
  precedenceOrder: AuthorityLevel[];
  conflicts: AuthorityConflict[];
  relevantLessons: LessonMatch[];
  applicableDirectives: DirectiveRecord[];
  applicableDecisions: DecisionRecord[];
  authoritativeSummary: string;
  recordedEvent?: StreamEvent;
}

function normalizeScopePath(p: string): string {
  const posix = p.replace(/\\/g, '/');
  const norm = path.posix.normalize(posix).replace(/^\.\//, '').replace(/^\/+/, '');
  return norm === '.' ? '' : norm;
}

function pathMatchesScope(targetPath: string, scopePath: string): boolean {
  const t = normalizeScopePath(targetPath);
  const s = normalizeScopePath(scopePath);
  if (s === '*' || s === '') return true;
  if (t === s) return true;
  if (s.includes('*') || s.includes('?')) {
    return matchGlobLinear(t, s);
  }
  if (t.startsWith(s.endsWith('/') ? s : s + '/')) return true;
  return false;
}

const CONTRAST_SPLIT_RX =
  /(?=\b(?:instead\s+of|rather\s+than|as\s+opposed\s+to|not\s+using|without\b)\b)|\b(?:but\s+rather|whereas)\b/i;

const LEADING_NEGATION_RX =
  /^(?:do\s+not|don't|never|avoid|avoiding|instead\s+of|rather\s+than|as\s+opposed\s+to|without|forbid|prohibit|not\s+using|no\s+longer)\b/i;

const SWITCH_BACK_AFFIRMATIVE_RX = /\b(?:by\s+using|by\s+running|by\s+calling|by\s+enabling)\b/i;

/**
 * Extracts affirmative spans while preserving dotted identifiers (`0.0.0.0/0`, `child_process.exec`,
 * `package.json`), handling contrast phrases (`X instead of Y` -> keeps `X`, drops `Y`), and
 * preventing bypasses like `"Deploy with --no-verify without waiting"` or `"Avoid boilerplate by using eval()"`.
 */
export function extractAffirmativeClauses(text: string): string[] {
  // Split ONLY on real sentence boundaries (period followed by whitespace/EOL, semicolon, newline)
  const sentences = text
    .split(/(?:\.(?=\s|$)|[;\n])+/g)
    .map((s) => s.trim())
    .filter(Boolean);

  const affirmative: string[] = [];

  for (const sentence of sentences) {
    const contrastSpans = sentence
      .split(CONTRAST_SPLIT_RX)
      .map((s) => s.trim())
      .filter(Boolean);

    for (const span of contrastSpans) {
      if (LEADING_NEGATION_RX.test(span)) {
        // Check if negated prefix switches back to affirmative ("Avoid boilerplate by using eval(x)")
        const sw = SWITCH_BACK_AFFIRMATIVE_RX.exec(span);
        if (sw) {
          const tail = span.slice(sw.index + sw[0].length).trim();
          if (tail && !LEADING_NEGATION_RX.test(tail)) {
            affirmative.push(tail);
          }
        }
        continue;
      }
      affirmative.push(span);
    }
  }

  return affirmative;
}

function matchesPatternInAffirmativeText(fullText: string, pattern: string): boolean {
  if (!pattern) return false;
  const affirmative = extractAffirmativeClauses(fullText);
  if (affirmative.length === 0) return false;
  const safeRx = compileSafeRegex(pattern, 'i');
  return affirmative.some((clause) => {
    const bounded =
      clause.length > MAX_REGEX_INPUT_LENGTH ? clause.slice(0, MAX_REGEX_INPUT_LENGTH) : clause;
    if (safeRx) {
      return safeRx.test(bounded);
    }
    return bounded.toLowerCase().includes(pattern.toLowerCase());
  });
}

const STOP_WORDS = new Set([
  'the',
  'and',
  'for',
  'use',
  'with',
  'from',
  'that',
  'this',
  'into',
  'using',
  'used',
  'when',
  'where',
  'have',
  'will',
  'code',
  'file',
  'not',
  'run',
  'set',
  'add',
  'get'
]);

const SHORT_TECH_TOKENS = new Set(['db', 'rm', 'ci', 'cd', 'ip', 'ca', 'go', 'js', 'ts', 'py', 'sh']);

function extractSignificantTokens(phrase: string): string[] {
  const cleaned = phrase.replace(/\s*\(failed:[\s\S]*\)$/i, '');
  const raw = cleaned.toLowerCase().match(/[a-z0-9_.-]{2,}/g) ?? [];
  return raw.filter((w) => {
    if (STOP_WORDS.has(w)) return false;
    return w.length >= 3 || SHORT_TECH_TOKENS.has(w);
  });
}

/**
 * Checks whether any affirmative clause of the proposal proposes repeating a
 * historically failed approach.
 */
function affirmativelyRepeatsApproach(proposalText: string, failedApproach: string): boolean {
  const cleanedFailed = failedApproach.replace(/\s*\(failed:[\s\S]*\)$/i, '').trim();
  const targetTokens = extractSignificantTokens(cleanedFailed);
  if (targetTokens.length === 0) return false;

  const affirmativeClauses = extractAffirmativeClauses(proposalText);
  const normalizedFailed = cleanedFailed.toLowerCase();

  for (const clause of affirmativeClauses) {
    const lower = clause.toLowerCase();
    if (normalizedFailed.length >= 6 && lower.includes(normalizedFailed)) {
      return true;
    }
    const clauseTokens = new Set(extractSignificantTokens(clause));
    const matched = targetTokens.filter((t) => clauseTokens.has(t)).length;
    const required = targetTokens.length <= 2 ? targetTokens.length : Math.max(3, Math.ceil(targetTokens.length * 0.75));
    if (matched >= required) {
      return true;
    }
  }
  return false;
}

/**
 * Authoritative SoR Arbitration Engine.
 *
 * Precedence Ladder:
 *   L1: SoR Invariants & Verified Lessons Learned
 *   L2: Number One Authoritative Directives
 *   L3: Bridge Crew Officer Mandatory Gates
 *   L4: Current Ephemeral Session / Harness Context (lowest priority)
 */
export class AuthorityEngine {
  private readonly store: StreamStore;
  private readonly lessonEngine: LessonEngine;

  public static readonly PRECEDENCE: AuthorityLevel[] = [
    'L1_SOR_INVARIANT',
    'L2_NUMBER_ONE_DIRECTIVE',
    'L3_OFFICER_GATE',
    'L4_SESSION_CONTEXT'
  ];

  constructor(store: StreamStore, lessonEngine: LessonEngine) {
    this.store = store;
    this.lessonEngine = lessonEngine;
  }

  public arbitrate(
    state: WorkspaceProjection,
    proposal: ArbitrationProposal,
    options: { recordAuditEvent?: boolean } = {}
  ): ArbitrationResult {
    const conflicts: AuthorityConflict[] = [];
    const targetPaths = proposal.targetPaths ?? [];
    const approachAndCommand = [
      proposal.command ?? '',
      proposal.proposedApproach ?? '',
      ...(proposal.sessionAssumptions ?? [])
    ]
      .filter(Boolean)
      .join('\n');
    const fullProposalText = [proposal.action, proposal.intent, approachAndCommand]
      .filter(Boolean)
      .join('\n');

    const proposalTags = new Set((proposal.tags ?? []).map((t) => t.toLowerCase()));

    // 1. Check active authoritative directives (L2 / L3)
    const applicableDirectives: DirectiveRecord[] = [];
    for (const directive of Object.values(state.directives)) {
      if (!directive.active) continue;

      const hasPathScope = directive.scopePaths.length > 0;
      const hasTagScope = directive.scopeTags.length > 0;

      const pathMatch =
        hasPathScope &&
        targetPaths.some((tp) => directive.scopePaths.some((sp) => pathMatchesScope(tp, sp)));
      const tagMatch =
        hasTagScope &&
        directive.scopeTags.some((st) => proposalTags.has(st.toLowerCase()));

      // Global ONLY when both scopePaths and scopeTags are empty
      const inScope = (!hasPathScope && !hasTagScope) || pathMatch || tagMatch;

      if (inScope) {
        applicableDirectives.push(directive);

        for (const forbidden of directive.forbiddenPatterns) {
          if (matchesPatternInAffirmativeText(fullProposalText, forbidden)) {
            conflicts.push({
              level: directive.issuedBy === 'numberone' ? 'L2_NUMBER_ONE_DIRECTIVE' : 'L3_OFFICER_GATE',
              sourceType: 'directive',
              sourceId: directive.id,
              eventId: directive.eventId,
              severity: directive.severity,
              message: `Proposal violates active directive "${directive.title}" (matched forbidden pattern: ${forbidden}).`,
              authoritativeGuidance: directive.directive
            });
          }
        }

        if ((proposal.proposedApproach || proposal.command) && directive.requiredPatterns.length > 0) {
          for (const required of directive.requiredPatterns) {
            if (!matchesPatternInAffirmativeText(fullProposalText, required)) {
              conflicts.push({
                level: directive.issuedBy === 'numberone' ? 'L2_NUMBER_ONE_DIRECTIVE' : 'L3_OFFICER_GATE',
                sourceType: 'directive',
                sourceId: directive.id,
                eventId: directive.eventId,
                severity: directive.severity === 'blocking' ? 'mandatory' : directive.severity,
                message: `Proposal omits required invariant from directive "${directive.title}" (missing: ${required}).`,
                authoritativeGuidance: directive.directive
              });
            }
          }
        }
      }
    }

    // 2. Check verified lessons learned & previously failed approaches (L1)
    const relevantLessons = this.lessonEngine.findRelevantLessons(state, {
      intent: `${proposal.action} ${proposal.intent} ${proposal.proposedApproach ?? ''}`,
      targetPaths,
      command: proposal.command,
      tags: proposal.tags
    });

    for (const match of relevantLessons) {
      const lesson = match.lesson;
      for (const failed of lesson.failedApproaches) {
        if (affirmativelyRepeatsApproach(fullProposalText, failed)) {
          conflicts.push({
            level: 'L1_SOR_INVARIANT',
            sourceType: 'lesson',
            sourceId: lesson.id,
            eventId: lesson.eventId,
            severity: lesson.severity === 'critical' ? 'blocking' : 'mandatory',
            message: `Proposed approach repeats failed approach recorded in lesson "${lesson.title}": "${failed}".`,
            authoritativeGuidance: `Apply verified resolution: ${lesson.resolution || lesson.preventionRule}`
          });
        }
      }
    }

    // 3. Check raw failed attempts history (L1)
    const relevantFailedAttempts = this.lessonEngine.findRelevantFailedAttempts(state, {
      intent: `${proposal.action} ${proposal.intent} ${proposal.proposedApproach ?? ''}`,
      targetPaths,
      command: proposal.command,
      tags: proposal.tags
    });
    for (const attempt of relevantFailedAttempts) {
      if (affirmativelyRepeatsApproach(fullProposalText, attempt.approach)) {
        conflicts.push({
          level: 'L1_SOR_INVARIANT',
          sourceType: 'failed_attempt',
          sourceId: attempt.eventId,
          eventId: attempt.eventId,
          severity: 'mandatory',
          message: `Proposal retries dead-end recorded at seq #${attempt.seq}: "${attempt.approach}" (failed: ${attempt.reason}).`,
          authoritativeGuidance: `Avoid dead-end from seq #${attempt.seq}.`
        });
      }
    }

    // 4. Find applicable active architectural decisions
    const applicableDecisions = Object.values(state.decisions).filter((d) => {
      if (d.status !== 'active') return false;
      const pathHit =
        d.affectedPaths.length > 0 &&
        targetPaths.some((tp) => d.affectedPaths.some((dp) => pathMatchesScope(tp, dp)));
      const tagHit = d.tags.some((t) => proposalTags.has(t.toLowerCase()));
      return pathHit || tagHit;
    });

    const hasBlocking = conflicts.some((c) => c.severity === 'blocking');
    const hasMandatory = conflicts.some((c) => c.severity === 'mandatory');
    const hasAdvisory = conflicts.some((c) => c.severity === 'advisory');

    let verdict: ArbitrationVerdict = 'APPROVE';
    if (hasBlocking) {
      verdict = 'BLOCK';
    } else if (hasMandatory) {
      verdict = 'OVERRIDE';
    } else if (hasAdvisory || applicableDirectives.length > 0) {
      verdict = 'APPROVE_WITH_CONDITIONS';
    }

    const supersedesSessionContext = verdict === 'BLOCK' || verdict === 'OVERRIDE';

    const authoritativeSummary = this.formatVerdictSummary(
      verdict,
      conflicts,
      relevantLessons.slice(0, 5),
      applicableDirectives
    );

    let recordedEvent: StreamEvent | undefined;
    if (options.recordAuditEvent) {
      recordedEvent = this.store.append({
        type: 'arbitration.decided',
        actor: { kind: 'numberone', id: 'numberone', name: 'Number One' },
        harness: proposal.harness ?? 'cli',
        sessionId: proposal.sessionId,
        summary: `[${verdict}] Arbitrated "${proposal.action}" (${conflicts.length} conflict(s))`,
        affectedPaths: targetPaths,
        tags: Array.from(new Set(['arbitration', verdict.toLowerCase(), ...(proposal.tags ?? [])])),
        payload: {
          proposal,
          verdict,
          supersedesSessionContext,
          conflicts,
          matchedLessonIds: relevantLessons.slice(0, 5).map((m) => m.lesson.id),
          appliedDirectiveIds: applicableDirectives.map((d) => d.id)
        }
      });
    }

    return {
      verdict,
      supersedesSessionContext,
      precedenceOrder: AuthorityEngine.PRECEDENCE,
      conflicts,
      relevantLessons,
      applicableDirectives,
      applicableDecisions,
      authoritativeSummary,
      recordedEvent
    };
  }

  private formatVerdictSummary(
    verdict: ArbitrationVerdict,
    conflicts: AuthorityConflict[],
    lessons: LessonMatch[],
    directives: DirectiveRecord[]
  ): string {
    const lines: string[] = [
      `Verdict: ${verdict}`,
      `Precedence: ${AuthorityEngine.PRECEDENCE.join(' > ')}`
    ];

    if (conflicts.length > 0) {
      lines.push('', 'Conflicts (Session Context Superseded):');
      for (const c of conflicts) {
        lines.push(`- [${c.level} | ${c.severity}] ${c.message}`);
        lines.push(`  Guidance: ${c.authoritativeGuidance} (event: ${c.eventId})`);
      }
    }

    if (directives.length > 0) {
      lines.push('', 'Active Directives in Scope:');
      for (const d of directives) {
        lines.push(`- [${d.severity}] ${d.title}: ${d.directive}`);
      }
    }

    if (lessons.length > 0) {
      lines.push('', 'Relevant Lessons:');
      for (const m of lessons) {
        lines.push(
          `- ${m.lesson.title} (score ${m.score}): ${m.lesson.preventionRule} [Resolution: ${m.lesson.resolution}]`
        );
      }
    }

    return lines.join('\n');
  }

  public compileAuthoritativeBrief(state: WorkspaceProjection, focusPaths: string[] = []): string {
    const activeDirectives = Object.values(state.directives).filter((d) => d.active);
    const activeLessons = Object.values(state.lessons).filter((l) => !l.supersededBy);
    const openIssues = Object.values(state.issues).filter((i) => i.status !== 'resolved');
    const unresolvedCrashes = state.crashes.filter((c) => !c.resolvedByEventId);
    const activeDecisions = Object.values(state.decisions).filter((d) => d.status === 'active');

    const lines: string[] = [
      `# Number One — System of Record Brief`,
      '',
      `Precedence: SoR Invariants & Directives supersede local session context on conflict.`,
      '',
      `- Workspace: \`${state.workspaceRoot}\``,
      `- Stream Position: seq #${state.lastSeq} (\`${state.lastEventHash.slice(0, 12)}\`)`,
      `- Branch / Commit: \`${state.currentBranch ?? 'unknown'}\` @ \`${state.lastCommitSha?.slice(0, 8) ?? 'none'}\``,
      `- Files Tracked: ${Object.values(state.files).filter((f) => f.status === 'exists').length}`,
      `- Harnesses Observed: ${state.harnessesSeen.join(', ') || 'none'}`,
      `- Officer KPIs: Engineering=${state.officers.engineering.currentKpiScore ?? 'unmeasured'} | Security=${state.officers.security.currentKpiScore ?? 'unmeasured'} | Bridge=${state.officers.bridge.currentKpiScore ?? 'unmeasured'}`,
      ''
    ];

    if (activeDirectives.length > 0) {
      lines.push(`## Active Directives (${activeDirectives.length})`);
      for (const d of activeDirectives) {
        lines.push(`- **[${d.severity} | ${d.issuedBy}] ${d.title}**: ${d.directive}`);
        if (d.forbiddenPatterns.length > 0) {
          lines.push(`  - Forbidden: \`${d.forbiddenPatterns.join('`, `')}\``);
        }
      }
      lines.push('');
    }

    const relevantLessons =
      focusPaths.length > 0
        ? this.lessonEngine
            .findRelevantLessons(state, { targetPaths: focusPaths })
            .map((m) => m.lesson)
        : activeLessons.slice(-15);

    if (relevantLessons.length > 0) {
      lines.push(`## Lessons Learned (${relevantLessons.length}/${activeLessons.length})`);
      for (const l of relevantLessons) {
        lines.push(`- **${l.title}** [${l.severity}${l.verified ? ', verified' : ''}]`);
        lines.push(`  - Prevention Rule: ${l.preventionRule}`);
        if (l.failedApproaches.length > 0) {
          lines.push(`  - Failed Approaches: ${l.failedApproaches.join('; ')}`);
        }
      }
      lines.push('');
    }

    if (activeDecisions.length > 0) {
      lines.push(`## Active Decisions (${activeDecisions.length})`);
      for (const dec of activeDecisions.slice(-10)) {
        lines.push(`- **${dec.title}**: ${dec.decision} *(Rationale: ${dec.rationale})*`);
      }
      lines.push('');
    }

    if (unresolvedCrashes.length > 0) {
      lines.push(`## Unresolved Failures (${unresolvedCrashes.length})`);
      for (const c of unresolvedCrashes.slice(-5)) {
        lines.push(`- [seq #${c.seq}] \`${c.command}\` (exit ${c.exitCode ?? 'null'}): ${c.errorSignature}`);
      }
      lines.push('');
    }

    if (openIssues.length > 0) {
      lines.push(`## Open Issues (${openIssues.length})`);
      for (const issue of openIssues.slice(-10)) {
        lines.push(`- **[${issue.priority} | ${issue.kind}] ${issue.title}** (${issue.status})`);
      }
      lines.push('');
    }

    return lines.join('\n');
  }
}

import { StreamEvent, WorkspaceProjection } from './types.js';

export interface DocumentaryChapter {
  chapterNumber: number;
  sessionId: string;
  startedAt: string;
  endedAt: string;
  harnesses: string[];
  eventCount: number;
  highlights: string[];
  events: StreamEvent[];
}

export interface WorkspaceDocumentary {
  workspaceRoot: string;
  generatedAt: string;
  totalEvents: number;
  chapters: DocumentaryChapter[];
  markdown: string;
}

/**
 * Transforms the raw event-sourced stream into a human-readable chronological
 * "Documentary of the Workspace" spanning chats, harnesses, crashes, pivots,
 * lessons learned, crew roundtables, and officer KPI evolution.
 */
export function buildWorkspaceDocumentary(
  events: StreamEvent[],
  state: WorkspaceProjection
): WorkspaceDocumentary {
  const chapters: DocumentaryChapter[] = [];
  let current: DocumentaryChapter | null = null;

  for (const ev of events) {
    const startNewChapter =
      !current ||
      current.sessionId !== ev.sessionId ||
      ev.type === 'workspace.attached' ||
      ev.type === 'harness.switched';

    if (startNewChapter) {
      current = {
        chapterNumber: chapters.length + 1,
        sessionId: ev.sessionId,
        startedAt: ev.timestamp,
        endedAt: ev.timestamp,
        harnesses: [ev.harness],
        eventCount: 0,
        highlights: [],
        events: []
      };
      chapters.push(current);
    }

    current!.endedAt = ev.timestamp;
    current!.eventCount += 1;
    if (!current!.harnesses.includes(ev.harness)) {
      current!.harnesses.push(ev.harness);
    }
    current!.events.push(ev);

    if (
      ev.type === 'lesson.captured' ||
      ev.type === 'decision.recorded' ||
      ev.type === 'directive.issued' ||
      ev.type === 'exec.crashed' ||
      ev.type === 'exec.failed' ||
      ev.type === 'crew.consensus' ||
      ev.type === 'officer.knowledge.updated' ||
      ev.type === 'git.commit'
    ) {
      current!.highlights.push(`[#${ev.seq} ${ev.type}] ${ev.summary}`);
    }
  }

  const lines: string[] = [
    `# Workspace Documentary — ${state.workspaceRoot}`,
    '',
    `> Curated by **Number One** (Event-Sourced System of Record)`,
    '',
    `## Overview`,
    `- **Total Atomic Events**: ${events.length}`,
    `- **Harnesses Spanned**: ${state.harnessesSeen.join(', ') || 'none'}`,
    `- **Sessions Spanned**: ${state.sessionsSeen.length}`,
    `- **Lessons Captured**: ${Object.keys(state.lessons).length}`,
    `- **Decisions Recorded**: ${Object.keys(state.decisions).length}`,
    `- **Authoritative Directives**: ${Object.values(state.directives).filter((d) => d.active).length} active / ${Object.keys(state.directives).length} total`,
    `- **Crashes Recorded**: ${state.crashes.length} (${state.crashes.filter((c) => c.resolvedByEventId).length} resolved)`,
    `- **Party Mode Sessions**: ${Object.keys(state.partySessions).length}`,
    ''
  ];

  if (Object.keys(state.lessons).length > 0) {
    lines.push(`## Institutional Lessons Learned`);
    for (const lesson of Object.values(state.lessons)) {
      lines.push(`### ${lesson.title}`);
      lines.push(`- **Problem**: ${lesson.problem}`);
      lines.push(`- **Root Cause**: ${lesson.rootCause}`);
      if (lesson.failedApproaches.length > 0) {
        lines.push(`- **Dead Ends Avoided**: ${lesson.failedApproaches.join(' | ')}`);
      }
      lines.push(`- **Resolution**: ${lesson.resolution}`);
      lines.push(`- **Prevention Rule**: ${lesson.preventionRule}`);
      lines.push('');
    }
  }

  lines.push(`## Chronological Chapters`);
  for (const ch of chapters) {
    lines.push(
      `### Chapter ${ch.chapterNumber}: Session \`${ch.sessionId}\` (${ch.harnesses.join(', ')})`
    );
    lines.push(`*${ch.startedAt} -> ${ch.endedAt} (${ch.eventCount} events)*`);
    lines.push('');
    for (const ev of ch.events) {
      const paths = ev.affectedPaths.length > 0 ? ` [${ev.affectedPaths.join(', ')}]` : '';
      lines.push(`- **#${ev.seq}** \`${ev.type}\` (${ev.actor.kind}:${ev.actor.id} via ${ev.harness}): ${ev.summary}${paths}`);
    }
    lines.push('');
  }

  return {
    workspaceRoot: state.workspaceRoot,
    generatedAt: new Date().toISOString(),
    totalEvents: events.length,
    chapters,
    markdown: lines.join('\n')
  };
}

import { createHash } from 'node:crypto';

const MAX_CANONICAL_DEPTH = 64;

function serializeCanonical(value: unknown, depth: number, inArray: boolean): string | undefined {
  if (depth > MAX_CANONICAL_DEPTH) {
    throw new Error(`canonicalJson: maximum nesting depth (${MAX_CANONICAL_DEPTH}) exceeded`);
  }

  if (value !== null && typeof value === 'object') {
    const maybeToJson = (value as { toJSON?: unknown }).toJSON;
    if (typeof maybeToJson === 'function') {
      return serializeCanonical(maybeToJson.call(value), depth + 1, inArray);
    }
  }

  if (value === null) return 'null';

  const t = typeof value;
  if (t === 'bigint') {
    throw new TypeError('canonicalJson: BigInt values are not JSON-serializable');
  }
  if (t === 'undefined' || t === 'function' || t === 'symbol') {
    return inArray ? 'null' : undefined;
  }
  if (t === 'number') {
    return Number.isFinite(value as number) ? JSON.stringify(value) : 'null';
  }
  if (t === 'boolean' || t === 'string') {
    return JSON.stringify(value);
  }

  if (Array.isArray(value)) {
    const items = value.map((item) => serializeCanonical(item, depth + 1, true) ?? 'null');
    return '[' + items.join(',') + ']';
  }

  const obj = value as Record<string, unknown>;
  const keys = Object.keys(obj).sort();
  const pairs: string[] = [];
  for (const k of keys) {
    const serialized = serializeCanonical(obj[k], depth + 1, false);
    if (serialized !== undefined) {
      pairs.push(`${JSON.stringify(k)}:${serialized}`);
    }
  }
  return '{' + pairs.join(',') + '}';
}

/**
 * Deterministic canonical JSON serialization with recursively sorted object keys.
 * Strictly matches JSON.stringify semantics so in-memory hashes always equal on-disk reload hashes.
 */
export function canonicalJson(value: unknown): string {
  const out = serializeCanonical(value, 0, false);
  if (out === undefined) {
    throw new TypeError('canonicalJson: top-level value is not JSON-serializable');
  }
  return out;
}

export function sha256Hex(input: string | Buffer): string {
  return createHash('sha256').update(input).digest('hex');
}

export function hashObject(value: unknown): string {
  return sha256Hex(canonicalJson(value));
}

export const GENESIS_HASH = '0'.repeat(64);

import { StreamStore } from './stream-store.js';
import { LessonRecord, StreamEvent, WorkspaceProjection } from './types.js';

export interface LessonMatch {
  lesson: LessonRecord;
  score: number;
  reasons: string[];
}

export interface ConsultationQuery {
  intent?: string;
  targetPaths?: string[];
  errorText?: string;
  command?: string;
  tags?: string[];
}

export interface FailureFixCorrelation {
  crashEvent: StreamEvent;
  fixEvent: StreamEvent;
  modifiedPaths: string[];
  intermediateThoughts: string[];
  failedApproaches: string[];
  suggestedLesson: {
    title: string;
    problem: string;
    rootCause: string;
    resolution: string;
    preventionRule: string;
    errorSignatures: string[];
    affectedPaths: string[];
    tags: string[];
    sourceEventIds: string[];
    failedApproaches: string[];
  };
}

function tokenize(text: string): Set<string> {
  const matches = text.toLowerCase().match(/[a-z0-9_.-]{3,}/g) ?? [];
  const stopWords = new Set([
    'the',
    'and',
    'for',
    'with',
    'that',
    'this',
    'from',
    'have',
    'been',
    'were',
    'will',
    'into',
    'about',
    'error',
    'failed',
    'command'
  ]);
  return new Set(matches.filter((t) => !stopWords.has(t)));
}

function normalizePath(p: string): string {
  return p.replace(/\\/g, '/').replace(/^\.\//, '');
}

/**
 * Institutional memory engine designed to inhibit reinventing the wheel:
 *  - Matches active work against historical lessons, failed attempts, and crashes
 *  - Automatically correlates failure -> edits/thinking -> fix sequences into durable lessons
 */
export class LessonEngine {
  private readonly store: StreamStore;

  constructor(store: StreamStore) {
    this.store = store;
  }

  /**
   * Scores and retrieves relevant historical lessons for a proposed task, path, command, or error.
   */
  public findRelevantLessons(state: WorkspaceProjection, query: ConsultationQuery): LessonMatch[] {
    const queryPaths = (query.targetPaths ?? []).map(normalizePath);
    const queryText = [query.intent ?? '', query.errorText ?? '', query.command ?? ''].join(' ');
    const queryTokens = tokenize(queryText);
    const queryTags = new Set((query.tags ?? []).map((t) => t.toLowerCase()));

    const matches: LessonMatch[] = [];

    for (const lesson of Object.values(state.lessons)) {
      if (lesson.supersededBy) continue;
      let score = 0;
      const reasons: string[] = [];

      // 1. Exact or prefix path overlap
      for (const lp of lesson.affectedPaths.map(normalizePath)) {
        for (const qp of queryPaths) {
          if (lp === qp) {
            score += 45;
            reasons.push(`Direct file match: ${lp}`);
          } else if (lp.startsWith(qp + '/') || qp.startsWith(lp + '/')) {
            score += 22;
            reasons.push(`Directory overlap: ${lp} <-> ${qp}`);
          }
        }
      }

      // 2. Error signature matching (against errorText, command, AND intent)
      if (query.errorText || query.command || query.intent) {
        const haystack = `${query.errorText ?? ''} ${query.command ?? ''} ${query.intent ?? ''}`.toLowerCase();
        for (const sig of lesson.errorSignatures) {
          const cleanSig = sig.trim().toLowerCase();
          if (cleanSig.length >= 4 && haystack.includes(cleanSig)) {
            score += 55;
            reasons.push(`Matched historical error signature: "${sig}"`);
          }
        }
      }

      // 3. Tag overlap
      for (const tag of lesson.tags) {
        if (queryTags.has(tag.toLowerCase())) {
          score += 18;
          reasons.push(`Shared tag: #${tag}`);
        }
      }

      // 4. Semantic token overlap across title, problem, rootCause, resolution, preventionRule
      if (queryTokens.size > 0) {
        const lessonTokens = tokenize(
          [
            lesson.title,
            lesson.problem,
            lesson.rootCause,
            lesson.resolution,
            lesson.preventionRule,
            ...lesson.failedApproaches
          ].join(' ')
        );
        let shared = 0;
        const sharedWords: string[] = [];
        for (const tok of queryTokens) {
          if (lessonTokens.has(tok)) {
            shared++;
            if (sharedWords.length < 5) sharedWords.push(tok);
          }
        }
        if (shared > 0) {
          const ratio = shared / Math.max(1, Math.min(queryTokens.size, 8));
          const tokenPoints = Math.round(ratio * 40);
          if (tokenPoints >= 8) {
            score += tokenPoints;
            reasons.push(`Keyword alignment (${sharedWords.join(', ')})`);
          }
        }
      }

      if (score > 0) {
        if (lesson.verified) score += 8;
        if (lesson.severity === 'critical') score += 12;
        else if (lesson.severity === 'high') score += 6;
        matches.push({ lesson, score, reasons: Array.from(new Set(reasons)) });
      }
    }

    return matches.sort((a, b) => b.score - a.score);
  }

  /**
   * Finds prior failed attempts matching the proposed work so the agent or human
   * does not retry dead ends already explored in previous sessions/harnesses.
   */
  public findRelevantFailedAttempts(state: WorkspaceProjection, query: ConsultationQuery) {
    const queryPaths = (query.targetPaths ?? []).map(normalizePath);
    const queryTokens = tokenize([query.intent ?? '', query.command ?? '', query.errorText ?? ''].join(' '));
    const queryTags = new Set((query.tags ?? []).map((t) => t.toLowerCase()));

    return state.failedAttempts.filter((attempt) => {
      if (
        attempt.affectedPaths.some((p) => {
          const ap = normalizePath(p);
          return queryPaths.some((qp) => ap === qp || ap.startsWith(qp + '/') || qp.startsWith(ap + '/'));
        })
      ) {
        return true;
      }
      if (attempt.tags.some((t) => queryTags.has(t.toLowerCase()))) return true;
      if (queryTokens.size > 0) {
        const attemptTokens = tokenize(`${attempt.approach} ${attempt.reason}`);
        let overlap = 0;
        for (const tok of queryTokens) {
          if (attemptTokens.has(tok)) overlap++;
        }
        if (overlap >= 2) return true;
      }
      return false;
    });
  }

  /**
   * Inspects the event stream around a successful command completion to see if it
   * resolved a recent failure/crash for the same command — automatically extracting
   * the intermediate edits, thinking, and failed attempts into a structured lesson!
   */
  public detectFailureToFixCorrelation(fixEvent: StreamEvent): FailureFixCorrelation | null {
    if (fixEvent.type !== 'exec.completed') return null;
    const command = typeof fixEvent.payload.command === 'string' ? fixEvent.payload.command : '';
    if (!command) return null;

    const lookbackWindow = 500;
    const priorEvents = this.store.query({
      sinceSeq: Math.max(1, fixEvent.seq - lookbackWindow),
      untilSeq: fixEvent.seq - 1
    });
    let crashEvent: StreamEvent | null = null;

    for (let i = priorEvents.length - 1; i >= 0; i--) {
      const ev = priorEvents[i]!;
      const evCmd = typeof ev.payload.command === 'string' ? ev.payload.command : '';
      if (ev.type === 'exec.completed' && evCmd === command) {
        // Already succeeded before without an intervening crash
        return null;
      }
      if ((ev.type === 'exec.failed' || ev.type === 'exec.crashed') && evCmd === command) {
        crashEvent = ev;
        break;
      }
    }

    if (!crashEvent) return null;

    const intervening = priorEvents.filter((e) => e.seq > crashEvent!.seq && e.seq < fixEvent.seq);
    const modifiedPaths = Array.from(
      new Set(
        intervening
          .filter((e) => e.type === 'fs.modified' || e.type === 'fs.created' || e.type === 'fs.deleted')
          .flatMap((e) => e.affectedPaths)
      )
    );
    const intermediateThoughts = intervening
      .filter((e) => e.type === 'chat.thinking')
      .map((e) => String(e.payload.thought ?? e.summary));
    const failedApproaches = intervening
      .filter((e) => e.type === 'attempt.failed')
      .map((e) => String(e.payload.approach ?? e.summary).trim())
      .filter(Boolean);

    const errorSig = String(
      crashEvent.payload.errorSignature ?? crashEvent.payload.stderrExcerpt ?? crashEvent.summary
    )
      .split(/\r?\n/)[0]!
      .trim()
      .slice(0, 140);

    const affectedPaths = Array.from(new Set([...crashEvent.affectedPaths, ...modifiedPaths])).sort();

    return {
      crashEvent,
      fixEvent,
      modifiedPaths,
      intermediateThoughts,
      failedApproaches,
      suggestedLesson: {
        title: `Resolved failure in \`${command}\`: ${errorSig.slice(0, 80)}`,
        problem: `Command \`${command}\` failed with exit code ${String(crashEvent.payload.exitCode ?? 'unknown')}: ${errorSig}`,
        rootCause:
          intermediateThoughts.length > 0
            ? intermediateThoughts.join(' | ')
            : `Failure observed at seq #${crashEvent.seq}; resolved after modifying ${modifiedPaths.join(', ') || 'workspace state'}.`,
        resolution:
          modifiedPaths.length > 0
            ? `Modified ${modifiedPaths.join(', ')} and verified \`${command}\` succeeded at seq #${fixEvent.seq}.`
            : `Verified \`${command}\` succeeded at seq #${fixEvent.seq}.`,
        preventionRule: `When encountering "${errorSig}" on \`${command}\`, inspect ${modifiedPaths.join(', ') || 'recent changes'} and avoid previously failed approaches.`,
        errorSignatures: errorSig ? [errorSig] : [],
        affectedPaths,
        tags: Array.from(new Set(['auto-correlated', 'crash-fix', ...crashEvent.tags, ...fixEvent.tags])),
        sourceEventIds: [crashEvent.id, ...intervening.map((e) => e.id), fixEvent.id],
        failedApproaches
      }
    };
  }
}

