import { randomBytes } from 'node:crypto';

const CROCKFORD = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
const MAX_TIME = 2 ** 48 - 1;

let lastTime = -1;
const lastRandom = new Uint8Array(10);

function encodeTime(time: number, length = 10): string {
  if (!Number.isFinite(time) || time < 0 || time > MAX_TIME) {
    throw new RangeError(`ULID timestamp out of range: ${time}`);
  }
  let remaining = Math.floor(time);
  let out = '';
  for (let i = length - 1; i >= 0; i--) {
    const mod = remaining % 32;
    out = CROCKFORD[mod]! + out;
    remaining = Math.floor(remaining / 32);
  }
  return out;
}

function encodeRandom(bytes: Uint8Array): string {
  let out = '';
  let buffer = 0;
  let bits = 0;
  for (let i = 0; i < bytes.length; i++) {
    buffer = (buffer << 8) | bytes[i]!;
    bits += 8;
    while (bits >= 5) {
      bits -= 5;
      out += CROCKFORD[(buffer >>> bits) & 0x1f]!;
    }
  }
  return out;
}

function incrementRandom(bytes: Uint8Array): boolean {
  for (let i = bytes.length - 1; i >= 0; i--) {
    if (bytes[i]! < 255) {
      bytes[i] = bytes[i]! + 1;
      return true;
    }
    bytes[i] = 0;
  }
  return false; // 80-bit overflow
}

/**
 * Generates a strictly monotonic, lexicographically sortable 26-char ULID,
 * resilient to backward NTP clock skew (`now <= lastTime`).
 */
export function generateUlid(now = Date.now()): string {
  if (!Number.isFinite(now)) {
    throw new RangeError(`ULID timestamp out of range: ${now}`);
  }
  let effectiveTime = Math.floor(now);
  if (effectiveTime < 0 || effectiveTime > MAX_TIME) {
    throw new RangeError(`ULID timestamp out of range: ${effectiveTime}`);
  }

  if (effectiveTime <= lastTime) {
    effectiveTime = lastTime;
    const candidateRandom = new Uint8Array(lastRandom);
    const incremented = incrementRandom(candidateRandom);
    if (!incremented) {
      // Extremely rare 80-bit overflow within same millisecond: advance logical time by 1ms
      if (lastTime + 1 > MAX_TIME) {
        throw new RangeError('ULID logical timestamp overflowed MAX_TIME');
      }
      effectiveTime = lastTime + 1;
      lastTime = effectiveTime;
      lastRandom.set(randomBytes(10));
    } else {
      lastRandom.set(candidateRandom);
    }
  } else {
    lastTime = effectiveTime;
    lastRandom.set(randomBytes(10));
  }
  return encodeTime(effectiveTime, 10) + encodeRandom(lastRandom);
}

import path from 'node:path';
import { KnowledgePractice, OfficerRole, WorkspaceProjection } from '../core/types.js';
import { readTextFileSafe, walkWorkspaceFiles } from '../utils/fs-helpers.js';
import { WorkspaceIgnore } from '../utils/ignore.js';
import { isSensitiveSecretFile } from '../utils/redactor.js';
import { compileSafeRegex, matchGlobLinear, MAX_REGEX_INPUT_LENGTH } from '../utils/safe-regex.js';
import {
  CheckEvaluation,
  CrewOfficer,
  OfficerAssessment,
  OfficerFinding,
  VerificationSample
} from './types.js';

/**
 * Canonical declarative container & IaC detection patterns shared across
 * EngineeringOfficer and BridgeOfficer so cross-officer assessments never contradict.
 */
export const SHARED_CONTAINER_FILE_RX =
  /(^|\/)(Dockerfile|Containerfile|docker-compose\.ya?ml|compose\.ya?ml)$/i;

export const SHARED_IAC_FILE_RX =
  /(\.tf$|Pulumi\.ya?ml$|cdk\.json$|Chart\.ya?ml$|kustomization\.ya?ml$|(^|\/)(k8s|helm|terraform|infra)\/)/i;

const MAX_DYNAMIC_FILES_PER_PRACTICE = 400;

export function matchesSimpleGlob(filePath: string, glob: string): boolean {
  const normPath = filePath.replace(/\\/g, '/').replace(/^\.\//, '');
  const normGlob = glob.replace(/\\/g, '/').replace(/^\.\//, '');
  return matchGlobLinear(normPath, normGlob, true);
}

/**
 * Evaluates a single `KnowledgePractice['matcher']` against an in-memory file set
 * using linear-time DP glob matching, ReDoS-safe regex compilation, and bounded input lengths.
 */
export function evaluatePracticeMatcherOnVirtualFiles(
  practice: Pick<KnowledgePractice, 'id' | 'title' | 'category' | 'description' | 'matcher'>,
  files: VerificationSample[],
  allFilePaths?: string[]
): { violated: boolean; evidence: string; matchedPaths: string[] } {
  const matcher = practice.matcher;
  if (!matcher) {
    return { violated: false, evidence: 'No executable matcher attached.', matchedPaths: [] };
  }

  if (matcher.missingFile) {
    const target = matcher.missingFile;
    const candidatePaths = allFilePaths ?? files.map((f) => f.path);
    const exists = candidatePaths.some((p) => p === target || matchesSimpleGlob(p, target));
    if (!exists) {
      return {
        violated: true,
        evidence: `Required file matching "${target}" is absent.`,
        matchedPaths: []
      };
    }
  }

  if (matcher.requiredContentRegex) {
    const rx = compileSafeRegex(matcher.requiredContentRegex, 'im');
    if (!rx) {
      return {
        violated: false,
        evidence: `Skipped unsafe requiredContentRegex pattern.`,
        matchedPaths: []
      };
    }
    const scoped = matcher.fileGlob
      ? files.filter((f) => matchesSimpleGlob(f.path, matcher.fileGlob!))
      : files;
    if (
      scoped.length === 0 ||
      !scoped.some((f) => rx.test(f.content.slice(0, MAX_REGEX_INPUT_LENGTH)))
    ) {
      return {
        violated: true,
        evidence: `Required pattern /${matcher.requiredContentRegex}/ not found${matcher.fileGlob ? ` in ${matcher.fileGlob}` : ''}.`,
        matchedPaths: scoped.map((s) => s.path)
      };
    }
  }

  if (matcher.contentRegex) {
    const rx = compileSafeRegex(matcher.contentRegex, 'im');
    if (!rx) {
      return {
        violated: false,
        evidence: `Skipped unsafe contentRegex pattern.`,
        matchedPaths: []
      };
    }
    const matchedPaths: string[] = [];
    for (const f of files) {
      if (matcher.fileGlob && !matchesSimpleGlob(f.path, matcher.fileGlob)) continue;
      if (rx.test(f.content.slice(0, MAX_REGEX_INPUT_LENGTH))) {
        matchedPaths.push(f.path);
      }
    }
    if (matchedPaths.length > 0) {
      return {
        violated: true,
        evidence: `Forbidden pattern /${matcher.contentRegex}/ matched in ${matchedPaths.slice(0, 5).join(', ')}.`,
        matchedPaths
      };
    }
  }

  return {
    violated: false,
    evidence: `Satisfied practice "${practice.title}".`,
    matchedPaths: []
  };
}

/**
 * Strips comments and echo/printf lines from CI YAML or shell scripts so naive
 * `echo "deploy canary rollback"` lines are never mistaken for real automation.
 */
export function stripShellEchoAndComments(content: string): string {
  return content
    .split(/\r?\n/)
    .filter((line) => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) return false;
      const afterDash = trimmed.replace(/^-\s*/, '').replace(/^run:\s*\|?\s*/i, '').trim();
      if (/^(?:echo|printf)\b/i.test(afterDash)) return false;
      return true;
    })
    .join('\n');
}

/**
 * Computes transparent weighted pass score and per-category breakdown strictly
 * from explicit `CheckEvaluation[]` entries — zero arbitrary baseline constants.
 */
export function computeScoresFromChecks(checks: CheckEvaluation[]): {
  kpiScore: number;
  kpiBreakdown: Record<string, number>;
} {
  const applicable = checks.filter((c) => c.applicable && c.weight > 0);
  if (applicable.length === 0) {
    return { kpiScore: 100, kpiBreakdown: {} };
  }

  const totalWeight = applicable.reduce((sum, c) => sum + c.weight, 0);
  const earnedWeight = applicable
    .filter((c) => c.passed)
    .reduce((sum, c) => sum + c.weight, 0);

  const kpiScore = Math.round((earnedWeight / totalWeight) * 1000) / 10;

  const byCat = new Map<string, { earned: number; total: number }>();
  for (const c of applicable) {
    const curr = byCat.get(c.category) ?? { earned: 0, total: 0 };
    curr.total += c.weight;
    if (c.passed) curr.earned += c.weight;
    byCat.set(c.category, curr);
  }

  const kpiBreakdown: Record<string, number> = {};
  for (const [cat, { earned, total }] of byCat.entries()) {
    kpiBreakdown[cat] = total > 0 ? Math.round((earned / total) * 1000) / 10 : 100;
  }

  return { kpiScore, kpiBreakdown };
}

/**
 * Base class for Bridge Crew expert officers.
 */
export abstract class BaseBridgeOfficer implements CrewOfficer {
  public abstract readonly role: OfficerRole;
  public abstract readonly title: string;
  public abstract readonly mainKpiName: string;
  public abstract readonly mandate: string;

  public abstract getBaselinePractices(): KnowledgePractice[];
  public abstract assess(
    workspaceRoot: string,
    projection: WorkspaceProjection,
    topic?: string,
    targetPaths?: string[]
  ): OfficerAssessment;

  protected listWorkspaceFiles(workspaceRoot: string): string[] {
    const ignore = new WorkspaceIgnore(workspaceRoot);
    return walkWorkspaceFiles(workspaceRoot, (p, d) => ignore.shouldIgnore(p, d));
  }

  protected prioritizeTargetPaths(files: string[], targetPaths?: string[]): string[] {
    if (!targetPaths || targetPaths.length === 0) return files;
    const normalizedTargets = new Set(targetPaths.map((p) => p.replace(/\\/g, '/').replace(/^\.\//, '')));
    const priority: string[] = [];
    const rest: string[] = [];
    for (const f of files) {
      if (
        normalizedTargets.has(f) ||
        Array.from(normalizedTargets).some((t) => f.startsWith(`${t.replace(/\/+$/, '')}/`))
      ) {
        priority.push(f);
      } else {
        rest.push(f);
      }
    }
    return [...priority, ...rest];
  }

  protected getEffectivePractices(projection: WorkspaceProjection): KnowledgePractice[] {
    const map = new Map<string, KnowledgePractice>();
    for (const p of this.getBaselinePractices()) {
      map.set(p.id, p);
    }
    const evolved = projection.officers[this.role]?.practices ?? {};
    for (const [id, practice] of Object.entries(evolved)) {
      if (practice.active) {
        map.set(id, practice);
      } else {
        map.delete(id);
      }
    }
    return Array.from(map.values());
  }

  /**
   * Evaluates dynamically promoted practices as first-class `CheckEvaluation` items.
   * Filters by `fileGlob` BEFORE slicing, skips reading sensitive secret file bodies,
   * and evaluates `missingFile` against the complete workspace file inventory.
   */
  protected evaluateDynamicPractices(
    workspaceRoot: string,
    files: string[],
    projection: WorkspaceProjection
  ): { checks: CheckEvaluation[]; findings: OfficerFinding[] } {
    const checks: CheckEvaluation[] = [];
    const findings: OfficerFinding[] = [];
    const evolved = Object.values(projection.officers[this.role]?.practices ?? {}).filter(
      (p) => p.active && p.matcher
    );
    if (evolved.length === 0) return { checks, findings };

    const contentCache = new Map<string, string>();
    const loadSamplesForPractice = (practice: KnowledgePractice): VerificationSample[] => {
      const matcher = practice.matcher;
      if (!matcher || (!matcher.contentRegex && !matcher.requiredContentRegex)) {
        return [];
      }
      const candidates = files.filter((f) => {
        if (isSensitiveSecretFile(f)) return false;
        if (matcher.fileGlob && !matchesSimpleGlob(f, matcher.fileGlob)) return false;
        return true;
      });
      const samples: VerificationSample[] = [];
      for (const f of candidates.slice(0, MAX_DYNAMIC_FILES_PER_PRACTICE)) {
        let text = contentCache.get(f);
        if (text === undefined) {
          text = readTextFileSafe(path.join(workspaceRoot, f), 200_000, workspaceRoot) ?? '';
          contentCache.set(f, text);
        }
        samples.push({ path: f, content: text });
      }
      return samples;
    };

    for (const practice of evolved) {
      const sev = practice.matcher?.severity ?? 'medium';
      const weight = practice.weight ?? (sev === 'critical' ? 20 : sev === 'high' ? 15 : 10);
      const samples = loadSamplesForPractice(practice);
      const evalRes = evaluatePracticeMatcherOnVirtualFiles(practice, samples, files);

      checks.push({
        id: `evolved-${practice.id}`,
        category: practice.category,
        title: practice.title,
        weight,
        applicable: true,
        passed: !evalRes.violated,
        evidence: evalRes.evidence
      });

      if (evalRes.violated) {
        findings.push({
          id: `evolved-${practice.id}`,
          severity: sev,
          category: practice.category,
          title: practice.title,
          description: practice.description,
          evidence: evalRes.evidence,
          affectedPaths: evalRes.matchedPaths.slice(0, 10),
          recommendation: `Satisfy evolved practice "${practice.title}" (${practice.evidenceSummary}).`,
          blocksRelease: sev === 'critical'
        });
      }
    }

    return { checks, findings };
  }
}

import path from 'node:path';
import { KnowledgePractice, WorkspaceProjection } from '../core/types.js';
import { readTextFileSafe } from '../utils/fs-helpers.js';
import {
  BaseBridgeOfficer,
  computeScoresFromChecks,
  SHARED_CONTAINER_FILE_RX,
  SHARED_IAC_FILE_RX,
  stripShellEchoAndComments
} from './base-officer.js';
import { CheckEvaluation, OfficerAssessment, OfficerFinding, PeerChallenge } from './types.js';

/**
 * Real deployment/release action patterns (evaluated ONLY after stripping comments and echo/printf!).
 */
const REAL_DEPLOY_OR_RELEASE_RX =
  /\b(?:npm\s+publish|pnpm\s+publish|yarn\s+npm\s+publish|gh\s+release\s+create|semantic-release|changesets\/action|googleapis\/release-please-action|softprops\/action-gh-release|docker\/build-push-action|docker\s+push|helm\s+upgrade|kubectl\s+apply|kubectl\s+rollout|terraform\s+apply|tofu\s+apply|pulumi\s+up|aws\s+ecs\s+update-service|gcloud\s+run\s+deploy|flyctl\s+deploy)\b/i;

const REAL_ROLLBACK_OR_PROGRESSIVE_RX =
  /\b(?:helm\s+upgrade\s+[^\n]*--atomic|kubectl\s+rollout\s+undo|argoproj\.io\/v1alpha1|flagger\.app\/v1beta1|aws\s+deploy|npm\s+dist-tag\s+add|npm\s+deprecate|gh\s+release\s+(?:delete|edit)|rollback\.sh|canary|blue[-_]?green)\b/i;

/**
 * Bridge Officer — Release & Continuous Delivery Auditor.
 * Zero unconditional hardcoded challenges, zero `|| 1` phantom constraints,
 * per-workflow CI trigger evaluation, shared IaC/container detection with EngineeringOfficer,
 * and strips shell `echo`/`printf` statements so fake CI echo steps cannot game CD scores.
 */
export class BridgeOfficer extends BaseBridgeOfficer {
  public readonly role = 'bridge' as const;
  public readonly title = 'Bridge Officer (Release & Continuous Delivery)';
  public readonly mainKpiName = 'continuous_delivery_score';
  public readonly mandate =
    'Evaluate and challenge release pipelines, automated test suites, deployment automation, rollback safety, and stream execution stability toward Continuous Delivery.';

  public getBaselinePractices(): KnowledgePractice[] {
    return [
      {
        id: 'cd-automated-ci',
        title: 'Automated Build & Test CI Pipeline',
        category: 'processes',
        description: 'Execute automated build and test verification on every push and pull request.',
        ruleType: 'process',
        targetKpi: this.mainKpiName,
        weight: 25,
        evidenceSummary: 'Automated commit verification is the foundational prerequisite for Continuous Delivery.',
        evidenceSources: ['Continuous Delivery (Humble & Farley)'],
        version: 1,
        active: true
      },
      {
        id: 'cd-automated-test-suite',
        title: 'Comprehensive Automated Test Suite',
        category: 'tests',
        description: 'Maintain unit, integration, and end-to-end automated tests executable via a single command.',
        ruleType: 'methodology',
        targetKpi: this.mainKpiName,
        weight: 25,
        evidenceSummary: 'Fast deterministic tests replace manual QA bottlenecks.',
        evidenceSources: ['DORA Capabilities: Continuous Testing'],
        version: 1,
        active: true
      },
      {
        id: 'cd-automated-release-promotion',
        title: 'Automated Artifact Publishing or Deployment',
        category: 'processes',
        description: 'Automate package publishing, release creation, or environment deployment from verified main builds.',
        ruleType: 'tool',
        targetKpi: this.mainKpiName,
        weight: 20,
        evidenceSummary: 'Eliminates manual release toil and human error.',
        evidenceSources: ['DORA Capabilities: Deployment Automation'],
        version: 1,
        active: true
      },
      {
        id: 'cd-rollback-and-progressive-safety',
        title: 'Automated Rollback or Progressive Delivery Controls',
        category: 'infra',
        description: 'Provide atomic rollback, canary/blue-green manifests, or feature-flag decoupling.',
        ruleType: 'control',
        targetKpi: this.mainKpiName,
        weight: 15,
        evidenceSummary: 'Minimizes mean time to recovery (MTTR) when defects reach production.',
        evidenceSources: ['DORA Metrics: Failed Deployment Recovery Time'],
        version: 1,
        active: true
      }
    ];
  }

  public assess(
    workspaceRoot: string,
    projection: WorkspaceProjection,
    topic?: string,
    _targetPaths?: string[]
  ): OfficerAssessment {
    const files = this.listWorkspaceFiles(workspaceRoot);
    const checks: CheckEvaluation[] = [];
    const findings: OfficerFinding[] = [];
    const challenges: PeerChallenge[] = [];
    const cdChallengeBacklog: string[] = [];

    // 1. CI Pipeline — evaluate triggers PER WORKFLOW so having a manual/tag release workflow
    // alongside an automatic push/PR CI workflow never falsely invalidates automatic CI!
    const ciFiles = files.filter((f) =>
      /^(\.github\/workflows\/.+\.ya?ml|\.gitlab-ci\.yml|Jenkinsfile|\.circleci\/config\.yml|azure-pipelines\.yml)$/i.test(
        f
      )
    );
    const autoCiFiles: string[] = [];
    let hasBuildInAutoCi = false;
    let hasTestInAutoCi = false;
    let hasBuildInAnyCi = false;
    let hasTestInAnyCi = false;
    let hasRealDeployOrReleaseInCi = false;

    for (const cf of ciFiles) {
      const rawContent = readTextFileSafe(path.join(workspaceRoot, cf), 512_000, workspaceRoot) ?? '';
      const stripped = stripShellEchoAndComments(rawContent);

      const wfHasBuild = /\b(npm run build|pnpm build|yarn build|tsc\b|cargo build|go build|docker build)\b/i.test(
        stripped
      );
      const wfHasTest =
        /\b(npm test|npm run test|vitest|jest|pytest|go test|cargo test|playwright|cypress)\b/i.test(
          stripped
        );
      if (wfHasBuild) hasBuildInAnyCi = true;
      if (wfHasTest) hasTestInAnyCi = true;

      if (REAL_DEPLOY_OR_RELEASE_RX.test(stripped)) {
        hasRealDeployOrReleaseInCi = true;
      }

      const isGithubWorkflow = /^\.github\/workflows\//i.test(cf);
      const triggersOnPushOrPr =
        !isGithubWorkflow ||
        /\b(push|pull_request)\s*:/i.test(rawContent) ||
        /^\s*on\s*:\s*(?:push|pull_request)\b/im.test(rawContent) ||
        /^\s*on\s*:\s*\[[^\]]*\b(?:push|pull_request)\b/im.test(rawContent);
      const isTagOnlyPush =
        isGithubWorkflow &&
        !/\bpull_request\b/i.test(rawContent) &&
        /\bpush\s*:\s*[\r\n]+\s+tags\s*:/i.test(rawContent) &&
        !/\bbranches\s*:/i.test(rawContent);

      if (triggersOnPushOrPr && !isTagOnlyPush) {
        autoCiFiles.push(cf);
        if (wfHasBuild) hasBuildInAutoCi = true;
        if (wfHasTest) hasTestInAutoCi = true;
      }
    }

    const isManualOnlyTrigger = ciFiles.length > 0 && autoCiFiles.length === 0;
    const ciVerifiesEveryChange = autoCiFiles.length > 0 && hasBuildInAutoCi && hasTestInAutoCi;

    checks.push({
      id: 'cd-ci-verification',
      category: 'processes',
      title: 'Automated push/PR CI pipeline executes build and tests',
      weight: 25,
      applicable: true,
      passed: ciVerifiesEveryChange,
      evidence:
        ciFiles.length === 0
          ? 'No CI workflow configuration found.'
          : `CI files: ${ciFiles.join(', ')} (autoCi=${autoCiFiles.join(', ') || 'none'}, build=${hasBuildInAutoCi}, test=${hasTestInAutoCi}, manualOnly=${isManualOnlyTrigger})`
    });

    if (ciFiles.length === 0) {
      cdChallengeBacklog.push('No automated CI pipeline configured.');
      findings.push({
        id: 'cd-no-pipeline',
        severity: 'high',
        category: 'processes',
        title: 'No CI/CD pipeline configuration found',
        description: 'Commits and pull requests are not automatically built and tested.',
        evidence: 'Checked .github/workflows, .gitlab-ci.yml, Jenkinsfile, CircleCI, Azure Pipelines.',
        affectedPaths: [],
        recommendation: 'Configure a trunk-based CI workflow running build, test, and security audits on push and PR.'
      });
    } else if (!ciVerifiesEveryChange) {
      cdChallengeBacklog.push(
        isManualOnlyTrigger
          ? 'All CI workflows are manual/tag-only; none trigger automatically on push/PR.'
          : `Automated push/PR CI workflow missing ${!hasBuildInAutoCi ? 'build' : 'test'} execution step.`
      );
      findings.push({
        id: 'cd-incomplete-ci',
        severity: 'medium',
        category: 'processes',
        title: isManualOnlyTrigger
          ? 'CI workflows only trigger manually (no automatic push/PR verification)'
          : 'Automated push/PR CI pipeline omits build or test execution',
        description: `Detected CI workflow(s) (${ciFiles.join(', ')}) do not automatically run both build and test commands on push/PR.`,
        evidence: `autoCiFiles=${autoCiFiles.length}, hasBuildInAutoCi=${hasBuildInAutoCi}, hasTestInAutoCi=${hasTestInAutoCi}`,
        affectedPaths: ciFiles,
        recommendation: 'Ensure an automatic push/pull_request CI workflow runs full build and automated test suite on every commit.'
      });
    }

    // 2. Automated Test Suite
    const testFiles = files.filter((f) =>
      /(^|\/)(tests?|__tests__|spec|e2e)\/|\.(test|spec)\.(ts|tsx|js|jsx|py|go|rs)$/i.test(f)
    );
    const hasE2eOrIntegration = testFiles.some((f) => /(e2e|integration)/i.test(f));
    const hasTestScript = (() => {
      const pkgText = readTextFileSafe(path.join(workspaceRoot, 'package.json'), 512_000, workspaceRoot);
      if (!pkgText) {
        return (
          files.includes('Makefile') ||
          files.includes('pytest.ini') ||
          files.includes('Cargo.toml') ||
          files.includes('go.mod')
        );
      }
      try {
        const pkg = JSON.parse(pkgText) as { scripts?: Record<string, string> };
        return Boolean(pkg.scripts?.test && !pkg.scripts.test.includes('no test specified'));
      } catch {
        return false;
      }
    })();

    const testsComprehensive = hasTestScript && testFiles.length >= 2 && hasE2eOrIntegration;
    checks.push({
      id: 'cd-automated-tests',
      category: 'tests',
      title: 'Executable automated unit and integration/E2E test suite present',
      weight: 25,
      applicable: true,
      passed: testsComprehensive,
      evidence: `testScript=${hasTestScript}, testFiles=${testFiles.length}, hasE2eOrIntegration=${hasE2eOrIntegration}`
    });

    if (testFiles.length === 0 || !hasTestScript) {
      cdChallengeBacklog.push('Missing executable automated test suite.');
      findings.push({
        id: 'cd-no-tests',
        severity: 'critical',
        category: 'tests',
        title: 'No executable automated test suite detected',
        description: 'Continuous Delivery is unsafe without automated verification.',
        evidence: `testScript=${hasTestScript}, testFiles=${testFiles.length}`,
        affectedPaths: [],
        recommendation: 'Add automated unit and integration/E2E tests wired to `npm test`.',
        blocksRelease: true
      });
    } else if (!hasE2eOrIntegration) {
      cdChallengeBacklog.push('Unit tests exist without integration/E2E tests.');
      findings.push({
        id: 'cd-missing-e2e-tests',
        severity: 'medium',
        category: 'tests',
        title: 'No integration or end-to-end tests detected',
        description: 'Only unit-level test files were detected; release confidence requires integration/E2E coverage.',
        evidence: `Found ${testFiles.length} test file(s), none matching integration/e2e.`,
        affectedPaths: testFiles.slice(0, 5),
        recommendation: 'Add end-to-end or integration tests exercising full CLI/runtime workflows.'
      });
    }

    // 3. Automated Release / Deployment Stage (Genuine commands/actions ONLY — echo stripped!)
    const hasReleaseConfig = files.some((f) =>
      /(\.changeset\/config\.json|release-please-config\.json|\.releaserc(\.json|\.js|\.yml)?)$/i.test(f)
    );
    const releaseAutomated = hasRealDeployOrReleaseInCi || hasReleaseConfig;

    checks.push({
      id: 'cd-release-automation',
      category: 'processes',
      title: 'Automated release publishing or deployment step configured',
      weight: 20,
      applicable: true,
      passed: releaseAutomated,
      evidence: releaseAutomated
        ? 'Real release/publish/deploy automation detected.'
        : 'CI verifies builds/tests but lacks a concrete publish, release, or deploy command.'
    });

    if (ciFiles.length > 0 && !releaseAutomated) {
      cdChallengeBacklog.push('CI stops at verification; artifact release/deployment is still manual.');
      findings.push({
        id: 'cd-ci-without-cd',
        severity: 'low',
        category: 'processes',
        title: 'CI configured without automated release or deployment step',
        description: 'Build and tests are automated, but artifact publishing/deployment remains manual.',
        evidence: `Inspected ${ciFiles.join(', ')} (ignoring echo/comments); no publish/release/deploy step found.`,
        affectedPaths: ciFiles,
        recommendation: 'Add automated package publishing, GitHub Release action, or target environment deployment.'
      });
    }

    // 4. Rollback & Progressive Delivery Controls (Genuine manifests/scripts ONLY — echo stripped!)
    const hasRealRollback = files.some((f) => {
      if (/(^|\/)(rollback\.sh|argo-rollout|flagger|feature[-_]?flags?\.(ts|js|py|go|json))$/i.test(f)) {
        return true;
      }
      if (/\.(ya?ml|sh)$/i.test(f)) {
        const stripped = stripShellEchoAndComments(
          readTextFileSafe(path.join(workspaceRoot, f), 512_000, workspaceRoot) ?? ''
        );
        return REAL_ROLLBACK_OR_PROGRESSIVE_RX.test(stripped);
      }
      return false;
    });

    checks.push({
      id: 'cd-rollback-safety',
      category: 'infra',
      title: 'Automated rollback or progressive delivery mechanism present',
      weight: 15,
      applicable: hasRealDeployOrReleaseInCi,
      passed: hasRealRollback,
      evidence: !hasRealDeployOrReleaseInCi
        ? 'Not applicable until automated deployment is configured.'
        : hasRealRollback
          ? 'Progressive delivery or automated rollback mechanism detected.'
          : 'Automated deploy exists without rollback/canary controls.'
    });

    if (hasRealDeployOrReleaseInCi && !hasRealRollback) {
      cdChallengeBacklog.push('Automated deployment lacks automated rollback or progressive rollout controls.');
      findings.push({
        id: 'cd-missing-rollback-strategy',
        severity: 'medium',
        category: 'infra',
        title: 'Automated deployment lacks rollback or progressive delivery controls',
        description: 'Deployments run automatically without atomic rollback, canary, or feature-flag controls.',
        evidence: 'No helm --atomic, kubectl rollout undo, Argo Rollouts, Flagger, npm dist-tag rollback, or rollback.sh script detected.',
        affectedPaths: ciFiles,
        recommendation: 'Configure atomic rollback on health failure, progressive canary rollout, or scripted release rollback.'
      });
    }

    // 5. Changelog / Versioning Hygiene & Stream Execution Stability (Sliding Window of last 50 executions)
    const hasChangelog = files.includes('CHANGELOG.md') || hasReleaseConfig;
    checks.push({
      id: 'cd-versioning-hygiene',
      category: 'controls',
      title: 'Release changelog or automated versioning configured',
      weight: 10,
      applicable: true,
      passed: hasChangelog,
      evidence: hasChangelog ? 'CHANGELOG.md or release config present.' : 'No CHANGELOG.md or release config found.'
    });

    const recentExecs = projection.recentExecutions;
    let windowExecs: number;
    let windowFailed: number;
    if (recentExecs && recentExecs.length > 0) {
      windowExecs = recentExecs.length;
      windowFailed = recentExecs.filter((e) => !e.ok).length;
    } else {
      windowExecs =
        (projection.eventCountsByType['exec.completed'] ?? 0) +
        (projection.eventCountsByType['exec.failed'] ?? 0) +
        (projection.eventCountsByType['exec.crashed'] ?? 0);
      windowFailed =
        (projection.eventCountsByType['exec.failed'] ?? 0) +
        (projection.eventCountsByType['exec.crashed'] ?? 0);
    }

    const changeFailureRate = windowExecs > 0 ? Math.round((windowFailed / windowExecs) * 100) : 0;
    const unresolvedCrashes = projection.crashes.filter((c) => !c.resolvedByEventId).length;

    checks.push({
      id: 'cd-stream-dora-stability',
      category: 'controls',
      title: 'Recent execution failure rate <= 20% (last 50 runs) with zero unresolved crashes',
      weight: 15,
      applicable: windowExecs > 0 || projection.crashes.length > 0,
      passed: changeFailureRate <= 20 && unresolvedCrashes === 0,
      evidence: `windowExecs=${windowExecs}, failureRate=${changeFailureRate}%, unresolvedCrashes=${unresolvedCrashes}`
    });

    // Dynamic evolved practices
    const dynamic = this.evaluateDynamicPractices(workspaceRoot, files, projection);
    checks.push(...dynamic.checks);
    findings.push(...dynamic.findings);

    const { kpiScore, kpiBreakdown } = computeScoresFromChecks(checks);

    // Emit peer challenges ONLY when concrete workspace conditions warrant them,
    // using the exact same canonical container/IaC detection regex as EngineeringOfficer!
    const hasContainerOrIaC = files.some(
      (f) => SHARED_CONTAINER_FILE_RX.test(f) || SHARED_IAC_FILE_RX.test(f)
    );
    if (!hasContainerOrIaC) {
      challenges.push({
        targetOfficer: 'engineering',
        challenge: 'Provide declarative container or IaC manifests so CI can package and deploy reproducibly.',
        rationale: 'Automated delivery pipelines require deterministic runtime packaging.',
        relatedFindingIds: ['cd-release-automation']
      });
    }
    if (ciFiles.length > 0 && !releaseAutomated) {
      challenges.push({
        targetOfficer: 'workspace',
        challenge: 'Automate package publishing or deployment from verified main-branch CI builds.',
        rationale: 'Eliminates manual release steps between green CI and artifact delivery.',
        relatedFindingIds: ['cd-ci-without-cd']
      });
    }

    const effectivePractices = this.getEffectivePractices(projection);
    const officerProj = projection.officers[this.role];
    const passedCount = checks.filter((c) => c.applicable && c.passed).length;
    const applicableCount = checks.filter((c) => c.applicable).length;

    const stance = `${this.mainKpiName}=${kpiScore}/100 (${passedCount}/${applicableCount} checks passed, ${cdChallengeBacklog.length} CD gap(s))${topic ? ` [${topic}]` : ''}.`;

    return {
      officer: this.role,
      officerTitle: this.title,
      mainKpiName: this.mainKpiName,
      kpiScore,
      kpiBreakdown,
      checks,
      findings,
      artifacts: {
        continuousDeliveryMatrix: {
          ciFiles,
          autoCiFiles,
          testFileCount: testFiles.length,
          hasTestScript,
          hasE2eOrIntegration,
          hasBuildInCi: hasBuildInAnyCi,
          hasTestInCi: hasTestInAnyCi,
          hasBuildInAutoCi,
          hasTestInAutoCi,
          hasRealDeployOrReleaseInCi,
          isManualOnlyTrigger,
          hasReleaseConfig,
          hasRealRollback,
          doraSnapshot: {
            commitsObserved: projection.eventCountsByType['git.commit'] ?? 0,
            execWindowSize: windowExecs,
            execChangeFailureRatePct: changeFailureRate,
            unresolvedCrashes
          },
          cdChallengeBacklog
        }
      },
      stance,
      challengesToPeers: challenges,
      activePracticeCount: effectivePractices.length,
      knowledgeVersion: officerProj?.knowledgeVersion ?? 1,
      evaluatedAt: new Date().toISOString()
    };
  }
}

import path from 'node:path';
import { KnowledgePractice, WorkspaceProjection } from '../core/types.js';
import { readTextFileSafe } from '../utils/fs-helpers.js';
import {
  BaseBridgeOfficer,
  computeScoresFromChecks,
  SHARED_CONTAINER_FILE_RX,
  SHARED_IAC_FILE_RX
} from './base-officer.js';
import { CheckEvaluation, OfficerAssessment, OfficerFinding, PeerChallenge } from './types.js';

const MAX_ENV_SCAN_FILES = 2000;

const ENV_VAR_PATTERNS = [
  /process\.env\.([A-Z][A-Z0-9_]{2,})/g,
  /process\.env\[['"]([A-Z][A-Z0-9_]{2,})['"]\]/g,
  /os\.environ(?:\.get)?\(\s*['"]([A-Z][A-Z0-9_]{2,})['"]/g,
  /os\.getenv\(\s*['"]([A-Z][A-Z0-9_]{2,})['"]/g,
  /std::env::var\(\s*['"]([A-Z][A-Z0-9_]{2,})['"]/g
];

const STANDARD_SYSTEM_ENV = new Set([
  'NODE_ENV',
  'HOME',
  'PATH',
  'USER',
  'PWD',
  'CI',
  'TZ',
  'LANG',
  'TERM',
  'SHELL'
]);

/**
 * Engineering Officer — Infrastructure & Target Runtime Readiness Auditor.
 * Computes `runtime_readiness_score` strictly from explicit, inspectable checks.
 */
export class EngineeringOfficer extends BaseBridgeOfficer {
  public readonly role = 'engineering' as const;
  public readonly title = 'Engineering Officer (Infrastructure & Target Runtime)';
  public readonly mainKpiName = 'runtime_readiness_score';
  public readonly mandate =
    'Verify that runtime versions, build/start entrypoints, declarative infrastructure, environment/secret contracts, and operational documentation are complete to run the application in its target runtime.';

  public getBaselinePractices(): KnowledgePractice[] {
    return [
      {
        id: 'eng-runtime-pinning',
        title: 'Deterministic Runtime Version Pinning',
        category: 'runtime',
        description: 'Pin runtime versions via package.json#engines, .nvmrc, .python-version, .tool-versions, go.mod, or rust-toolchain.',
        ruleType: 'process',
        targetKpi: this.mainKpiName,
        weight: 15,
        evidenceSummary: 'Prevents runtime drift between local development, CI, and target deployment environments.',
        evidenceSources: ['12-Factor App II (Dependencies)'],
        version: 1,
        active: true
      },
      {
        id: 'eng-env-contract',
        title: 'Complete Environment & Secret Contract',
        category: 'configuration',
        description: 'Declare every environment variable referenced in production source code within .env.example or IaC variable specs.',
        ruleType: 'control',
        targetKpi: this.mainKpiName,
        weight: 20,
        evidenceSummary: 'Prevents startup failures from undocumented runtime configuration or missing credentials.',
        evidenceSources: ['12-Factor App III (Config)'],
        version: 1,
        active: true
      },
      {
        id: 'eng-declarative-infra',
        title: 'Declarative Container or Infrastructure Specification',
        category: 'infrastructure',
        description: 'Provide reproducible containerization (Dockerfile/Compose) or IaC (Terraform/OpenTofu/Helm/Kubernetes/Pulumi).',
        ruleType: 'methodology',
        targetKpi: this.mainKpiName,
        weight: 25,
        evidenceSummary: 'Eliminates manual target environment provisioning.',
        evidenceSources: ['CNCF Cloud Native Principles'],
        version: 1,
        active: true
      },
      {
        id: 'eng-access-and-runbooks',
        title: 'Access Specification & Operational Runbook',
        category: 'operations',
        description: 'Document required credentials/IAM permissions, build/run commands, and recovery procedures.',
        ruleType: 'process',
        targetKpi: this.mainKpiName,
        weight: 20,
        evidenceSummary: 'Ensures operators and automated agents have complete instructions and access prerequisites.',
        evidenceSources: ['Google SRE Workbook'],
        version: 1,
        active: true
      }
    ];
  }

  public assess(
    workspaceRoot: string,
    projection: WorkspaceProjection,
    topic?: string,
    targetPaths?: string[]
  ): OfficerAssessment {
    const files = this.listWorkspaceFiles(workspaceRoot);
    const checks: CheckEvaluation[] = [];
    const findings: OfficerFinding[] = [];
    const challenges: PeerChallenge[] = [];

    // 1. Application Manifest & Build/Start Entrypoint
    const manifests: string[] = [];
    let hasRuntimePin = false;
    let hasEntrypoint = false;

    if (files.includes('package.json')) {
      manifests.push('package.json');
      const pkgText = readTextFileSafe(path.join(workspaceRoot, 'package.json'), 512_000, workspaceRoot);
      if (pkgText) {
        try {
          const pkg = JSON.parse(pkgText) as {
            engines?: Record<string, string>;
            scripts?: Record<string, string>;
            bin?: unknown;
            main?: string;
          };
          if (pkg.engines && Object.keys(pkg.engines).length > 0) hasRuntimePin = true;
          if (
            pkg.bin ||
            pkg.main ||
            (pkg.scripts && Boolean(pkg.scripts.start || pkg.scripts.build || pkg.scripts.dev))
          ) {
            hasEntrypoint = true;
          }
        } catch {
          // ignore malformed JSON
        }
      }
    }

    for (const m of ['pyproject.toml', 'requirements.txt', 'go.mod', 'Cargo.toml', 'pom.xml', 'build.gradle']) {
      if (files.includes(m)) {
        manifests.push(m);
        hasEntrypoint = true;
        if (m === 'go.mod') {
          const goMod = readTextFileSafe(path.join(workspaceRoot, 'go.mod'), 512_000, workspaceRoot) ?? '';
          if (/^go\s+\d+\.\d+/m.test(goMod)) hasRuntimePin = true;
        }
        if (m === 'pyproject.toml') {
          const pyproj = readTextFileSafe(path.join(workspaceRoot, 'pyproject.toml'), 512_000, workspaceRoot) ?? '';
          if (/requires-python\s*=/i.test(pyproj)) hasRuntimePin = true;
        }
      }
    }

    if (files.includes('Makefile') || files.includes('Justfile')) {
      hasEntrypoint = true;
    }

    if (
      files.some((f) =>
        [
          '.nvmrc',
          '.node-version',
          '.python-version',
          '.tool-versions',
          'mise.toml',
          'rust-toolchain.toml'
        ].includes(path.basename(f))
      )
    ) {
      hasRuntimePin = true;
    }

    checks.push({
      id: 'eng-manifest-and-entrypoint',
      category: 'runtime',
      title: 'Application manifest and build/run entrypoint defined',
      weight: 15,
      applicable: true,
      passed: manifests.length > 0 && hasEntrypoint,
      evidence:
        manifests.length > 0 && hasEntrypoint
          ? `Manifests: ${manifests.join(', ')}`
          : `Manifests: ${manifests.join(', ') || 'none'}, entrypoint=${hasEntrypoint}`
    });

    if (!hasEntrypoint) {
      findings.push({
        id: 'eng-missing-entrypoint',
        severity: 'high',
        category: 'runtime',
        title: 'Missing build or start entrypoint',
        description: 'No executable build/start script or package entrypoint was found.',
        evidence: `Checked package.json, Makefile, Justfile, pyproject.toml, go.mod, Cargo.toml.`,
        affectedPaths: manifests,
        recommendation: 'Define explicit build and start scripts in your project manifest.'
      });
    }

    checks.push({
      id: 'eng-runtime-pinned',
      category: 'runtime',
      title: 'Target runtime version pinned',
      weight: 15,
      applicable: true,
      passed: hasRuntimePin,
      evidence: hasRuntimePin
        ? 'Runtime version constraint declared.'
        : 'No engines, .nvmrc, .python-version, .tool-versions, or go/python version directive found.'
    });

    if (!hasRuntimePin) {
      findings.push({
        id: 'eng-no-runtime-pin',
        severity: 'medium',
        category: 'runtime',
        title: 'Target runtime version is not pinned',
        description: 'Unpinned runtime versions risk subtle behavior drift in target environments.',
        evidence: `Manifests present: ${manifests.join(', ') || 'none'}`,
        affectedPaths: manifests,
        recommendation: 'Pin exact runtime version constraints in package.json#engines or .tool-versions.'
      });
    }

    // 2. Containerization & IaC (shared canonical regexes with BridgeOfficer)
    const containerFiles = files.filter((f) => SHARED_CONTAINER_FILE_RX.test(f));
    const validContainerFile = containerFiles.some((f) => {
      const content = readTextFileSafe(path.join(workspaceRoot, f), 512_000, workspaceRoot) ?? '';
      if (/compose/i.test(f)) return /\bservices:/i.test(content);
      return /^\s*FROM\s+\S+/im.test(content) && /^\s*(?:ENTRYPOINT|CMD)\s+/im.test(content);
    });
    const iacFiles = files.filter((f) => SHARED_IAC_FILE_RX.test(f));
    const hasDeclarativeInfra = validContainerFile || iacFiles.length > 0;

    checks.push({
      id: 'eng-declarative-infra',
      category: 'infrastructure',
      title: 'Declarative container or infrastructure specification present',
      weight: 25,
      applicable: true,
      passed: hasDeclarativeInfra,
      evidence: hasDeclarativeInfra
        ? `Container/IaC files: ${[...containerFiles, ...iacFiles].join(', ')}`
        : 'No valid Dockerfile, compose.yaml, Terraform, Helm, or Kubernetes manifest found.'
    });

    if (!hasDeclarativeInfra) {
      findings.push({
        id: 'eng-no-iac-or-container',
        severity: 'high',
        category: 'infrastructure',
        title: 'Missing declarative container or infrastructure specification',
        description: 'Target runtime cannot be reproducibly provisioned without container or IaC manifests.',
        evidence: 'No valid Dockerfile (FROM + ENTRYPOINT/CMD), compose.yaml, or IaC files detected.',
        affectedPaths: [],
        recommendation: 'Add a deterministic Dockerfile/compose.yaml or IaC definitions for target runtime provisioning.'
      });
    }

    // 3. Environment & Secret Contract Completeness
    const referencedEnvVars = new Set<string>();
    const declaredEnvVars = new Set<string>();
    const envExampleFiles = files.filter((f) => /\.env\.(example|sample|template)$/i.test(path.basename(f)));

    for (const ef of envExampleFiles) {
      const content = readTextFileSafe(path.join(workspaceRoot, ef), 512_000, workspaceRoot) ?? '';
      for (const line of content.split(/\r?\n/)) {
        const m = /^\s*([A-Z][A-Z0-9_]+)\s*=/.exec(line);
        if (m?.[1]) declaredEnvVars.add(m[1]);
      }
    }

    const prodCodeFiles = this.prioritizeTargetPaths(
      files.filter(
        (f) =>
          /\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs)$/i.test(f) &&
          !/(^|\/)(tests?|__tests__|spec)\/|\.(test|spec)\./i.test(f)
      ),
      targetPaths
    );
    for (const cf of prodCodeFiles.slice(0, MAX_ENV_SCAN_FILES)) {
      const content = readTextFileSafe(path.join(workspaceRoot, cf), 200_000, workspaceRoot);
      if (!content) continue;
      for (const rx of ENV_VAR_PATTERNS) {
        rx.lastIndex = 0;
        let m: RegExpExecArray | null;
        while ((m = rx.exec(content)) !== null) {
          const name = m[1]!;
          if (!STANDARD_SYSTEM_ENV.has(name) && !name.startsWith('N1_SHELL_')) {
            referencedEnvVars.add(name);
          }
        }
      }
    }

    const undocumentedEnvVars = Array.from(referencedEnvVars)
      .filter((v) => !declaredEnvVars.has(v))
      .sort();

    checks.push({
      id: 'eng-env-contract',
      category: 'configuration',
      title: 'All production environment variables documented in .env.example',
      weight: 20,
      applicable: referencedEnvVars.size > 0,
      passed: undocumentedEnvVars.length === 0,
      evidence:
        referencedEnvVars.size === 0
          ? 'No custom environment variables referenced in production code.'
          : undocumentedEnvVars.length === 0
            ? `All ${referencedEnvVars.size} referenced env var(s) declared in ${envExampleFiles.join(', ')}.`
            : `Undocumented env var(s): ${undocumentedEnvVars.join(', ')}`
    });

    if (undocumentedEnvVars.length > 0) {
      findings.push({
        id: 'eng-undocumented-env-vars',
        severity: undocumentedEnvVars.length >= 3 ? 'high' : 'medium',
        category: 'configuration',
        title: `${undocumentedEnvVars.length} runtime environment variable(s) undocumented`,
        description: 'Production code reads environment variables missing from .env.example.',
        evidence: `Undocumented variables: ${undocumentedEnvVars.slice(0, 15).join(', ')}`,
        affectedPaths: envExampleFiles,
        recommendation: `Declare ${undocumentedEnvVars.slice(0, 8).join(', ')} in .env.example.`
      });
    }

    // 4. Access & Operational Documentation
    const accessOrOpsFiles = files.filter((f) =>
      /(^|\/)(README\.md|RUNBOOK\.md|OPERATIONS\.md|docs\/.*|infra\/.*|iam.*\.tf|rbac.*\.ya?ml)$/i.test(f)
    );
    const combinedOpsDocs = accessOrOpsFiles
      .slice(0, 10)
      .map((f) => readTextFileSafe(path.join(workspaceRoot, f), 100_000, workspaceRoot) ?? '')
      .join('\n');
    const hasAccessDocumentation =
      iacFiles.some((f) => /(iam|rbac|role|policy|serviceaccount)/i.test(f)) ||
      (combinedOpsDocs.length >= 200 &&
        /(credential|token|permission|iam|secret|environment|configuration)/i.test(combinedOpsDocs));
    const hasRunbookDocumentation =
      combinedOpsDocs.length >= 200 && /(build|install|usage|run|deploy|verify|recovery)/i.test(combinedOpsDocs);

    checks.push({
      id: 'eng-access-documented',
      category: 'access',
      title: 'Target runtime access/credential requirements specified',
      weight: 10,
      applicable: true,
      passed: hasAccessDocumentation,
      evidence: hasAccessDocumentation
        ? `Documented across ${accessOrOpsFiles.slice(0, 4).join(', ')}`
        : 'No IAM/RBAC manifests or credential/access documentation found.'
    });

    if (!hasAccessDocumentation) {
      findings.push({
        id: 'eng-missing-access-manifest',
        severity: 'medium',
        category: 'access',
        title: 'Missing access and credential specification',
        description: 'Required runtime credentials, tokens, or IAM roles are not documented or codified.',
        evidence: 'Scanned IaC manifests and project documentation.',
        affectedPaths: [],
        recommendation: 'Document required tokens/permissions or provide IAM/RBAC definitions.'
      });
    }

    checks.push({
      id: 'eng-operational-runbook',
      category: 'operations',
      title: 'Build, run, and operational procedures documented',
      weight: 10,
      applicable: true,
      passed: hasRunbookDocumentation,
      evidence: hasRunbookDocumentation
        ? 'Operational instructions present in repository docs.'
        : 'Missing build/run/recovery documentation.'
    });

    if (!hasRunbookDocumentation) {
      findings.push({
        id: 'eng-missing-runbook',
        severity: 'low',
        category: 'operations',
        title: 'Missing operational runbook or build/run documentation',
        description: 'Operators lack documented build, execution, and recovery steps.',
        evidence: 'README.md / docs/ missing operational commands.',
        affectedPaths: [],
        recommendation: 'Document build, startup, verification, and recovery steps in README.md or RUNBOOK.md.'
      });
    }

    // 5. Stream Runtime Stability (Unresolved Crashes)
    const unresolvedCrashes = projection.crashes.filter((c) => !c.resolvedByEventId);
    checks.push({
      id: 'eng-no-unresolved-crashes',
      category: 'operations',
      title: 'Zero unresolved execution crashes in workspace stream',
      weight: 15,
      applicable: projection.crashes.length > 0,
      passed: unresolvedCrashes.length === 0,
      evidence:
        projection.crashes.length === 0
          ? 'No crashes recorded in stream.'
          : `${unresolvedCrashes.length} unresolved of ${projection.crashes.length} recorded crash(es).`
    });

    if (unresolvedCrashes.length > 0) {
      findings.push({
        id: 'eng-unresolved-stream-crashes',
        severity: 'high',
        category: 'operations',
        title: `${unresolvedCrashes.length} unresolved crash/failure event(s) in stream`,
        description: 'Recorded command failures in the workspace stream have not yet succeeded.',
        evidence: unresolvedCrashes
          .slice(-3)
          .map((c) => `#${c.seq} ${c.command}: ${c.errorSignature}`)
          .join(' | '),
        affectedPaths: Array.from(new Set(unresolvedCrashes.flatMap((c) => c.affectedPaths))),
        recommendation: 'Resolve failing commands and verify green execution via `n1 exec`.'
      });
    }

    // Dynamic evolved practices
    const dynamic = this.evaluateDynamicPractices(workspaceRoot, files, projection);
    checks.push(...dynamic.checks);
    findings.push(...dynamic.findings);

    const { kpiScore, kpiBreakdown } = computeScoresFromChecks(checks);

    if (!hasDeclarativeInfra) {
      challenges.push({
        targetOfficer: 'bridge',
        challenge: 'Automated deployment lacks declarative container or IaC runtime specifications.',
        rationale: 'Continuous Delivery requires reproducible environment definitions.',
        relatedFindingIds: ['eng-no-iac-or-container']
      });
    }
    if (undocumentedEnvVars.length > 0) {
      challenges.push({
        targetOfficer: 'security',
        challenge: `Verify secret handling for ${undocumentedEnvVars.length} undocumented env var(s): ${undocumentedEnvVars.slice(0, 5).join(', ')}.`,
        rationale: 'Undocumented runtime variables risk ad-hoc credential exposure.',
        relatedFindingIds: ['eng-undocumented-env-vars']
      });
    }

    const effectivePractices = this.getEffectivePractices(projection);
    const officerProj = projection.officers[this.role];
    const passedCount = checks.filter((c) => c.applicable && c.passed).length;
    const applicableCount = checks.filter((c) => c.applicable).length;

    const stance = `${this.mainKpiName}=${kpiScore}/100 (${passedCount}/${applicableCount} checks passed, ${findings.length} finding(s))${topic ? ` [${topic}]` : ''}.`;

    return {
      officer: this.role,
      officerTitle: this.title,
      mainKpiName: this.mainKpiName,
      kpiScore,
      kpiBreakdown,
      checks,
      findings,
      artifacts: {
        runtimeCompletenessManifest: {
          manifests,
          hasRuntimePin,
          hasEntrypoint,
          containerFiles,
          iacFiles,
          referencedEnvVars: Array.from(referencedEnvVars).sort(),
          declaredEnvVars: Array.from(declaredEnvVars).sort(),
          undocumentedEnvVars,
          hasAccessDocumentation,
          hasRunbookDocumentation,
          unresolvedCrashCount: unresolvedCrashes.length
        }
      },
      stance,
      challengesToPeers: challenges,
      activePracticeCount: effectivePractices.length,
      knowledgeVersion: officerProj?.knowledgeVersion ?? 1,
      evaluatedAt: new Date().toISOString()
    };
  }
}

import { spawnSync } from 'node:child_process';
import { z } from 'zod';
import { ReplayEngine } from '../core/replay-engine.js';
import { StreamStore } from '../core/stream-store.js';
import { KnowledgePractice, OfficerRole, WorkspaceProjection } from '../core/types.js';
import { buildSanitizedChildEnv } from '../utils/redactor.js';
import { validateRegexSafety } from '../utils/safe-regex.js';
import { evaluatePracticeMatcherOnVirtualFiles } from './base-officer.js';
import { createDefaultCrewRoster } from './party-mode.js';
import {
  CrewOfficer,
  EvolutionVerdict,
  KnowledgeUpdateProposal,
  VerificationSample
} from './types.js';

export const KnowledgeUpdateProposalSchema = z.object({
  officer: z.enum(['engineering', 'security', 'bridge']),
  practice: z.object({
    id: z.string().min(2).max(120).regex(/^[a-zA-Z0-9._-]+$/),
    title: z.string().min(3).max(200),
    category: z.string().min(2).max(80),
    description: z.string().min(3).max(1000),
    ruleType: z.enum(['check', 'tool', 'methodology', 'process', 'control']),
    targetKpi: z.string().min(2).max(80),
    weight: z.number().min(1).max(100).optional(),
    evidenceSummary: z.string().min(3).max(1000),
    evidenceSources: z.array(z.string().min(1)).default([]),
    matcher: z
      .object({
        fileGlob: z.string().min(1).max(256).refine((s) => !s.includes('\0'), 'null byte disallowed').optional(),
        contentRegex: z.string().min(1).max(512).optional(),
        missingFile: z.string().min(1).max(256).refine((s) => !s.includes('\0'), 'null byte disallowed').optional(),
        requiredContentRegex: z.string().min(1).max(512).optional(),
        severity: z.enum(['low', 'medium', 'high', 'critical']).optional()
      })
      .optional()
  }),
  proof: z.object({
    kind: z.enum(['counterfactual_replay', 'empirical_benchmark']),
    sources: z.array(z.string().min(1)),
    methodology: z.string(),
    counterfactualEventIds: z.array(z.string().min(1)).optional(),
    positiveSamples: z.array(z.object({ path: z.string().min(1), content: z.string() })).optional(),
    negativeSamples: z.array(z.object({ path: z.string().min(1), content: z.string() })).optional(),
    reproducibleCommand: z.string().max(1000).optional()
  }),
  allowCrossKpiTradeoff: z.boolean().optional()
});

export interface ProposeUpdateOptions {
  /**
   * Security gate (CWE-78): defaults to `false`.
   * Shell execution of `proof.reproducibleCommand` is ONLY permitted when explicitly
   * opted in by a trusted local operator (never over untrusted MCP inputs).
   */
  allowCommandExecution?: boolean;
}

export interface AuditRegressionOptions {
  /**
   * By default, valid stricter rules that genuinely catch new workspace defects are NOT
   * auto-reverted just because the workspace's live score dropped when a defect appeared.
   * Set true to explicitly force reverting on any live score drop.
   */
  forceRevertOnStrictnessDrop?: boolean;
}

/**
 * Empirically Verified KPI-Gated Knowledge Evolution Engine.
 *
 * Security & Verification Guarantees:
 *  - Full Zod schema validation of proposals
 *  - Static ReDoS safety validation of all proposed matcher regexes
 *  - Shell command execution (`empirical_benchmark`) disabled by default (`allowCommandExecution: false`);
 *    when explicitly opted in, executes with credential-stripped environment (`buildSanitizedChildEnv`)
 *    and strict timeout/buffer caps
 *  - Real counterfactual matcher corpus execution & real cross-officer KPI regression simulation
 */
export class KnowledgeEvolutionEngine {
  private readonly store: StreamStore;
  private readonly replay: ReplayEngine;
  private readonly roster: Record<OfficerRole, CrewOfficer>;
  private readonly minProvenDelta: number;

  constructor(
    store: StreamStore,
    replay: ReplayEngine,
    roster?: Record<OfficerRole, CrewOfficer>,
    minProvenDelta = 0.5
  ) {
    this.store = store;
    this.replay = replay;
    this.roster = roster ?? createDefaultCrewRoster();
    this.minProvenDelta = minProvenDelta;
  }

  public proposeUpdate(
    rawProposal: KnowledgeUpdateProposal,
    options: ProposeUpdateOptions = {}
  ): EvolutionVerdict {
    const proposal = KnowledgeUpdateProposalSchema.parse(rawProposal) as KnowledgeUpdateProposal;
    const officer = this.roster[proposal.officer];
    const reasons: string[] = [];

    const proposedEv = this.store.append({
      type: 'officer.knowledge.proposed',
      actor: { kind: 'officer', id: proposal.officer, name: officer.title },
      harness: 'evolution-engine',
      summary: `Proposed expertise update for ${proposal.officer}: ${proposal.practice.title}`,
      tags: ['evolution', 'proposal', proposal.officer],
      payload: {
        officer: proposal.officer,
        practiceId: proposal.practice.id,
        targetKpi: proposal.practice.targetKpi,
        proofKind: proposal.proof.kind
      }
    });

    // Gate 1: Target KPI must match the officer's main KPI and not collide with baseline IDs
    if (proposal.practice.targetKpi !== officer.mainKpiName) {
      reasons.push(
        `Target KPI mismatch: ${proposal.officer} main KPI is "${officer.mainKpiName}", got "${proposal.practice.targetKpi}".`
      );
    }
    const baselineIds = new Set(officer.getBaselinePractices().map((b) => b.id));
    if (baselineIds.has(proposal.practice.id)) {
      reasons.push(
        `Practice ID "${proposal.practice.id}" collides with a built-in baseline practice for ${proposal.officer}; use a distinct evolved practice ID.`
      );
    }

    // Gate 2: Methodology and source references required
    if (!proposal.proof.methodology || proposal.proof.methodology.trim().length < 15) {
      reasons.push('Proof requires a concrete verification methodology (>=15 chars).');
    }
    if (!proposal.proof.sources || proposal.proof.sources.length === 0) {
      reasons.push('Proof must cite at least one verifiable empirical source or stream event.');
    }

    // Gate 2b: Static ReDoS safety verification on any proposed regex matchers
    if (proposal.practice.matcher?.contentRegex) {
      const safety = validateRegexSafety(proposal.practice.matcher.contentRegex);
      if (!safety.safe) {
        reasons.push(`Unsafe practice.matcher.contentRegex rejected: ${safety.reason}`);
      }
    }
    if (proposal.practice.matcher?.requiredContentRegex) {
      const safety = validateRegexSafety(proposal.practice.matcher.requiredContentRegex);
      if (!safety.safe) {
        reasons.push(`Unsafe practice.matcher.requiredContentRegex rejected: ${safety.reason}`);
      }
    }

    const stateBefore = this.replay.getCurrentState();
    const existingActiveMatchers = Object.values(
      stateBefore.officers[proposal.officer]?.practices ?? {}
    ).filter((p) => p.active && p.matcher);

    let truePositivesBefore = 0;
    let truePositivesAfter = 0;
    let falsePositivesAfter = 0;
    let measuredDelta = 0;
    let commandExecuted: string | undefined;

    // Gate 3: Actual Empirical / Counterfactual Execution
    if (proposal.proof.kind === 'counterfactual_replay') {
      const eventIds = proposal.proof.counterfactualEventIds ?? [];
      if (eventIds.length === 0) {
        reasons.push(
          'Counterfactual replay proof must reference at least one real event ID in .numberone/stream.'
        );
      }
      const eventDerivedSamples: VerificationSample[] = [];
      for (const id of eventIds) {
        const ev = this.store.getEventById(id);
        if (!ev) {
          reasons.push(`Counterfactual replay references nonexistent stream event: ${id}`);
          continue;
        }
        for (const blob of ev.blobs) {
          const text = this.store.readBlobUtf8(blob.sha256);
          if (text !== null) {
            eventDerivedSamples.push({
              path: ev.affectedPaths[0] ?? `${ev.id}-${blob.key}`,
              content: text
            });
          }
        }
      }

      if (!proposal.practice.matcher) {
        reasons.push(
          'Counterfactual replay proof requires an executable `practice.matcher` to verify detection on historical cases.'
        );
      } else if (reasons.length === 0) {
        const positiveCases: VerificationSample[][] = [];
        for (const sample of proposal.proof.positiveSamples ?? []) {
          positiveCases.push([sample]);
        }
        // Always include event-derived blobs when present so unrelated stream event IDs with blobs
        // cannot be cited to rubber-stamp synthetic positiveSamples!
        if (eventDerivedSamples.length > 0) {
          positiveCases.push(eventDerivedSamples);
        }
        if (
          positiveCases.length === 0 &&
          proposal.practice.matcher.missingFile &&
          eventIds.length > 0
        ) {
          positiveCases.push([]);
        }

        if (positiveCases.length === 0) {
          reasons.push(
            'Counterfactual replay requires defective `positiveSamples` or stream event blobs to measure detection gain.'
          );
        } else {
          const negativeSamples = proposal.proof.negativeSamples ?? [];
          if (negativeSamples.length === 0) {
            reasons.push(
              'Counterfactual replay requires at least one clean `negativeSamples` entry to verify 0% false-positive rate.'
            );
          }

          for (const caseFiles of positiveCases) {
            const caughtBefore = existingActiveMatchers.some(
              (p) => evaluatePracticeMatcherOnVirtualFiles(p, caseFiles).violated
            );
            const caughtByCandidate = evaluatePracticeMatcherOnVirtualFiles(
              proposal.practice,
              caseFiles
            ).violated;
            if (caughtBefore) truePositivesBefore++;
            if (caughtBefore || caughtByCandidate) truePositivesAfter++;
          }

          // If event-derived blobs existed alongside synthetic positiveSamples, ensure the candidate
          // actually caught at least one event-derived blob rather than ignoring the referenced incident
          if (
            eventDerivedSamples.length > 0 &&
            (proposal.proof.positiveSamples?.length ?? 0) > 0 &&
            !evaluatePracticeMatcherOnVirtualFiles(proposal.practice, eventDerivedSamples).violated
          ) {
            reasons.push(
              'Candidate matcher did not detect any defect in the blobs of the referenced counterfactualEventIds.'
            );
          }

          if (negativeSamples.length > 0) {
            const fp = evaluatePracticeMatcherOnVirtualFiles(proposal.practice, negativeSamples);
            if (fp.violated) {
              falsePositivesAfter = 1;
              reasons.push(
                `Candidate matcher produced false positive on clean negativeSamples: ${fp.evidence}`
              );
            }
          }

          const recallBefore = (truePositivesBefore / positiveCases.length) * 100;
          const recallAfter = (truePositivesAfter / positiveCases.length) * 100;
          measuredDelta = Math.round((recallAfter - recallBefore) * 100) / 100;

          if (measuredDelta < this.minProvenDelta) {
            reasons.push(
              `Counterfactual verification showed zero new defect detection: recallBefore=${recallBefore.toFixed(1)}%, recallAfter=${recallAfter.toFixed(1)}% (delta=${measuredDelta}).`
            );
          }
        }
      }
    } else if (proposal.proof.kind === 'empirical_benchmark') {
      if (!proposal.proof.reproducibleCommand) {
        reasons.push(
          'Empirical benchmark proof requires an executable `reproducibleCommand` outputting {"kpiBefore": number, "kpiAfter": number}.'
        );
      } else if (options.allowCommandExecution !== true) {
        reasons.push(
          'Benchmark shell command execution is disabled by default for security (CWE-78). Re-run with explicit local opt-in (`--allow-exec` / `allowCommandExecution: true`) or use `counterfactual_replay`.'
        );
      } else if (proposal.proof.reproducibleCommand.includes('\0')) {
        reasons.push('Benchmark command contains disallowed null byte.');
      } else {
        commandExecuted = proposal.proof.reproducibleCommand;
        const proc = spawnSync(proposal.proof.reproducibleCommand, {
          cwd: this.store.workspaceRoot,
          shell: true,
          encoding: 'utf8',
          env: buildSanitizedChildEnv(process.env),
          timeout: 15_000,
          maxBuffer: 1_048_576
        });
        if (proc.status !== 0) {
          reasons.push(
            `Benchmark command exited with status ${proc.status ?? 'null'}: ${(proc.stderr || proc.stdout || '').trim().slice(0, 200)}`
          );
        } else {
          try {
            const lines = (proc.stdout ?? '')
              .trim()
              .split(/\r?\n/)
              .map((l) => l.trim())
              .filter(Boolean);
            const jsonLine = lines.reverse().find((l) => l.startsWith('{') && l.endsWith('}'));
            if (!jsonLine) {
              throw new Error('No JSON metric object found on stdout');
            }
            const parsed = JSON.parse(jsonLine) as {
              kpiBefore?: unknown;
              kpiAfter?: unknown;
            };
            if (
              typeof parsed.kpiBefore !== 'number' ||
              typeof parsed.kpiAfter !== 'number' ||
              !Number.isFinite(parsed.kpiBefore) ||
              !Number.isFinite(parsed.kpiAfter)
            ) {
              throw new Error('JSON output must contain finite numeric kpiBefore and kpiAfter');
            }
            measuredDelta = Math.round((parsed.kpiAfter - parsed.kpiBefore) * 100) / 100;
            if (measuredDelta < this.minProvenDelta) {
              reasons.push(
                `Executed benchmark command measured insufficient KPI delta: ${measuredDelta} (before=${parsed.kpiBefore}, after=${parsed.kpiAfter}; min=+${this.minProvenDelta}).`
              );
            }
          } catch (err) {
            reasons.push(
              `Invalid benchmark output from "${proposal.proof.reproducibleCommand}": ${err instanceof Error ? err.message : String(err)}`
            );
          }
        }
      }
    }

    // Gate 4: Real Cross-Officer KPI Simulation
    const scoresBefore: Record<OfficerRole, number> = {
      engineering: this.roster.engineering.assess(this.store.workspaceRoot, stateBefore).kpiScore,
      security: this.roster.security.assess(this.store.workspaceRoot, stateBefore).kpiScore,
      bridge: this.roster.bridge.assess(this.store.workspaceRoot, stateBefore).kpiScore
    };

    const existingPractice = stateBefore.officers[proposal.officer]?.practices[proposal.practice.id];
    const nextVersion = (existingPractice?.version ?? 0) + 1;
    const candidatePractice: KnowledgePractice = {
      ...proposal.practice,
      provenKpiDelta: measuredDelta,
      evidenceSources: Array.from(
        new Set([...proposal.practice.evidenceSources, ...proposal.proof.sources])
      ),
      addedAt: new Date().toISOString(),
      version: nextVersion,
      active: true
    };

    const simulatedState: WorkspaceProjection = structuredClone(stateBefore);
    simulatedState.officers[proposal.officer].practices[candidatePractice.id] = candidatePractice;
    simulatedState.officers[proposal.officer].knowledgeVersion += 1;

    const scoresAfter: Record<OfficerRole, number> = {
      engineering: this.roster.engineering.assess(this.store.workspaceRoot, simulatedState).kpiScore,
      security: this.roster.security.assess(this.store.workspaceRoot, simulatedState).kpiScore,
      bridge: this.roster.bridge.assess(this.store.workspaceRoot, simulatedState).kpiScore
    };

    const crossKpiImpact: Record<OfficerRole, number> = {
      engineering: Math.round((scoresAfter.engineering - scoresBefore.engineering) * 10) / 10,
      security: Math.round((scoresAfter.security - scoresBefore.security) * 10) / 10,
      bridge: Math.round((scoresAfter.bridge - scoresBefore.bridge) * 10) / 10
    };

    for (const role of ['engineering', 'security', 'bridge'] as const) {
      if (role !== proposal.officer && crossKpiImpact[role] < 0 && !proposal.allowCrossKpiTradeoff) {
        reasons.push(
          `Candidate practice caused cross-officer KPI regression on ${role} (${crossKpiImpact[role]}).`
        );
      }
    }

    const verificationMetrics = {
      truePositivesBefore,
      truePositivesAfter,
      falsePositivesAfter,
      commandExecuted
    };

    if (reasons.length > 0) {
      const rejectEv = this.store.append({
        type: 'officer.knowledge.rejected',
        actor: { kind: 'numberone', id: 'evolution-engine', name: 'Number One Evolution Gate' },
        harness: 'evolution-engine',
        causationId: proposedEv.id,
        summary: `Rejected knowledge update "${proposal.practice.title}" for ${proposal.officer}: ${reasons[0]}`,
        tags: ['evolution', 'rejected', proposal.officer],
        payload: {
          officer: proposal.officer,
          practiceId: proposal.practice.id,
          measuredDelta,
          verificationMetrics,
          crossKpiImpact,
          reasons
        }
      });

      return {
        accepted: false,
        officer: proposal.officer,
        practiceId: proposal.practice.id,
        measuredKpiDelta: measuredDelta,
        reasons,
        eventId: rejectEv.id,
        verificationMetrics,
        crossKpiImpact
      };
    }

    const updateEv = this.store.append({
      type: 'officer.knowledge.updated',
      actor: { kind: 'numberone', id: 'evolution-engine', name: 'Number One Evolution Gate' },
      harness: 'evolution-engine',
      causationId: proposedEv.id,
      summary: `Promoted verified practice for ${proposal.officer}: "${candidatePractice.title}" (+${measuredDelta} ${
        proposal.proof.kind === 'counterfactual_replay' ? 'detection recall' : officer.mainKpiName
      })`,
      tags: ['evolution', 'promoted', proposal.officer, officer.mainKpiName],
      payload: {
        officer: proposal.officer,
        practice: candidatePractice,
        proof: {
          kind: proposal.proof.kind,
          sources: proposal.proof.sources,
          methodology: proposal.proof.methodology,
          counterfactualEventIds: proposal.proof.counterfactualEventIds,
          reproducibleCommand: proposal.proof.reproducibleCommand
        },
        measuredDelta,
        verificationMetrics,
        scoresBefore,
        scoresAfter,
        crossKpiImpact
      }
    });

    return {
      accepted: true,
      officer: proposal.officer,
      practiceId: candidatePractice.id,
      measuredKpiDelta: measuredDelta,
      reasons: [
        `Verified via ${proposal.proof.kind}: measured gain +${measuredDelta} with 0 false positives.`
      ],
      eventId: updateEv.id,
      verificationMetrics,
      crossKpiImpact
    };
  }

  public revertPractice(officerRole: OfficerRole, practiceId: string, reason: string): string {
    const ev = this.store.append({
      type: 'officer.knowledge.reverted',
      actor: { kind: 'numberone', id: 'evolution-engine', name: 'Number One Evolution Gate' },
      harness: 'evolution-engine',
      summary: `Reverted practice "${practiceId}" for ${officerRole}: ${reason}`,
      tags: ['evolution', 'reverted', officerRole],
      payload: {
        officer: officerRole,
        practiceId,
        reason
      }
    });
    return ev.id;
  }

  public auditLiveRegressions(
    officerRole: OfficerRole,
    regressionThreshold = 5,
    options: AuditRegressionOptions = {}
  ): string[] {
    const state = this.replay.getCurrentState();
    const officerState = state.officers[officerRole];
    const history = officerState.kpiHistory;
    if (history.length < 2) return [];

    const latest = history[history.length - 1]!;
    const previous = history[history.length - 2]!;
    const drop = previous.score - latest.score;
    if (drop < regressionThreshold) return [];

    const activeEvolved = Object.values(officerState.practices)
      .filter((p) => p.active)
      .sort((a, b) => (b.addedAt ?? '').localeCompare(a.addedAt ?? ''));

    if (activeEvolved.length === 0) return [];
    const newest = activeEvolved[0]!;

    // Guard: do NOT auto-revert a valid stricter practice simply because it caught real defects
    // in the workspace! Re-evaluate the officer to distinguish broken matchers from valid detections.
    const liveAssessment = this.roster[officerRole].assess(this.store.workspaceRoot, state);
    const evolvedCheck = liveAssessment.checks.find((c) => c.id === `evolved-${newest.id}`);
    const isBrokenMatcher = Boolean(evolvedCheck?.evidence.startsWith('Skipped unsafe'));
    const causedValidDetectionDrop = Boolean(
      evolvedCheck && !evolvedCheck.passed && !isBrokenMatcher
    );

    if (causedValidDetectionDrop && !options.forceRevertOnStrictnessDrop) {
      return [];
    }

    this.revertPractice(
      officerRole,
      newest.id,
      isBrokenMatcher
        ? `Evolved practice matcher skipped as unsafe during live audit (KPI dropped ${previous.score} -> ${latest.score}).`
        : `Live ${officerState.mainKpiName} dropped by ${drop.toFixed(1)} points (${previous.score} -> ${latest.score}).`
    );
    return [newest.id];
  }
}

import { NumberOneConfig } from '../core/types.js';
import {
  readResponseJsonBounded,
  resilientFetch,
  resolveScopedEnvVar
} from '../utils/http.js';
import { redactSecrets } from '../utils/redactor.js';

export interface LlmMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

export interface LlmProvider {
  readonly isAvailable: boolean;
  readonly providerName: string;
  complete(messages: LlmMessage[], maxTokens?: number): Promise<string | null>;
}

/**
 * Harness-agnostic pluggable LLM provider.
 * Uses resilientFetch with strict timeouts, redirect:error, SSRF guards, provider-scoped
 * env-var resolution, header-only auth, bounded JSON body reading, and egress secret redaction.
 */
export class PluggableLlmProvider implements LlmProvider {
  private readonly cfg: NonNullable<NumberOneConfig['llm']>;

  constructor(config?: NumberOneConfig['llm']) {
    this.cfg = config ?? { provider: 'none' };
  }

  public get providerName(): string {
    return this.cfg.provider;
  }

  private resolveApiKey(): string | null {
    if (this.cfg.provider === 'none') return null;
    if (this.cfg.provider === 'openai-compatible') {
      return resolveScopedEnvVar(this.cfg.apiKeyEnvVar, ['OPENAI_', 'LLM_'], ['OPENAI_API_KEY']);
    }
    if (this.cfg.provider === 'anthropic') {
      return resolveScopedEnvVar(this.cfg.apiKeyEnvVar, ['ANTHROPIC_', 'LLM_'], ['ANTHROPIC_API_KEY']);
    }
    if (this.cfg.provider === 'gemini') {
      return resolveScopedEnvVar(
        this.cfg.apiKeyEnvVar,
        ['GEMINI_', 'GOOGLE_', 'LLM_'],
        ['GEMINI_API_KEY']
      );
    }
    return null;
  }

  public get isAvailable(): boolean {
    return this.cfg.provider !== 'none' && Boolean(this.resolveApiKey());
  }

  public async complete(messages: LlmMessage[], maxTokens = 600): Promise<string | null> {
    const apiKey = this.resolveApiKey();
    if (!apiKey || this.cfg.provider === 'none') return null;

    const redactedMessages = messages.map((m) => ({
      role: m.role,
      content: redactSecrets(m.content)
    }));

    try {
      if (this.cfg.provider === 'openai-compatible') {
        const base = (this.cfg.baseUrl ?? 'https://api.openai.com/v1').replace(/\/$/, '');
        const res = await resilientFetch(`${base}/chat/completions`, {
          method: 'POST',
          timeoutMs: 20_000,
          maxRetries: 0,
          headers: {
            Authorization: `Bearer ${apiKey}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            model: this.cfg.model ?? 'gpt-4o-mini',
            messages: redactedMessages,
            max_tokens: maxTokens,
            temperature: 0.2
          })
        });
        if (!res.ok) return null;
        const json = await readResponseJsonBounded<{
          choices?: Array<{ message?: { content?: string } }>;
        }>(res, 2_000_000);
        return json.choices?.[0]?.message?.content?.trim() ?? null;
      }

      if (this.cfg.provider === 'anthropic') {
        const system = redactedMessages
          .filter((m) => m.role === 'system')
          .map((m) => m.content)
          .join('\n');
        const userMsgs = redactedMessages
          .filter((m) => m.role !== 'system')
          .map((m) => ({ role: m.role, content: m.content }));
        const base = (this.cfg.baseUrl ?? 'https://api.anthropic.com').replace(/\/$/, '');
        const res = await resilientFetch(`${base}/v1/messages`, {
          method: 'POST',
          timeoutMs: 20_000,
          maxRetries: 0,
          headers: {
            'x-api-key': apiKey,
            'anthropic-version': '2023-06-01',
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            model: this.cfg.model ?? 'claude-3-5-sonnet-latest',
            max_tokens: maxTokens,
            system,
            messages: userMsgs
          })
        });
        if (!res.ok) return null;
        const json = await readResponseJsonBounded<{
          content?: Array<{ type: string; text?: string }>;
        }>(res, 2_000_000);
        return json.content?.find((c) => c.type === 'text')?.text?.trim() ?? null;
      }

      if (this.cfg.provider === 'gemini') {
        const model = this.cfg.model ?? 'gemini-2.5-flash';
        const base = (this.cfg.baseUrl ?? 'https://generativelanguage.googleapis.com/v1beta').replace(/\/$/, '');
        const combined = redactedMessages.map((m) => `[${m.role.toUpperCase()}]\n${m.content}`).join('\n\n');
        // Pass API key via x-goog-api-key header (never in URL query string!)
        const res = await resilientFetch(`${base}/models/${encodeURIComponent(model)}:generateContent`, {
          method: 'POST',
          timeoutMs: 20_000,
          maxRetries: 0,
          headers: {
            'x-goog-api-key': apiKey,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            contents: [{ parts: [{ text: combined }] }],
            generationConfig: { maxOutputTokens: maxTokens, temperature: 0.2 }
          })
        });
        if (!res.ok) return null;
        const json = await readResponseJsonBounded<{
          candidates?: Array<{ content?: { parts?: Array<{ text?: string }> } }>;
        }>(res, 2_000_000);
        return json.candidates?.[0]?.content?.parts?.[0]?.text?.trim() ?? null;
      }
    } catch {
      return null;
    }
    return null;
  }
}

