        rationale: input.rationale,
        scopePaths: input.scopePaths ?? [],
        scopeTags: input.scopeTags ?? [],
        forbiddenPatterns: input.forbiddenPatterns ?? [],
        requiredPatterns: input.requiredPatterns ?? [],
        severity: input.severity ?? 'mandatory',
