  public openIssue(input: {
    title: string;
    description: string;
    kind?: 'bug' | 'crash' | 'story' | 'epic' | 'task' | 'debt' | 'security' | 'infra' | 'release';
    priority?: 'low' | 'medium' | 'high' | 'critical';
