  createdAt: string;
  author: string;
  body: string;
  eventHash: string;
}

export interface DirectoryScrumIssue {
  id: string;
  key: string;
  issueType: 'Epic' | 'Story' | 'Bug' | 'Task';
  status: 'open' | 'in_progress' | 'done';
  priority: 'low' | 'medium' | 'high' | 'critical';
