];

const EMBEDDED_MARKER_GLOBAL_RX = /<!--\s*numberone:event\s+({[\s\S]*?})\s*-->/g;
const SAFE_GH_SEGMENT_RX = /^[A-Za-z0-9._-]{1,100}$/;

export interface GitHubEmbeddedMeta {
  schemaVersion: 1;
  eventId: string;
  seq: number;
  type: string;
  hash: string;
  prevHash: string;
  harness: string;
  sessionId: string;
  fallbackBlobs: Array<{ key: string; uri: string; sha256: string }>;
  fallbackFields: string[];
}

/**
 * Pure deterministic builder for GitHub Issue/Comment markdown body with embedded integrity block.
 * Neutralizes `-->` in payload previews and redacts metadata BEFORE JSON serialization.
 */
export function buildGitHubIssueBody(event: StreamEvent, fallbackFields: string[]): string {
  const meta: GitHubEmbeddedMeta = {
    schemaVersion: 1,
    eventId: event.id,
    seq: event.seq,
    type: event.type,
    hash: event.hash,
    prevHash: event.prevHash,
    harness: redactSecrets(event.harness),
    sessionId: redactSecrets(event.sessionId),
    fallbackBlobs: event.blobs.map((b) => ({ key: redactSecrets(b.key), uri: b.uri, sha256: b.sha256 })),
    fallbackFields: fallbackFields.map((f) => redactSecrets(f))
  };

  const payloadPreview = redactSecrets(JSON.stringify(event.payload, null, 2).slice(0, 6000)).replace(
    /-->/g,
    '--\\>'
  );

  const lines: string[] = [
    `## Number One Stream Event \`#${event.seq}\` (\`${event.type}\`)`,
    '',
    `- **Event ID**: \`${event.id}\``,
    `- **Timestamp**: ${event.timestamp}`,
    `- **Actor**: \`${event.actor.kind}:${redactSecrets(event.actor.id)}\``,
    `- **Harness / Session**: \`${meta.harness}\` / \`${meta.sessionId}\``,
    `- **Integrity Hash**: \`${event.hash}\``,
    ''
  ];

  if (event.affectedPaths.length > 0) {
    lines.push(`### Affected Paths`, ...event.affectedPaths.map((p) => `- \`${p}\``), '');
  }

  lines.push('### Details', '```json', payloadPreview, '```', '');

  if (event.blobs.length > 0 || fallbackFields.length > 0) {
    lines.push('### `.numberone` Fallback Integrity Pointers');
    for (const blob of event.blobs) {
      lines.push(`- **${redactSecrets(blob.key)}**: \`${blob.uri}\` (${blob.sizeBytes} bytes, ${blob.contentType})`);
    }
    if (fallbackFields.length > 0) {
      lines.push(`- **Local Fallback Fields**: ${meta.fallbackFields.join(', ')}`);
    }
    lines.push('');
  }

  const narrative = redactSecrets(lines.join('\n'));
  return `${narrative}\n<!-- numberone:event ${JSON.stringify(meta)} -->`;
}

/**
 * Extracts the LAST embedded integrity marker (immune to spoofed markers inside payload previews).
 */
export function parseGitHubEmbeddedMeta(body: string): GitHubEmbeddedMeta | null {
  EMBEDDED_MARKER_GLOBAL_RX.lastIndex = 0;
  let lastJson: string | null = null;
  let match: RegExpExecArray | null;
  while ((match = EMBEDDED_MARKER_GLOBAL_RX.exec(body)) !== null) {
    if (match[1]) lastJson = match[1];
  }
  if (!lastJson) return null;
  try {
    return JSON.parse(lastJson) as GitHubEmbeddedMeta;
  } catch {
    return null;
  }
}

export function labelsForGitHubEvent(event: StreamEvent): string[] {
  const labels = new Set<string>(['n1:stream']);
  if (event.type.startsWith('lesson.')) labels.add('n1:lesson');
  if (event.type === 'decision.recorded') labels.add('n1:decision');
  if (event.type.startsWith('directive.')) labels.add('n1:directive');
  if (event.type === 'exec.crashed' || event.type === 'exec.failed') labels.add('n1:crash');
  if (event.type.startsWith('issue.')) labels.add('n1:issue');
  if (event.type.startsWith('crew.')) labels.add('n1:party-mode');
  if (event.type.startsWith('officer.')) labels.add('n1:evolution');

  const officer = event.payload.ownerOfficer ?? event.payload.officer ?? event.payload.issuedBy;
  if (officer === 'engineering' || officer === 'security' || officer === 'bridge') {
    labels.add(`n1:officer:${officer}`);
  }
  return Array.from(labels);
}

/**
 * Builds GraphQL queries covering Repository, Organization, and User scopes for GitHub Projects v2.
 */
export function buildGitHubProjectV2LookupQueries(owner: string, repo: string, number: number) {
  return [
    {
      scope: 'repository' as const,
      query: `query($owner: String!, $repo: String!, $number: Int!) { repository(owner: $owner, name: $repo) { projectV2(number: $number) { id } } }`,
      variables: { owner, repo, number }
    },
    {
      scope: 'organization' as const,
      query: `query($owner: String!, $number: Int!) { organization(login: $owner) { projectV2(number: $number) { id } } }`,
      variables: { owner, number }
    },
    {
      scope: 'user' as const,
      query: `query($owner: String!, $number: Int!) { user(login: $owner) { projectV2(number: $number) { id } } }`,
      variables: { owner, number }
    }
  ];
}

/**
 * GitHub Issues + Labels + Milestones + Comments + Projects v2 persistence adapter.
 */
export class GitHubPersistenceAdapter implements PersistenceAdapter {
  public readonly backend = 'github' as const;
  public readonly name: string;
  private readonly config: GitHubAdapterConfig;
  private readonly apiBaseUrl: string;
  private readonly repoBasePath: string;
  private taxonomyReady = false;
  private availableLabels = new Set<string>();
  private milestoneCache = new Map<string, number>();

  constructor(config: GitHubAdapterConfig) {
    this.config = config;
    this.apiBaseUrl = (config.apiBaseUrl ?? 'https://api.github.com').replace(/\/$/, '');
    this.name = `github:${config.owner}/${config.repo}`;
    if (
      config.enabled &&
      (!SAFE_GH_SEGMENT_RX.test(config.owner) || !SAFE_GH_SEGMENT_RX.test(config.repo))
    ) {
      throw new Error(`Invalid GitHub owner/repo: "${config.owner}/${config.repo}"`);
    }
    this.repoBasePath = `/repos/${encodeURIComponent(config.owner)}/${encodeURIComponent(config.repo)}`;
  }

  public isConfigured(): boolean {
    return Boolean(this.config.enabled && this.config.owner && this.config.repo && this.resolveToken());
  }

  private isOfficialGitHubApi(): boolean {
    try {
      const host = new URL(this.apiBaseUrl).hostname.toLowerCase();
      return host === 'api.github.com' || host.endsWith('.github.com');
    } catch {
      return false;
    }
  }

  private resolveToken(): string | null {
    if (this.config.token) return this.config.token;
    const fromEnv = resolveScopedEnvVar(
      this.config.tokenEnvVar,
      ['GITHUB_', 'GH_'],
      ['GITHUB_TOKEN', 'GH_TOKEN']
    );
    if (fromEnv) return fromEnv;
    // Never forward `gh auth token` to arbitrary non-GitHub hosts (SEC-03)
    if (this.config.useGhCli !== false && this.isOfficialGitHubApi()) {
      try {
        const out = execFileSync('gh', ['auth', 'token'], {
          encoding: 'utf8',
          stdio: ['ignore', 'pipe', 'ignore']
        }).trim();
        if (out) return out;
      } catch {
        // gh CLI not logged in
      }
    }
    return null;
  }

  private async request<T>(method: string, apiPath: string, body?: unknown): Promise<T> {
    const token = this.resolveToken();
    if (!token) {
      throw new Error(`GitHub token unavailable for ${this.name}`);
    }
    const res = await resilientFetch(`${this.apiBaseUrl}${apiPath}`, {
      method,
      allowPrivateHosts: this.config.allowPrivateHosts,
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28',
        'Content-Type': 'application/json',
        'User-Agent': 'numberone-agent/1.0'
      },
      body: body !== undefined ? JSON.stringify(body) : undefined
    });
    if (!res.ok) {
      const txt = await readResponseTextBounded(res, 100_000).catch(() => '');
      throw new Error(`GitHub API ${method} ${apiPath} failed (${res.status}): ${redactSecrets(txt).slice(0, 300)}`);
    }
    if (res.status === 204) return undefined as T;
    return await readResponseJsonBounded<T>(res, 5_000_000);
  }

  private async graphql<T>(query: string, variables: Record<string, unknown>): Promise<T> {
    const data = await this.request<{ data?: T; errors?: Array<{ message: string }> }>(
      'POST',
      '/graphql',
      { query, variables }
    );
    if (data.errors && data.errors.length > 0) {
      throw new Error(`GitHub GraphQL error: ${data.errors.map((e) => e.message).join('; ')}`);
    }
    return data.data as T;
  }

  public async ensureTaxonomy(): Promise<void> {
    if (this.taxonomyReady) return;
    let discoveredOk = false;
    try {
      for (let page = 1; page <= 5; page++) {
        const existing = await this.request<Array<{ name: string }>>(
          'GET',
          `${this.repoBasePath}/labels?per_page=100&page=${page}`
        );
        discoveredOk = true;
        for (const l of existing) {
          this.availableLabels.add(l.name);
        }
        if (existing.length < 100) break;
      }
    } catch {
      // Do not cache taxonomyReady on transient discovery failure
      return;
    }

    for (const label of GITHUB_LABELS) {
      if (!this.availableLabels.has(label.name)) {
        try {
          const created = await this.request<{ name: string }>('POST', `${this.repoBasePath}/labels`, label);
          if (created?.name) this.availableLabels.add(created.name);
        } catch (err) {
          if (err instanceof Error && err.message.includes('(422)')) {
            this.availableLabels.add(label.name);
          }
        }
      }
    }
    if (discoveredOk) this.taxonomyReady = true;
  }

  private async ensureMilestone(title: string): Promise<number | undefined> {
    if (this.milestoneCache.has(title)) return this.milestoneCache.get(title);
    try {
      for (let page = 1; page <= 5; page++) {
        const milestones = await this.request<Array<{ number: number; title: string }>>(
          'GET',
          `${this.repoBasePath}/milestones?state=all&per_page=100&page=${page}`
        );
        for (const m of milestones) {
          this.milestoneCache.set(m.title, m.number);
        }
        if (this.milestoneCache.has(title)) return this.milestoneCache.get(title);
        if (milestones.length < 100) break;
      }
      const created = await this.request<{ number: number }>('POST', `${this.repoBasePath}/milestones`, {
        title,
        description: `Number One milestone: ${title}`
      });
      this.milestoneCache.set(title, created.number);
      return created.number;
    } catch {
      return undefined;
    }
  }

  private async attachToProjectV2(issueNodeId: string): Promise<void> {
    if (!this.config.projectNumber || !issueNodeId) return;
    const lookups = buildGitHubProjectV2LookupQueries(
      this.config.owner,
      this.config.repo,
      this.config.projectNumber
    );
    let projectId: string | undefined;

    for (const lookup of lookups) {
      try {
        const data = await this.graphql<{
          repository?: { projectV2?: { id: string } };
          organization?: { projectV2?: { id: string } };
          user?: { projectV2?: { id: string } };
        }>(lookup.query, lookup.variables);
        projectId =
          data?.repository?.projectV2?.id ??
          data?.organization?.projectV2?.id ??
          data?.user?.projectV2?.id;
        if (projectId) break;
      } catch {
        // Continue to next owner scope
      }
    }

    if (!projectId) return;
    try {
      await this.graphql(
        `mutation($projectId: ID!, $contentId: ID!) {
          addProjectV2ItemById(input: { projectId: $projectId, contentId: $contentId }) {
            item { id }
          }
        }`,
        { projectId, contentId: issueNodeId }
      );
    } catch {
      // Optional enrichment if token lacks `project` scope
    }
  }

  private resolveParentEntityKey(event: StreamEvent): string | null {
    const p = event.payload;
    if (typeof p.issueId === 'string') return `issue:${p.issueId}`;
    if (typeof p.partySessionId === 'string') return `party:${p.partySessionId}`;
    if (typeof p.lessonId === 'string') return `lesson:${p.lessonId}`;
    if (typeof p.directiveId === 'string') return `directive:${p.directiveId}`;
    if (event.correlationId) return `corr:${event.correlationId}`;
    return null;
  }

  public async pushEvent(event: StreamEvent, context: PushEventContext): Promise<PushEventOutcome> {
    await this.ensureTaxonomy();

    if (
      event.type === 'workspace.snapshot' ||
      event.type === 'fs.created' ||
      event.type === 'fs.modified' ||
      event.type === 'fs.deleted' ||
      event.type === 'fs.renamed' ||
      event.type === 'exec.started' ||
      event.type === 'sync.pushed' ||
      event.type === 'sync.pulled' ||
      event.type === 'sync.reconciled'
    ) {
      return {
        synced: false,
        fallbackFields: ['fullEvent', 'rawDiffs', 'blobs'],
        skippedReason: `Routed to .numberone fallback ledger (high-frequency local event ${event.type})`
      };
    }

    const fallbackFields: string[] = [];
    if (event.blobs.length > 0) fallbackFields.push('blobs');

    const entityKey = this.resolveParentEntityKey(event);
    const existingEntityRef = entityKey ? context.ledger.entities[entityKey]?.[this.backend] : undefined;

    if (
      existingEntityRef &&
      (event.type === 'issue.updated' ||
        event.type === 'issue.resolved' ||
        event.type === 'issue.reopened' ||
        event.type === 'crew.opinion' ||
        event.type === 'crew.challenge' ||
        event.type === 'crew.consensus' ||
        event.type === 'crew.veto' ||
        event.type === 'lesson.verified' ||
        event.type === 'lesson.applied' ||
        event.type === 'lesson.superseded' ||
        event.type === 'directive.superseded' ||
        event.type === 'chat.thinking')
    ) {
      const rawNum = (existingEntityRef.externalKey ?? existingEntityRef.externalId).replace(/^#/, '').split('#')[0]!;
      const issueNumber = encodeURIComponent(rawNum);
      const comment = await this.request<{ id: number; html_url: string }>(
        'POST',
        `${this.repoBasePath}/issues/${issueNumber}/comments`,
        {
          body: buildGitHubIssueBody(event, fallbackFields)
        }
      );

      // Best-effort state transition after comment creation so comment ref is never lost on PATCH error
      try {
        if (event.type === 'issue.resolved' || event.type === 'directive.superseded') {
          await this.request('PATCH', `${this.repoBasePath}/issues/${issueNumber}`, { state: 'closed' });
        } else if (event.type === 'issue.reopened') {
          await this.request('PATCH', `${this.repoBasePath}/issues/${issueNumber}`, { state: 'open' });
        }
      } catch {
        // Comment already persisted; preserve ref
      }

      const ref: RemoteRecordRef = {
        backend: 'github',
        externalId: String(comment.id),
        externalKey: `${rawNum}#comment-${comment.id}`,
        entityType: 'issue_comment',
        url: comment.html_url,
        syncedAt: new Date().toISOString(),
        syncedHash: event.hash,
        fallbackFields
      };

      return { synced: true, ref, fallbackFields };
    }

    const milestoneName =
      typeof event.payload.milestone === 'string'
        ? event.payload.milestone
        : event.type.startsWith('crew.')
          ? 'Number One Bridge Crew'
          : event.type.startsWith('lesson.')
            ? 'Institutional Memory'
            : undefined;
    const milestoneNumber = milestoneName ? await this.ensureMilestone(milestoneName) : undefined;

    const desiredLabels = labelsForGitHubEvent(event).filter((l) => this.availableLabels.has(l));
    const title = `[N1 #${event.seq}] ${event.summary}`.slice(0, 240);

    const payload: Record<string, unknown> = {
      title,
      body: buildGitHubIssueBody(event, fallbackFields)
    };
    if (desiredLabels.length > 0) payload.labels = desiredLabels;
    if (milestoneNumber !== undefined) payload.milestone = milestoneNumber;

    const created = await this.request<{
      id: number;
      node_id?: string;
      number: number;
      html_url: string;
    }>('POST', `${this.repoBasePath}/issues`, payload);

    if (created.node_id && this.config.projectNumber) {
      await this.attachToProjectV2(created.node_id);
    }

    const ref: RemoteRecordRef = {
      backend: 'github',
      externalId: String(created.id),
      externalKey: String(created.number),
      entityType: 'issue',
      url: created.html_url,
      syncedAt: new Date().toISOString(),
      syncedHash: event.hash,
      fallbackFields
    };

    return {
      synced: true,
      ref,
      entityKey: entityKey ?? `event:${event.id}`,
      fallbackFields
    };
  }

  public async pullExternalEvents(sinceTimestamp?: string, maxPages = 10): Promise<PulledExternalEvent[]> {
    const sinceParam = sinceTimestamp ? `&since=${encodeURIComponent(sinceTimestamp)}` : '';
    const direction = sinceTimestamp ? 'asc' : 'desc';
    const pulled: PulledExternalEvent[] = [];

    for (let page = 1; page <= maxPages; page++) {
      const issues = await this.request<
        Array<{
          id: number;
          number: number;
          title: string;
          body: string | null;
          state: string;
          created_at: string;
          updated_at: string;
          user?: { login: string };
          labels?: Array<{ name: string }>;
          pull_request?: unknown;
        }>
      >(
        'GET',
        `${this.repoBasePath}/issues?state=all&sort=updated&direction=${direction}&per_page=100&page=${page}${sinceParam}`
      );

      for (const issue of issues) {
        if (issue.pull_request) continue;
        const body = issue.body ?? '';
        const meta = parseGitHubEmbeddedMeta(body);

        pulled.push({
          externalId: String(issue.id),
          externalKey: String(issue.number),
          backend: 'github',
          type: issue.state === 'closed' ? 'issue.resolved' : 'issue.opened',
          summary: issue.title,
          actorName: issue.user?.login ?? 'github-user',
          timestamp: issue.updated_at || issue.created_at,
          tags: (issue.labels ?? []).map((l) => l.name),
          payload: {
            issueId: `gh-${issue.number}`,
            githubNumber: issue.number,
            title: issue.title,
            description: body,
            state: issue.state
          },
          embeddedEventId: meta?.eventId
        });
      }

      if (issues.length < 100) break;
    }

    return pulled;
  }

  public async verifyRemoteRef(
    event: StreamEvent,
    ref: RemoteRecordRef
  ): Promise<{ ok: boolean; reason?: string }> {
    try {
      const rawKey = (ref.externalKey ?? ref.externalId).replace(/^#/, '').split('#')[0]!;
      if (ref.entityType === 'issue') {
        const issue = await this.request<{ id: number; body: string | null }>(
          'GET',
          `${this.repoBasePath}/issues/${encodeURIComponent(rawKey)}`
        );
        const meta = parseGitHubEmbeddedMeta(issue.body ?? '');
        if (!meta || meta.hash !== event.hash) {
          return {
            ok: false,
            reason: `GitHub issue #${rawKey} integrity hash mismatch (expected ${event.hash})`
          };
        }
        return { ok: true };
      }
      if (ref.entityType === 'issue_comment') {
        const comment = await this.request<{ id: number; body: string | null }>(
          'GET',
          `${this.repoBasePath}/issues/comments/${encodeURIComponent(ref.externalId)}`
        );
        const meta = parseGitHubEmbeddedMeta(comment.body ?? '');
        if (!meta || meta.hash !== event.hash) {
          return {
            ok: false,
            reason: `GitHub comment ${ref.externalId} integrity hash mismatch (expected ${event.hash})`
          };
        }
        return { ok: true };
      }
      if (ref.entityType === 'external_issue') {
        await this.request<{ id: number }>('GET', `${this.repoBasePath}/issues/${encodeURIComponent(rawKey)}`);
        return { ok: true };
      }
      return { ok: true };
    } catch (err) {
      return { ok: false, reason: err instanceof Error ? err.message : String(err) };
    }
  }
}

import { RemoteRecordRef, StreamEvent } from '../core/types.js';
import {
  readResponseTextBounded,
  resilientFetch,
  resolveScopedEnvVar
} from '../utils/http.js';
import { redactSecrets } from '../utils/redactor.js';
import {
  PersistenceAdapter,
  PulledExternalEvent,
  PushEventContext,
  PushEventOutcome
} from './types.js';

export interface JiraAdapterConfig {
  enabled: boolean;
  baseUrl: string;
  projectKey: string;
  boardId?: number;
  email?: string;
  apiToken?: string;
  emailEnvVar?: string;
  apiTokenEnvVar?: string;
  allowPrivateHosts?: boolean;
}

export const JIRA_OFFICER_COMPONENTS: Record<string, string> = {
  engineering: 'Engineering Officer',
  security: 'Security Officer',
  bridge: 'Bridge Officer',
  numberone: 'Number One SoR'
};

const SAFE_JIRA_PROJECT_KEY_RX = /^[A-Z][A-Z0-9_]{0,31}$/i;
const SAFE_JIRA_ISSUE_KEY_RX = /^[A-Z][A-Z0-9_]{0,31}-\d+$/i;

export function toAdfDocument(text: string): Record<string, unknown> {
  const paragraphs = text
    .split(/\n{2,}/)
    .map((block) => block.trim())
    .filter((block) => block.length > 0)
    .map((block) => ({
      type: 'paragraph',
      content: [{ type: 'text', text: block.slice(0, 10_000) }]
    }));
  return {
    type: 'doc',
    version: 1,
    content:
      paragraphs.length > 0
        ? paragraphs
        : [{ type: 'paragraph', content: [{ type: 'text', text: ' ' }] }]
  };
}

export function mapJiraIssueType(
  event: StreamEvent,
  availableTypes?: Set<string>
): string {
  const kind = event.payload.kind;
  let preferred = 'Task';
  if (kind === 'epic') preferred = 'Epic';
  else if (kind === 'story') preferred = 'Story';
  else if (
    kind === 'bug' ||
    kind === 'crash' ||
    event.type === 'exec.crashed' ||
    event.type === 'exec.failed'
  ) {
    preferred = 'Bug';
  }

  if (!availableTypes || availableTypes.size === 0 || availableTypes.has(preferred)) {
    return preferred;
  }
  if (availableTypes.has('Task')) return 'Task';
  return Array.from(availableTypes)[0]!;
}

export function mapJiraPriority(
  event: StreamEvent,
  availablePriorities?: Set<string>
): string | null {
  const sev = event.payload.priority ?? event.payload.severity;
  let preferred = 'Medium';
  if (sev === 'critical' || sev === 'blocking') preferred = 'Highest';
  else if (sev === 'high' || sev === 'mandatory') preferred = 'High';
  else if (sev === 'low' || sev === 'advisory') preferred = 'Low';

  if (!availablePriorities || availablePriorities.size === 0) return null;
  if (availablePriorities.has(preferred)) return preferred;
  if (preferred === 'Highest' && availablePriorities.has('High')) return 'High';
  if (availablePriorities.has('Medium')) return 'Medium';
  return null;
}

export function buildJiraCreateFields(options: {
  projectKey: string;
  event: StreamEvent;
  narrative: string;
  availableIssueTypes?: Set<string>;
  availableComponents?: Set<string>;
  availablePriorities?: Set<string>;
}): Record<string, unknown> {
  const { projectKey, event, narrative } = options;
  const officer = String(
    event.payload.ownerOfficer ?? event.payload.officer ?? event.payload.issuedBy ?? 'numberone'
  );
  const componentName = JIRA_OFFICER_COMPONENTS[officer] ?? JIRA_OFFICER_COMPONENTS.numberone!;
  const labels = Array.from(
    new Set([
      'numberone',
      `n1-${event.type.replace(/\./g, '-')}`,
      ...event.tags.map((t) => t.replace(/[^a-zA-Z0-9_-]/g, '-'))
    ])
  );

  const fields: Record<string, unknown> = {
    project: { key: projectKey },
    issuetype: { name: mapJiraIssueType(event, options.availableIssueTypes) },
    summary: `[N1 #${event.seq}] ${event.summary}`.slice(0, 240),
    description: toAdfDocument(narrative),
    labels
  };

  if (options.availableComponents?.has(componentName)) {
    fields.components = [{ name: componentName }];
  }

  const priority = mapJiraPriority(event, options.availablePriorities);
  if (priority) {
    fields.priority = { name: priority };
  }

  return fields;
}

export function buildJiraSearchPayload(
  projectKey: string,
  sinceTimestamp?: string,
  nextPageToken?: string
): Record<string, unknown> {
  if (!SAFE_JIRA_PROJECT_KEY_RX.test(projectKey)) {
    throw new Error(`Invalid Jira projectKey for JQL query: "${projectKey}"`);
  }
  const jqlParts = [`project = "${projectKey}"`];
  if (sinceTimestamp) {
    const parsedMs = Date.parse(sinceTimestamp);
    if (!Number.isFinite(parsedMs)) {
      throw new Error(`Invalid ISO-8601 sinceTimestamp for Jira JQL query: "${sinceTimestamp}"`);
    }
    const isoUtc = new Date(parsedMs).toISOString();
    const formatted = isoUtc.slice(0, 16).replace('T', ' ');
    jqlParts.push(`updated >= "${formatted}"`);
  }
  // When no cursor is provided, order DESC so large (>1000 issue) projects never starve new issues
  const order = sinceTimestamp ? 'ASC' : 'DESC';
  const payload: Record<string, unknown> = {
    jql: `${jqlParts.join(' AND ')} ORDER BY updated ${order}`,
    maxResults: 100,
    fields: ['summary', 'status', 'labels', 'updated', 'created', 'reporter'],
    properties: ['numberone.event']
  };
  if (nextPageToken) {
    payload.nextPageToken = nextPageToken;
  }
  return payload;
}

/**
 * Jira Scrum Persistence Adapter (REST API v3 + Agile API 1.0).
 */
export class JiraPersistenceAdapter implements PersistenceAdapter {
  public readonly backend = 'jira' as const;
  public readonly name: string;
  private readonly config: JiraAdapterConfig;
  private readonly baseUrl: string;
  private taxonomyReady = false;
  private availableComponents = new Set<string>();
  private availableIssueTypes = new Set<string>();
  private availablePriorities = new Set<string>();

  constructor(config: JiraAdapterConfig) {
    this.config = config;
    this.baseUrl = config.baseUrl.replace(/\/$/, '');
    if (config.enabled && !SAFE_JIRA_PROJECT_KEY_RX.test(config.projectKey)) {
      throw new Error(`Invalid Jira projectKey: "${config.projectKey}"`);
    }
    this.name = `jira:${config.projectKey}`;
  }

  public isConfigured(): boolean {
    const creds = this.resolveAuthHeader();
    return Boolean(this.config.enabled && this.baseUrl && this.config.projectKey && creds);
  }

  private resolveAuthHeader(): string | null {
    const email =
      this.config.email ??
      resolveScopedEnvVar(this.config.emailEnvVar, ['JIRA_'], ['JIRA_EMAIL']);
    const token =
      this.config.apiToken ??
      resolveScopedEnvVar(this.config.apiTokenEnvVar, ['JIRA_'], ['JIRA_API_TOKEN']);
    if (!email || !token) return null;
    return `Basic ${Buffer.from(`${email}:${token}`).toString('base64')}`;
  }

  private async request<T>(method: string, apiPath: string, body?: unknown): Promise<T> {
    const auth = this.resolveAuthHeader();
    if (!auth) throw new Error(`Jira credentials unavailable for ${this.name}`);
    const res = await resilientFetch(`${this.baseUrl}${apiPath}`, {
      method,
      allowPrivateHosts: this.config.allowPrivateHosts,
      headers: {
        Authorization: auth,
        Accept: 'application/json',
        'Content-Type': 'application/json'
      },
      body: body !== undefined ? JSON.stringify(body) : undefined
    });
    if (!res.ok) {
      const txt = await readResponseTextBounded(res, 100_000).catch(() => '');
      throw new Error(`Jira API ${method} ${apiPath} failed (${res.status}): ${redactSecrets(txt).slice(0, 300)}`);
    }
    if (res.status === 204) return undefined as T;
    const text = await readResponseTextBounded(res, 5_000_000);
    if (!text) return undefined as T;
    return JSON.parse(text) as T;
  }

  public async ensureTaxonomy(): Promise<void> {
    if (this.taxonomyReady) return;
    let projectDiscovered = false;

    try {
      const proj = await this.request<{
        issueTypes?: Array<{ name: string; subtask?: boolean }>;
      }>('GET', `/rest/api/3/project/${encodeURIComponent(this.config.projectKey)}`);
      projectDiscovered = true;
      for (const it of proj.issueTypes ?? []) {
        if (!it.subtask && it.name) this.availableIssueTypes.add(it.name);
      }
    } catch {
      return;
    }

    try {
      const priorities = await this.request<Array<{ name: string }>>('GET', '/rest/api/3/priority');
      for (const p of priorities ?? []) {
        if (p.name) this.availablePriorities.add(p.name);
      }
    } catch {
      // Optional if restricted
    }

    try {
      const components = await this.request<Array<{ name: string }>>(
        'GET',
        `/rest/api/3/project/${encodeURIComponent(this.config.projectKey)}/components`
      );
      for (const c of components) {
        this.availableComponents.add(c.name);
      }
      for (const compName of Object.values(JIRA_OFFICER_COMPONENTS)) {
        if (!this.availableComponents.has(compName)) {
          const created = await this.request<{ name: string }>('POST', '/rest/api/3/component', {
            name: compName,
            project: this.config.projectKey,
            description: `Number One managed component: ${compName}`
          }).catch(() => null);
          if (created?.name) {
            this.availableComponents.add(created.name);
          }
        }
      }
    } catch {
      // Non-admin user: omit component refs
    }

    if (projectDiscovered) this.taxonomyReady = true;
  }

  private async getActiveSprintId(): Promise<number | null> {
    if (!this.config.boardId) return null;
    try {
      const res = await this.request<{ values: Array<{ id: number; state: string }> }>(
        'GET',
        `/rest/agile/1.0/board/${encodeURIComponent(String(this.config.boardId))}/sprint?state=active`
      );
      return res.values[0]?.id ?? null;
    } catch {
      return null;
    }
  }

  private async transitionIssue(issueKey: string, targetNameKeywords: string[]): Promise<void> {
    try {
      const res = await this.request<{
        transitions: Array<{ id: string; name: string }>;
      }>('GET', `/rest/api/3/issue/${encodeURIComponent(issueKey)}/transitions`);
      const match = res.transitions.find((t) =>
        targetNameKeywords.some((kw) => t.name.toLowerCase().includes(kw.toLowerCase()))
      );
      if (match) {
        await this.request('POST', `/rest/api/3/issue/${encodeURIComponent(issueKey)}/transitions`, {
          transition: { id: match.id }
        });
      }
    } catch {
      // Best-effort workflow transition
    }
  }

  private resolveParentEntityKey(event: StreamEvent): string | null {
    const p = event.payload;
    if (typeof p.issueId === 'string') return `issue:${p.issueId}`;
    if (typeof p.partySessionId === 'string') return `party:${p.partySessionId}`;
    if (typeof p.lessonId === 'string') return `lesson:${p.lessonId}`;
    if (typeof p.directiveId === 'string') return `directive:${p.directiveId}`;
    if (event.correlationId) return `corr:${event.correlationId}`;
    return null;
  }

  private buildNarrative(event: StreamEvent, fallbackFields: string[]): string {
    const lines = [
      `Number One Event #${event.seq} [${event.type}]`,
      `Event ID: ${event.id}`,
      `Actor: ${event.actor.kind}:${event.actor.id} | Harness: ${event.harness} | Session: ${event.sessionId}`,
      `Integrity Hash: ${event.hash}`,
      '',
      `Summary: ${event.summary}`,
      ''
    ];
    if (event.affectedPaths.length > 0) {
      lines.push(`Affected Paths: ${event.affectedPaths.join(', ')}`, '');
    }
    lines.push(`Payload: ${JSON.stringify(event.payload, null, 2).slice(0, 4000)}`, '');
    if (event.blobs.length > 0 || fallbackFields.length > 0) {
      lines.push(
        `Fallback Store Pointers (.numberone): ${event.blobs.map((b) => `${b.key}=${b.uri}`).join(', ') || 'none'}`,
        `Fallback Fields: ${fallbackFields.join(', ') || 'none'}`
      );
    }
    return redactSecrets(lines.join('\n'));
  }

  public async pushEvent(event: StreamEvent, context: PushEventContext): Promise<PushEventOutcome> {
    await this.ensureTaxonomy();

    if (
      event.type === 'workspace.snapshot' ||
      event.type === 'fs.created' ||
      event.type === 'fs.modified' ||
      event.type === 'fs.deleted' ||
      event.type === 'fs.renamed' ||
      event.type === 'exec.started' ||
      event.type === 'sync.pushed' ||
      event.type === 'sync.pulled' ||
      event.type === 'sync.reconciled'
    ) {
      return {
        synced: false,
        fallbackFields: ['fullEvent', 'rawDiffs', 'blobs'],
        skippedReason: `Routed to .numberone fallback ledger (high-frequency local event ${event.type})`
      };
    }

    const fallbackFields: string[] = [];
    if (event.blobs.length > 0) fallbackFields.push('blobs');

    const entityKey = this.resolveParentEntityKey(event);
    const existingEntityRef = entityKey ? context.ledger.entities[entityKey]?.[this.backend] : undefined;

    if (
      existingEntityRef &&
      existingEntityRef.externalKey &&
      (event.type === 'issue.updated' ||
        event.type === 'issue.resolved' ||
        event.type === 'issue.reopened' ||
        event.type === 'crew.opinion' ||
        event.type === 'crew.challenge' ||
        event.type === 'crew.consensus' ||
        event.type === 'crew.veto' ||
        event.type === 'lesson.verified' ||
        event.type === 'lesson.applied' ||
        event.type === 'lesson.superseded' ||
        event.type === 'directive.superseded' ||
        event.type === 'chat.thinking')
    ) {
      const issueKey = existingEntityRef.externalKey.split('#')[0]!;
      const comment = await this.request<{ id: string }>(
        'POST',
        `/rest/api/3/issue/${encodeURIComponent(issueKey)}/comment`,
        {
          body: toAdfDocument(this.buildNarrative(event, fallbackFields))
        }
      );

      if (
        event.type === 'issue.resolved' ||
        event.type === 'directive.superseded' ||
        event.type === 'lesson.superseded'
      ) {
        await this.transitionIssue(issueKey, ['done', 'resolve', 'close']);
      } else if (event.type === 'issue.reopened') {
        await this.transitionIssue(issueKey, ['reopen', 'to do', 'open']);
      } else if (event.type === 'issue.updated' && event.payload.status === 'in_progress') {
        await this.transitionIssue(issueKey, ['in progress', 'start']);
      }

      const ref: RemoteRecordRef = {
        backend: 'jira',
        externalId: comment.id,
        externalKey: `${issueKey}#comment-${comment.id}`,
        entityType: 'comment',
        url: `${this.baseUrl}/browse/${issueKey}`,
        syncedAt: new Date().toISOString(),
        syncedHash: event.hash,
        fallbackFields
      };

      return { synced: true, ref, fallbackFields };
    }

    const fields = buildJiraCreateFields({
      projectKey: this.config.projectKey,
      event,
      narrative: this.buildNarrative(event, fallbackFields),
      availableIssueTypes: this.availableIssueTypes,
      availableComponents: this.availableComponents,
      availablePriorities: this.availablePriorities
    });

    const created = await this.request<{ id: string; key: string }>('POST', '/rest/api/3/issue', {
      fields
    });

    // Best-effort secondary metadata attachments so created issue ref is never lost on secondary failure
    await this.request(
      'PUT',
      `/rest/api/3/issue/${encodeURIComponent(created.key)}/properties/numberone.event`,
      {
        schemaVersion: 1,
        eventId: event.id,
        seq: event.seq,
        type: event.type,
        hash: event.hash,
        prevHash: event.prevHash,
        harness: event.harness,
        sessionId: event.sessionId,
        fallbackBlobs: event.blobs,
        fallbackFields
      }
    ).catch(() => {});

    const activeSprintId = await this.getActiveSprintId();
    if (activeSprintId) {
      await this.request('POST', `/rest/agile/1.0/sprint/${activeSprintId}/issue`, {
        issues: [created.key]
      }).catch(() => {});
    }

    if (event.causationId) {
      const parentRef = context.ledger.events[event.causationId]?.remotes.jira;
      if (parentRef?.externalKey && !parentRef.externalKey.includes('#comment-')) {
        await this.request('POST', '/rest/api/3/issueLink', {
          type: { name: event.type === 'lesson.captured' ? 'Relates' : 'Causes' },
          inwardIssue: { key: parentRef.externalKey },
          outwardIssue: { key: created.key }
        }).catch(() => {});
      }
    }

    const ref: RemoteRecordRef = {
      backend: 'jira',
      externalId: created.id,
      externalKey: created.key,
      entityType: 'issue',
      url: `${this.baseUrl}/browse/${created.key}`,
      syncedAt: new Date().toISOString(),
      syncedHash: event.hash,
      fallbackFields
    };

    return {
      synced: true,
      ref,
      entityKey: entityKey ?? `event:${event.id}`,
      fallbackFields
    };
  }

  public async pullExternalEvents(sinceTimestamp?: string, maxPages = 10): Promise<PulledExternalEvent[]> {
    const pulled: PulledExternalEvent[] = [];
    let nextPageToken: string | undefined;

    for (let page = 1; page <= maxPages; page++) {
      const searchPayload = buildJiraSearchPayload(
        this.config.projectKey,
        sinceTimestamp,
        nextPageToken
      );

      const res = await this.request<{
        issues: Array<{
          id: string;
          key: string;
          properties?: Record<string, { eventId?: string }>;
          fields: {
            summary: string;
            status?: { name: string };
            labels?: string[];
            updated?: string;
            created?: string;
            reporter?: { displayName?: string };
          };
        }>;
        nextPageToken?: string;
        isLast?: boolean;
      }>('POST', '/rest/api/3/search/jql', searchPayload);

      for (const issue of res.issues ?? []) {
        // Use inline property from search/jql response to avoid N+1 HTTP storms
        let embeddedEventId: string | undefined = issue.properties?.['numberone.event']?.eventId;
        if (!embeddedEventId && (issue.fields.labels ?? []).includes('numberone')) {
          try {
            const prop = await this.request<{ value?: { eventId?: string } }>(
              'GET',
              `/rest/api/3/issue/${encodeURIComponent(issue.key)}/properties/numberone.event`
            );
            embeddedEventId = prop.value?.eventId;
          } catch {
            // Externally created issue
          }
        }

        const statusName = issue.fields.status?.name?.toLowerCase() ?? 'open';
        pulled.push({
          externalId: issue.id,
          externalKey: issue.key,
          backend: 'jira',
          type:
            statusName.includes('done') || statusName.includes('closed')
              ? 'issue.resolved'
              : 'issue.opened',
          summary: issue.fields.summary,
          actorName: issue.fields.reporter?.displayName ?? 'jira-user',
          timestamp: issue.fields.updated ?? issue.fields.created ?? new Date().toISOString(),
          tags: issue.fields.labels ?? [],
          payload: {
            issueId: `jira-${issue.key}`,
            jiraKey: issue.key,
            title: issue.fields.summary,
            status: statusName
          },
          embeddedEventId
        });
      }

      if (!res.nextPageToken || res.isLast) break;
      nextPageToken = res.nextPageToken;
    }

    return pulled;
  }

  public async verifyRemoteRef(
    event: StreamEvent,
    ref: RemoteRecordRef
  ): Promise<{ ok: boolean; reason?: string }> {
    try {
      const issueKey = (ref.externalKey ?? ref.externalId).split('#')[0]!;
      if (!SAFE_JIRA_ISSUE_KEY_RX.test(issueKey)) {
        return { ok: false, reason: `Invalid Jira issue key "${issueKey}"` };
      }

      if (ref.entityType === 'issue') {
        const prop = await this.request<{ value?: { hash?: string; eventId?: string } }>(
          'GET',
          `/rest/api/3/issue/${encodeURIComponent(issueKey)}/properties/numberone.event`
        );
        if (prop.value?.hash !== event.hash) {
          return {
            ok: false,
            reason: `Jira ${issueKey} property hash mismatch (expected ${event.hash}, got ${prop.value?.hash ?? 'none'})`
          };
        }
        return { ok: true };
      }

      if (ref.entityType === 'comment') {
        const comment = await this.request<{ id: string; body?: unknown }>(
          'GET',
          `/rest/api/3/issue/${encodeURIComponent(issueKey)}/comment/${encodeURIComponent(ref.externalId)}`
        );
        const serialized = JSON.stringify(comment.body ?? '');
        if (!serialized.includes(event.hash)) {
          return {
            ok: false,
            reason: `Jira comment ${issueKey}#${ref.externalId} integrity hash mismatch`
          };
        }
        return { ok: true };
      }

      if (ref.entityType === 'external_issue') {
        await this.request<{ id: string }>('GET', `/rest/api/3/issue/${encodeURIComponent(issueKey)}?fields=summary`);
        return { ok: true };
      }

      return { ok: true };
    } catch (err) {
      return { ok: false, reason: err instanceof Error ? err.message : String(err) };
    }
  }
}

