export interface LineDiffResult {
  added: number;
  removed: number;
  unified: string;
  truncated: boolean;
}

/**
 * Computes a concise unified-style line diff between previous and next text.
 * Bounded for large files to keep stream events compact while preserving fidelity.
 */
export function computeUnifiedDiff(
  filePath: string,
  before: string,
  after: string,
  maxLines = 160
): LineDiffResult {
  const a = before === '' ? [] : before.split(/\r?\n/);
  const b = after === '' ? [] : after.split(/\r?\n/);

  // Fast trim of common prefix & suffix
  let start = 0;
  while (start < a.length && start < b.length && a[start] === b[start]) {
    start++;
  }
  let endA = a.length - 1;
  let endB = b.length - 1;
  while (endA >= start && endB >= start && a[endA] === b[endB]) {
    endA--;
    endB--;
  }

  const midA = a.slice(start, endA + 1);
  const midB = b.slice(start, endB + 1);

  const lines: string[] = [`--- a/${filePath}`, `+++ b/${filePath}`];
  let added = 0;
  let removed = 0;

  if (midA.length === 0 && midB.length === 0) {
    return { added: 0, removed: 0, unified: '', truncated: false };
  }

  const ctxStart = Math.max(0, start - 2);
  const ctxEndA = Math.min(a.length, endA + 3);
  lines.push(`@@ -${ctxStart + 1},${ctxEndA - ctxStart} +${ctxStart + 1},${ctxEndA - ctxStart - midA.length + midB.length} @@`);

  for (let i = ctxStart; i < start; i++) {
    lines.push(` ${a[i]!}`);
  }

  // Use LCS for reasonably sized changed regions, fallback to block replacement for huge edits
  if (midA.length * midB.length <= 250_000) {
    const m = midA.length;
    const n = midB.length;
    const dp: Uint32Array[] = Array.from({ length: m + 1 }, () => new Uint32Array(n + 1));
    for (let i = m - 1; i >= 0; i--) {
      const row = dp[i]!;
      const nextRow = dp[i + 1]!;
      for (let j = n - 1; j >= 0; j--) {
        if (midA[i] === midB[j]) {
          row[j] = nextRow[j + 1]! + 1;
        } else {
          row[j] = Math.max(nextRow[j]!, row[j + 1]!);
        }
      }
    }
    let i = 0;
    let j = 0;
    while (i < m && j < n) {
      if (midA[i] === midB[j]) {
        lines.push(` ${midA[i]!}`);
        i++;
        j++;
      } else if (dp[i + 1]![j]! >= dp[i]![j + 1]!) {
        lines.push(`-${midA[i]!}`);
        removed++;
        i++;
      } else {
        lines.push(`+${midB[j]!}`);
        added++;
        j++;
      }
    }
    while (i < m) {
      lines.push(`-${midA[i]!}`);
      removed++;
      i++;
    }
    while (j < n) {
      lines.push(`+${midB[j]!}`);
      added++;
      j++;
    }
  } else {
    for (const l of midA) {
      lines.push(`-${l}`);
      removed++;
    }
    for (const l of midB) {
      lines.push(`+${l}`);
      added++;
    }
  }

  for (let i = endA + 1; i < ctxEndA; i++) {
    lines.push(` ${a[i]!}`);
  }

  const truncated = lines.length > maxLines;
  const outputLines = truncated
    ? [...lines.slice(0, maxLines), `... (${lines.length - maxLines} more diff lines truncated; full content stored in fallback blob)`]
    : lines;

  return {
    added,
    removed,
    unified: outputLines.join('\n'),
    truncated
  };
}

import fs, { constants as fsConstants } from 'node:fs';
import path from 'node:path';
import { randomBytes } from 'node:crypto';

export function ensureDir(dirPath: string, mode = 0o755): void {
  fs.mkdirSync(dirPath, { recursive: true, mode });
}

function fsyncDirBestEffort(dirPath: string): void {
  let fd: number | null = null;
  try {
    fd = fs.openSync(dirPath, 'r');
    fs.fsyncSync(fd);
  } catch {
    // Some virtual/network filesystems return EINVAL/EBADF on directory fsync
  } finally {
    if (fd !== null) {
      try {
        fs.closeSync(fd);
      } catch {
        // ignore
      }
    }
  }
}

/**
 * Crash-consistent atomic file write (POSIX durability pattern):
 *   1. Ensure parent dir (0o700 when mode is owner-only 0o600)
 *   2. Open unique temp file in same directory with `wx`
 *   3. Write all bytes + `fsyncSync(fd)` to flush data to disk
 *   4. `closeSync(fd)`
 *   5. `renameSync(tmpPath, targetPath)` atomically replaces target
 *   6. `fsyncSync` parent directory to persist rename metadata
 *   7. Unlink temp file on any error so partial files never remain
 */
export function atomicWriteFileSync(
  targetPath: string,
  data: string | Buffer,
  mode = 0o644
): void {
  const dir = path.dirname(targetPath);
  ensureDir(dir, (mode & 0o077) === 0 ? 0o700 : 0o755);
  const tmpName = `.${path.basename(targetPath)}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`;
  const tmpPath = path.join(dir, tmpName);
  const buf = typeof data === 'string' ? Buffer.from(data, 'utf8') : data;

  let fd: number | null = null;
  try {
    fd = fs.openSync(tmpPath, 'wx', mode);
    let offset = 0;
    while (offset < buf.length) {
      const written = fs.writeSync(fd, buf, offset, buf.length - offset);
      if (written <= 0) {
        throw new Error(`Short write to ${tmpPath}`);
      }
      offset += written;
    }
    fs.fsyncSync(fd);
    fs.closeSync(fd);
    fd = null;
    fs.renameSync(tmpPath, targetPath);
    fsyncDirBestEffort(dir);
  } catch (err) {
    if (fd !== null) {
      try {
        fs.closeSync(fd);
      } catch {
        // ignore
      }
    }
    try {
      if (fs.existsSync(tmpPath)) fs.unlinkSync(tmpPath);
    } catch {
      // ignore
    }
    throw err;
  }
}

export function atomicWriteJsonSync(targetPath: string, value: unknown, mode = 0o644): void {
  atomicWriteFileSync(targetPath, JSON.stringify(value, null, 2) + '\n', mode);
}

/**
 * Verifies that `targetPath` (resolving symlinks if present) stays strictly inside `rootDir`.
 * Defends against symlink escape (CWE-59) and path traversal (CWE-22).
 */
export function isPathConfinedToRoot(rootDir: string, targetPath: string): boolean {
  try {
    const realRoot = fs.realpathSync(rootDir);
    const realTarget = fs.realpathSync(targetPath);
    const rel = path.relative(realRoot, realTarget);
    return rel !== '..' && !rel.startsWith(`..${path.sep}`) && !path.isAbsolute(rel);
  } catch {
    return false;
  }
}

/**
 * Verifies that a target path (which may not exist yet) has its deepest existing ancestor
 * strictly confined inside `rootDir`, with no symlink components along the path.
 */
export function isWritablePathConfinedToRoot(rootDir: string, targetPath: string): boolean {
  try {
    const realRoot = fs.realpathSync(rootDir);
    const resolved = path.resolve(targetPath);
    const rel = path.relative(realRoot, resolved);
    if (rel === '..' || rel.startsWith(`..${path.sep}`) || path.isAbsolute(rel)) {
      // Also check relative to non-realpath rootDir in case rootDir contains symlink prefix (e.g. /tmp -> /private/tmp)
      const relRaw = path.relative(path.resolve(rootDir), resolved);
      if (relRaw === '..' || relRaw.startsWith(`..${path.sep}`) || path.isAbsolute(relRaw)) {
        return false;
      }
    }

    // Walk every existing segment from rootDir down to targetPath and reject symlinks
    let current = path.resolve(rootDir);
    const relParts = path.relative(current, resolved).split(path.sep).filter(Boolean);
    for (const part of relParts) {
      if (part === '..') return false;
      current = path.join(current, part);
      if (fs.existsSync(current)) {
        const st = fs.lstatSync(current);
        if (st.isSymbolicLink()) return false;
      } else {
        break;
      }
    }
    return true;
  } catch {
    return false;
  }
}

/**
 * FD-based TOCTOU-safe regular file reader:
 *  - Opens with `O_RDONLY | O_NONBLOCK | O_NOFOLLOW` (prevents FIFO blocking & symlink swap)
 *  - Validates `fstatSync(fd).isFile()` and `size <= maxBytes` on the open descriptor
 *  - Reads at most `maxBytes + 1` bytes in a bounded loop (guards growing files)
 */
export function readFileBufferSafe(
  filePath: string,
  maxBytes = 512_000,
  confineToRoot?: string
): Buffer | null {
  if (confineToRoot && !isPathConfinedToRoot(confineToRoot, filePath)) {
    return null;
  }
  const openFlags =
    fsConstants.O_RDONLY |
    (fsConstants.O_NONBLOCK ?? 0) |
    (fsConstants.O_NOFOLLOW ?? 0);

  let fd: number | null = null;
  try {
    fd = fs.openSync(filePath, openFlags);
    const st = fs.fstatSync(fd);
    if (!st.isFile() || st.size > maxBytes) {
      return null;
    }

    const chunks: Buffer[] = [];
    let total = 0;
    const chunkSize = Math.min(65_536, Math.max(1024, maxBytes));
    const scratch = Buffer.allocUnsafe(chunkSize);

    while (true) {
      const remainingAllowance = maxBytes - total + 1;
      const toRead = Math.min(scratch.length, remainingAllowance);
      const bytesRead = fs.readSync(fd, scratch, 0, toRead, null);
      if (bytesRead <= 0) break;
      total += bytesRead;
      if (total > maxBytes) {
        return null;
      }
      chunks.push(Buffer.from(scratch.subarray(0, bytesRead)));
    }

    return chunks.length === 1 ? chunks[0]! : Buffer.concat(chunks, total);
  } catch {
    return null;
  } finally {
    if (fd !== null) {
      try {
        fs.closeSync(fd);
      } catch {
        // ignore
      }
    }
  }
}

export function readJsonSafe<T>(filePath: string, maxBytes = 10_000_000): T | null {
  const buf = readFileBufferSafe(filePath, maxBytes);
  if (!buf) return null;
  try {
    return JSON.parse(buf.toString('utf8')) as T;
  } catch {
    return null;
  }
}

export function isBinaryBuffer(buf: Buffer): boolean {
  const len = Math.min(buf.length, 4096);
  for (let i = 0; i < len; i++) {
    if (buf[i] === 0) return true;
  }
  return false;
}

export function readTextFileSafe(
  filePath: string,
  maxBytes = 512_000,
  confineToRoot?: string
): string | null {
  const buf = readFileBufferSafe(filePath, maxBytes, confineToRoot);
  if (!buf || isBinaryBuffer(buf)) return null;
  return buf.toString('utf8');
}

/**
 * Deterministic A->Z workspace file walk (never traverses symlinks).
 * Pushes subdirectories in reverse sorted order onto LIFO stack so traversal proceeds A->Z
 * (ensuring `.github/`, `app/`, `src/` are always visited first even in large repos).
 */
export function walkWorkspaceFiles(
  rootDir: string,
  shouldIgnore: (relPath: string, isDir: boolean) => boolean,
  maxFiles = 5000
): string[] {
  const results: string[] = [];
  const stack: string[] = [''];

  while (stack.length > 0 && results.length < maxFiles) {
    const rel = stack.pop()!;
    const abs = rel ? path.join(rootDir, rel) : rootDir;
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(abs, { withFileTypes: true });
    } catch {
      continue;
    }
    entries.sort((a, b) => a.name.localeCompare(b.name));
    const subdirs: string[] = [];
    for (const entry of entries) {
      if (entry.isSymbolicLink()) continue;
      const childRel = rel ? `${rel}/${entry.name}` : entry.name;
      const isDir = entry.isDirectory();
      if (shouldIgnore(childRel, isDir)) continue;
      if (isDir) {
        subdirs.push(childRel);
      } else if (entry.isFile()) {
        results.push(childRel);
        if (results.length >= maxFiles) break;
      }
    }
    // Reverse push so LIFO pop visits subdirs in deterministic A->Z order
    for (let i = subdirs.length - 1; i >= 0; i--) {
      stack.push(subdirs[i]!);
    }
  }
  return results.sort();
}

import dns from 'node:dns/promises';
import net from 'node:net';
import { redactSecrets } from './redactor.js';

export interface ResilientFetchOptions {
  method?: string;
  headers?: Record<string, string>;
  body?: string;
  timeoutMs?: number;
  maxRetries?: number;
  baseDelayMs?: number;
  /** Permit loopback/RFC1918/link-local hosts (default false to prevent SSRF CWE-918). */
  allowPrivateHosts?: boolean;
  /** Require HTTPS (default false when allowPrivateHosts is true, true otherwise). */
  requireHttps?: boolean;
}

const RETRYABLE_STATUS = new Set([429, 502, 503, 504]);
const IDEMPOTENT_METHODS = new Set(['GET', 'HEAD', 'PUT', 'DELETE', 'OPTIONS']);

export function isPrivateOrReservedIp(ip: string): boolean {
  const clean = ip.replace(/^\[|\]$/g, '').toLowerCase();

  // IPv4-mapped IPv6 addresses (::ffff:127.0.0.1 or ::ffff:7f00:1)
  if (clean.startsWith('::ffff:')) {
    const mapped = clean.slice(7);
    if (net.isIPv4(mapped)) return isPrivateOrReservedIp(mapped);
    return true;
  }

  if (net.isIPv4(clean)) {
    const parts = clean.split('.').map((p) => Number.parseInt(p, 10));
    const a = parts[0] ?? 0;
    const b = parts[1] ?? 0;
    if (a === 0 || a === 10 || a === 127) return true;
    if (a === 169 && b === 254) return true; // AWS/GCP/Azure link-local metadata
    if (a === 172 && b >= 16 && b <= 31) return true;
    if (a === 192 && b === 168) return true;
    if (a === 100 && b >= 64 && b <= 127) return true; // CGNAT
    if (a >= 224) return true; // Multicast / reserved
    return false;
  }

  if (net.isIPv6(clean)) {
    if (clean === '::' || clean === '::1') return true;
    if (clean.startsWith('fc') || clean.startsWith('fd')) return true; // Unique local
    if (/^fe[89ab]/.test(clean)) return true; // Link-local
    if (clean.startsWith('ff')) return true; // Multicast
    return false;
  }

  return false;
}

export function validateHttpUrl(
  rawUrl: string,
  options: { allowPrivateHosts?: boolean; requireHttps?: boolean } = {}
): URL {
  let parsed: URL;
  try {
    parsed = new URL(rawUrl);
  } catch {
    throw new Error(`Invalid URL: ${redactSecrets(rawUrl)}`);
  }

  const allowPrivate = options.allowPrivateHosts ?? false;
  const requireHttps = options.requireHttps ?? !allowPrivate;

  if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
    throw new Error(`Unsupported URL protocol "${parsed.protocol}" (only http/https allowed)`);
  }
  if (requireHttps && parsed.protocol !== 'https:') {
    throw new Error(`Cleartext HTTP is disallowed for outbound endpoint "${parsed.origin}" (HTTPS required)`);
  }
  if (parsed.username || parsed.password) {
    throw new Error('Embedded URL credentials are disallowed; supply credentials via headers only.');
  }

  const host = parsed.hostname.replace(/^\[|\]$/g, '').toLowerCase();
  if (!allowPrivate) {
    if (
      host === 'localhost' ||
      host.endsWith('.localhost') ||
      host.endsWith('.local') ||
      host.endsWith('.internal') ||
      isPrivateOrReservedIp(host)
    ) {
      throw new Error(`Blocked SSRF target host "${host}" (private/loopback/metadata hosts disallowed)`);
    }
  }

  return parsed;
}

async function assertResolvedHostPublic(hostname: string): Promise<void> {
  const clean = hostname.replace(/^\[|\]$/g, '');
  if (net.isIP(clean)) {
    if (isPrivateOrReservedIp(clean)) {
      throw new Error(`Blocked SSRF IP target "${clean}"`);
    }
    return;
  }
  let addresses: Array<{ address: string }>;
  try {
    addresses = await dns.lookup(clean, { all: true });
  } catch {
    // Let fetch report DNS failure normally
    return;
  }
  for (const addr of addresses) {
    if (isPrivateOrReservedIp(addr.address)) {
      throw new Error(
        `Blocked SSRF DNS resolution for "${clean}" -> private/reserved IP "${addr.address}"`
      );
    }
  }
}

/**
 * Provider-scoped environment variable resolver (SEC-03):
 * Prevents untrusted workspace configs from reading arbitrary host env vars.
 */
export function resolveScopedEnvVar(
  configuredName: string | undefined,
  allowedPrefixes: string[],
  fallbackNames: string[]
): string | null {
  if (configuredName) {
    const validFormat = /^[A-Z][A-Z0-9_]{1,63}$/.test(configuredName);
    const allowed = allowedPrefixes.some((p) => configuredName.startsWith(p));
    if (validFormat && allowed && process.env[configuredName]) {
      return process.env[configuredName]!;
    }
  }
  for (const name of fallbackNames) {
    if (process.env[name]) return process.env[name]!;
  }
  return null;
}

function parseRetryAfterMs(headerVal: string | null): number | null {
  if (!headerVal) return null;
  const seconds = Number(headerVal);
  if (Number.isFinite(seconds) && seconds >= 0) {
    return Math.min(30_000, seconds * 1000);
  }
  const dateMs = Date.parse(headerVal);
  if (Number.isFinite(dateMs)) {
    return Math.min(30_000, Math.max(0, dateMs - Date.now()));
  }
  return null;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Reads an HTTP response body with a strict streaming byte cap to prevent OOM DoS.
 */
export async function readResponseTextBounded(
  res: Response,
  maxBytes = 5_000_000
): Promise<string> {
  if (!res.body) return '';
  const reader = res.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      if (value) {
        total += value.byteLength;
        if (total > maxBytes) {
          await reader.cancel().catch(() => {});
          throw new Error(`HTTP response exceeded maximum allowed size (${maxBytes} bytes)`);
        }
        chunks.push(value);
      }
    }
  } finally {
    reader.releaseLock();
  }

  return Buffer.concat(chunks, total).toString('utf8');
}

export async function readResponseJsonBounded<T>(
  res: Response,
  maxBytes = 5_000_000
): Promise<T> {
  const text = await readResponseTextBounded(res, maxBytes);
  return JSON.parse(text) as T;
}

/**
 * Production HTTP client wrapper enforcing:
 *  - URL scheme & SSRF private-IP/DNS validation (HTTPS required by default)
 *  - `redirect: 'error'` to prevent cross-origin auth-header leakage & redirect SSRF pivots
 *  - Non-idempotent `POST` defaults to `maxRetries = 0` (preventing duplicate remote creations)
 *  - Per-attempt timeout via AbortSignal.timeout
 *  - Exponential backoff + jitter + Retry-After honoring on 429/502/503/504
 *  - Secret-redacted error reporting
 */
export async function resilientFetch(
  rawUrl: string,
  options: ResilientFetchOptions
): Promise<Response> {
  const allowPrivate = options.allowPrivateHosts ?? false;
  const requireHttps = options.requireHttps ?? !allowPrivate;
  const url = validateHttpUrl(rawUrl, { allowPrivateHosts: allowPrivate, requireHttps });

  if (!allowPrivate) {
    await assertResolvedHostPublic(url.hostname);
  }

  const method = (options.method ?? 'GET').toUpperCase();
  const timeoutMs = options.timeoutMs ?? 15_000;
  const maxRetries = options.maxRetries ?? (IDEMPOTENT_METHODS.has(method) ? 3 : 0);
  const baseDelayMs = options.baseDelayMs ?? 300;

  let lastError: unknown;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      const res = await fetch(url.toString(), {
        method,
        headers: options.headers,
        body: options.body,
        redirect: 'error',
        signal: AbortSignal.timeout(timeoutMs)
      });

      if (!RETRYABLE_STATUS.has(res.status) || attempt === maxRetries) {
        return res;
      }

      const retryAfter = parseRetryAfterMs(res.headers.get('retry-after'));
      const backoff = retryAfter ?? Math.min(10_000, baseDelayMs * 2 ** attempt + Math.floor(Math.random() * 150));
      await res.body?.cancel().catch(() => {});
      await sleep(backoff);
    } catch (err) {
      lastError = err;
      if (attempt === maxRetries) {
        const msg = err instanceof Error ? err.message : String(err);
        throw new Error(`HTTP ${method} ${url.origin}${url.pathname} failed: ${redactSecrets(msg)}`);
      }
      const backoff = Math.min(10_000, baseDelayMs * 2 ** attempt + Math.floor(Math.random() * 150));
      await sleep(backoff);
    }
  }

  throw lastError instanceof Error ? lastError : new Error('HTTP request failed after retries');
}

import path from 'node:path';
import { readTextFileSafe } from './fs-helpers.js';
import { MAX_GLOB_LENGTH, matchGlobLinear } from './safe-regex.js';

const DEFAULT_IGNORED_SEGMENTS = new Set([
  '.git',
  '.numberone',
  'node_modules',
  '.next',
  '.nuxt',
  '.cache',
  '.turbo',
  '__pycache__',
  '.pytest_cache',
  '.venv',
  'venv',
  'dist',
  'build',
  'target',
  'coverage',
  '.idea',
  '.DS_Store'
]);

interface IgnoreRule {
  negated: boolean;
  dirOnly: boolean;
  anchored: boolean;
  pattern: string;
}

function matchesIgnoreRule(normalizedPath: string, rule: IgnoreRule): boolean {
  const candidates = rule.anchored
    ? [rule.pattern, `${rule.pattern}/**`]
    : [rule.pattern, `**/${rule.pattern}`, `${rule.pattern}/**`, `**/${rule.pattern}/**`];

  for (const glob of candidates) {
    if (glob.length <= MAX_GLOB_LENGTH && matchGlobLinear(normalizedPath, glob)) {
      return true;
    }
  }
  return false;
}

/**
 * Linear-time `.gitignore` / `.numberoneignore` matcher (zero regex backtracking).
 */
export class WorkspaceIgnore {
  private readonly rules: IgnoreRule[] = [];
  private readonly extraSegments: Set<string>;

  constructor(workspaceRoot: string, extraIgnored: string[] = []) {
    this.extraSegments = new Set([...DEFAULT_IGNORED_SEGMENTS, ...extraIgnored]);
    const gitignore = readTextFileSafe(path.join(workspaceRoot, '.gitignore'), 256_000, workspaceRoot);
    if (gitignore) {
      this.parseRules(gitignore);
    }
    const n1Ignore = readTextFileSafe(
      path.join(workspaceRoot, '.numberoneignore'),
      256_000,
      workspaceRoot
    );
    if (n1Ignore) {
      this.parseRules(n1Ignore);
    }
  }

  private parseRules(content: string): void {
    const maxRules = 500;
    for (const rawLine of content.split(/\r?\n/)) {
      if (this.rules.length >= maxRules) break;
      const line = rawLine.trim();
      if (!line || line.startsWith('#')) continue;
      let negated = false;
      let pattern = line;
      if (pattern.startsWith('!')) {
        negated = true;
        pattern = pattern.slice(1);
      }
      let dirOnly = false;
      if (pattern.endsWith('/')) {
        dirOnly = true;
        pattern = pattern.slice(0, -1);
      }
      let anchored = false;
      if (pattern.startsWith('/')) {
        anchored = true;
        pattern = pattern.slice(1);
      }
      if (!pattern || pattern.length > MAX_GLOB_LENGTH - 8) continue;
      if (pattern.includes('/')) anchored = true;

      this.rules.push({ negated, dirOnly, anchored, pattern });
    }
  }

  public shouldIgnore(relPath: string, isDir = false): boolean {
    const normalized = relPath.replace(/\\/g, '/').replace(/^\.\//, '');
    if (!normalized) return false;
    const segments = normalized.split('/');
    for (const seg of segments) {
      if (this.extraSegments.has(seg)) return true;
      if (seg.endsWith('.tmp') && seg.startsWith('.')) return true;
    }

    let ignored = false;
    for (const rule of this.rules) {
      if (rule.dirOnly && !isDir && !normalized.includes('/')) continue;
      if (matchesIgnoreRule(normalized, rule)) {
        ignored = !rule.negated;
      }
    }
    return ignored;
  }
}

import { randomBytes } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { ensureDir } from './fs-helpers.js';

const SLEEP_ARRAY = new Int32Array(new SharedArrayBuffer(4));
const CURRENT_INSTANCE_ID = randomBytes(12).toString('hex');

interface LockMetadata {
  pid: number;
  instanceId: string;
  procStartTicks: string | null;
  acquiredAt: number;
}

interface AcquiredLock {
  lockPath: string;
  dev: number;
  ino: number;
}

function sleepSyncMs(ms: number): void {
  Atomics.wait(SLEEP_ARRAY, 0, 0, ms);
}

function sleepAsyncMs(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

export function isProcessAlive(pid: number): boolean {
  if (!Number.isFinite(pid) || pid <= 0) return false;
  try {
    process.kill(pid, 0);
    return true;
  } catch (err: unknown) {
    if (err && typeof err === 'object' && (err as { code?: string }).code === 'EPERM') {
      return true;
    }
    return false;
  }
}

/**
 * Reads process start time ticks (field 22) from Linux `/proc/<pid>/stat`
 * to distinguish OS-recycled PIDs and container PID-1 restarts.
 */
export function readProcStartTicks(pid: number): string | null {
  try {
    const statText = fs.readFileSync(`/proc/${pid}/stat`, 'utf8');
    const closeParen = statText.lastIndexOf(')');
    if (closeParen === -1) return null;
    const fields = statText.slice(closeParen + 2).trim().split(/\s+/);
    // Field 3 is index 0 after ')'; field 22 (starttime) is index 19
    return fields[19] ?? null;
  } catch {
    return null;
  }
}

function isLockStale(lockPath: string, staleAfterMs: number): { stale: boolean; dev: number; ino: number } {
  let st: fs.Stats;
  try {
    st = fs.lstatSync(lockPath);
  } catch {
    return { stale: false, dev: 0, ino: 0 };
  }

  let parsed: Partial<LockMetadata> | null = null;
  try {
    const raw = fs.readFileSync(lockPath, 'utf8');
    if (raw.trim().length > 0) {
      parsed = JSON.parse(raw) as Partial<LockMetadata>;
    }
  } catch {
    parsed = null;
  }

  const mtimeAge = Date.now() - st.mtimeMs;

  // Corrupt or 0-byte lockfile: reclaim after brief 2s grace window
  if (!parsed || typeof parsed.pid !== 'number' || !Number.isFinite(parsed.pid)) {
    return { stale: mtimeAge > 2000, dev: st.dev, ino: st.ino };
  }

  // Container PID-1 restart (or same PID from prior process image): different instanceId!
  if (parsed.pid === process.pid && parsed.instanceId && parsed.instanceId !== CURRENT_INSTANCE_ID) {
    return { stale: true, dev: st.dev, ino: st.ino };
  }

  // Owner process is dead
  if (!isProcessAlive(parsed.pid)) {
    return { stale: true, dev: st.dev, ino: st.ino };
  }

  // Linux OS PID reuse: PID is alive, but /proc/<pid>/stat start ticks changed
  if (parsed.procStartTicks) {
    const currentTicks = readProcStartTicks(parsed.pid);
    if (currentTicks !== null && currentTicks !== parsed.procStartTicks) {
      return { stale: true, dev: st.dev, ino: st.ino };
    }
  }

  // Legacy lockfile without instanceId/procStartTicks: allow age-based fallback only if pid missing
  if (!parsed.instanceId && mtimeAge > staleAfterMs && !isProcessAlive(parsed.pid)) {
    return { stale: true, dev: st.dev, ino: st.ino };
  }

  // Never evict a proven-alive holder purely on wall-clock age
  return { stale: false, dev: st.dev, ino: st.ino };
}

/**
 * Coordinates stale lock reclamation using a short-lived `.reclaim` guard
 * verifying `(dev, ino)` did not change, preventing two waiters from unlinking a winner's live lock.
 */
function tryReclaimStaleLock(lockPath: string, staleAfterMs: number): boolean {
  const initial = isLockStale(lockPath, staleAfterMs);
  if (!initial.stale) return false;

  const reclaimGuard = `${lockPath}.reclaim`;
  let guardFd: number | null = null;
  try {
    guardFd = fs.openSync(reclaimGuard, 'wx', 0o600);
  } catch (err: unknown) {
    const code = err && typeof err === 'object' ? (err as { code?: string }).code : undefined;
    if (code === 'EEXIST') {
      try {
        const gst = fs.lstatSync(reclaimGuard);
        if (Date.now() - gst.mtimeMs > 5000) {
          fs.unlinkSync(reclaimGuard);
        }
      } catch {
        // ignore
      }
    }
    return false;
  }

  try {
    const current = isLockStale(lockPath, staleAfterMs);
    if (current.stale && current.dev === initial.dev && current.ino === initial.ino) {
      try {
        fs.unlinkSync(lockPath);
        return true;
      } catch {
        return false;
      }
    }
    return false;
  } finally {
    try {
      fs.closeSync(guardFd);
    } catch {
      // ignore
    }
    try {
      fs.unlinkSync(reclaimGuard);
    } catch {
      // ignore
    }
  }
}

/**
 * Atomically publishes a fully populated, fsynced lockfile using temp-file + `fs.linkSync`
 * (eliminating 0-byte lockfile deadlocks and FD leaks).
 */
function tryAcquireLockOnce(lockPath: string): AcquiredLock | null {
  const dir = path.dirname(lockPath);
  const tmpPath = path.join(
    dir,
    `.${path.basename(lockPath)}.${process.pid}.${randomBytes(4).toString('hex')}.tmp`
  );
  const meta: LockMetadata = {
    pid: process.pid,
    instanceId: CURRENT_INSTANCE_ID,
    procStartTicks: readProcStartTicks(process.pid),
    acquiredAt: Date.now()
  };
  const payload = Buffer.from(JSON.stringify(meta), 'utf8');

  let fd: number | null = null;
  try {
    fd = fs.openSync(tmpPath, 'wx', 0o600);
    let offset = 0;
    while (offset < payload.length) {
      const n = fs.writeSync(fd, payload, offset, payload.length - offset);
      if (n <= 0) throw new Error(`Short write to lock temp file ${tmpPath}`);
      offset += n;
    }
    fs.fsyncSync(fd);
    const st = fs.fstatSync(fd);
    fs.closeSync(fd);
    fd = null;

    try {
      fs.linkSync(tmpPath, lockPath);
    } catch (err: unknown) {
      const code = err && typeof err === 'object' ? (err as { code?: string }).code : undefined;
      if (code === 'EEXIST') {
        return null;
      }
      // Fallback for rare filesystems without hardlink support
      if (code === 'EPERM' || code === 'EXDEV' || code === 'ENOTSUP') {
        let fallbackFd: number | null = null;
        try {
          fallbackFd = fs.openSync(lockPath, 'wx', 0o600);
          fs.writeSync(fallbackFd, payload);
          fs.fsyncSync(fallbackFd);
          const fst = fs.fstatSync(fallbackFd);
          fs.closeSync(fallbackFd);
          fallbackFd = null;
          return { lockPath, dev: fst.dev, ino: fst.ino };
        } catch (ferr: unknown) {
          if (fallbackFd !== null) {
            try {
              fs.closeSync(fallbackFd);
            } catch {
              // ignore
            }
          }
          const fcode = ferr && typeof ferr === 'object' ? (ferr as { code?: string }).code : undefined;
          if (fcode === 'EEXIST') return null;
          throw ferr;
        }
      }
      throw err;
    }
    return { lockPath, dev: st.dev, ino: st.ino };
  } finally {
    if (fd !== null) {
      try {
        fs.closeSync(fd);
      } catch {
        // ignore
      }
    }
    try {
      if (fs.existsSync(tmpPath)) fs.unlinkSync(tmpPath);
    } catch {
      // ignore
    }
  }
}

function releaseLock(lock: AcquiredLock): void {
  try {
    const cur = fs.lstatSync(lock.lockPath);
    if (cur.dev === lock.dev && cur.ino === lock.ino) {
      fs.unlinkSync(lock.lockPath);
    }
  } catch {
    // Already removed or vanished
  }
}

/**
 * Synchronous cross-process exclusive lock with TOCTOU-free reclaim & inode-verified release.
 */
export function withFileLockSync<T>(
  lockPath: string,
  fn: () => T,
  timeoutMs = 10_000,
  staleAfterMs = 30_000
): T {
  ensureDir(path.dirname(lockPath), 0o700);
  const deadline = Date.now() + timeoutMs;
  let acquired: AcquiredLock | null = null;

  while (acquired === null) {
    acquired = tryAcquireLockOnce(lockPath);
    if (acquired !== null) break;
    if (tryReclaimStaleLock(lockPath, staleAfterMs)) continue;
    if (Date.now() >= deadline) {
      throw new Error(`Timed out waiting ${timeoutMs}ms for lock at ${lockPath}`);
    }
    sleepSyncMs(5 + Math.floor(Math.random() * 10));
  }

  try {
    return fn();
  } finally {
    releaseLock(acquired);
  }
}

/**
 * Async cross-process exclusive lock for distributed sync and daemon coordination.
 */
export async function withFileLockAsync<T>(
  lockPath: string,
  fn: () => Promise<T>,
  timeoutMs = 15_000,
  staleAfterMs = 120_000
): Promise<T> {
  ensureDir(path.dirname(lockPath), 0o700);
  const deadline = Date.now() + timeoutMs;
  let acquired: AcquiredLock | null = null;

  while (acquired === null) {
    acquired = tryAcquireLockOnce(lockPath);
    if (acquired !== null) break;
    if (tryReclaimStaleLock(lockPath, staleAfterMs)) continue;
    if (Date.now() >= deadline) {
      throw new Error(`Timed out waiting ${timeoutMs}ms for async lock at ${lockPath}`);
    }
    await sleepAsyncMs(15 + Math.floor(Math.random() * 25));
  }

  try {
    return await fn();
  } finally {
    releaseLock(acquired);
  }
}

/**
 * Deterministic secret and credential redaction engine (OWASP ASVS V7/V8 / CWE-532 / CWE-200).
 * Prevents API keys, tokens, passwords, private keys, and credentialed URIs from being
 * persisted into `.numberone/stream/` or mirrored to external GitHub/Jira/LLM endpoints.
 */

interface RedactionRule {
  name: string;
  regex: RegExp;
  replace: (match: string, ...groups: string[]) => string;
}

const FORBIDDEN_RECORD_KEYS = new Set([
  '__proto__',
  'prototype',
  'constructor',
  'toString',
  'valueOf',
  'hasOwnProperty'
]);

/**
 * Returns true if `key` is safe to use as a dynamic lookup/write key on plain objects.
 */
export function isSafeRecordKey(key: string): boolean {
  return typeof key === 'string' && key.length > 0 && !FORBIDDEN_RECORD_KEYS.has(key);
}

// Matches both complete and truncated PEM / PGP private key blocks
const PEM_BLOCK_RX = new RegExp(
  '-----BEGIN ' +
    '(?:RSA |EC |DSA |OPENSSH |PGP |ENCRYPTED )?' +
    'PRIVATE KEY(?: BLOCK)?-----[\\s\\S]*?(?:-----END ' +
    '(?:RSA |EC |DSA |OPENSSH |PGP |ENCRYPTED )?' +
    'PRIVATE KEY(?: BLOCK)?-----|$)',
  'g'
);

const REDACTION_RULES: RedactionRule[] = [
  {
    name: 'pem-private-key',
    regex: PEM_BLOCK_RX,
    replace: () => '[REDACTED:PRIVATE_KEY]'
  },
  {
    name: 'aws-access-key',
    regex: new RegExp('\\b(?:AKIA|ASIA)' + '[0-9A-Z]{16}\\b', 'g'),
    replace: () => '[REDACTED:AWS_ACCESS_KEY]'
  },
  {
    name: 'github-token',
    regex: new RegExp('\\b(?:ghp|gho|ghu|ghs|ghr|github_pat)_' + '[A-Za-z0-9_]{20,}\\b', 'g'),
    replace: () => '[REDACTED:GITHUB_TOKEN]'
  },
  {
    name: 'gitlab-token',
    regex: /\b(?:glpat|gloas|glrt)-[A-Za-z0-9_-]{20,}\b/g,
    replace: () => '[REDACTED:GITLAB_TOKEN]'
  },
  {
    name: 'npm-token',
    regex: /\bnpm_[A-Za-z0-9]{20,}\b/g,
    replace: () => '[REDACTED:NPM_TOKEN]'
  },
  {
    name: 'pypi-token',
    regex: /\bpypi-[A-Za-z0-9_-]{20,}\b/g,
    replace: () => '[REDACTED:PYPI_TOKEN]'
  },
  {
    name: 'anthropic-key',
    regex: /\bsk-ant-[A-Za-z0-9_-]{20,}\b/g,
    replace: () => '[REDACTED:ANTHROPIC_KEY]'
  },
  {
    name: 'openai-key',
    regex: /\bsk-(?:proj-)?[A-Za-z0-9_-]{20,}\b/g,
    replace: () => '[REDACTED:OPENAI_KEY]'
  },
  {
    name: 'google-api-key',
    regex: /\bAIza[0-9A-Za-z_-]{35}\b/g,
    replace: () => '[REDACTED:GOOGLE_API_KEY]'
  },
  {
    name: 'google-oauth-token',
    regex: /\bya29\.[0-9A-Za-z_-]{20,}\b/g,
    replace: () => '[REDACTED:GOOGLE_OAUTH_TOKEN]'
  },
  {
    name: 'slack-token',
    regex: /\bxox[baprs]-[0-9A-Za-z-]{10,}\b/g,
    replace: () => '[REDACTED:SLACK_TOKEN]'
  },
  {
    name: 'slack-webhook',
    regex: /https:\/\/hooks\.slack\.com\/services\/[A-Z0-9]+\/[A-Z0-9]+\/[A-Za-z0-9]+/g,
    replace: () => '[REDACTED:SLACK_WEBHOOK]'
  },
  {
    name: 'stripe-key',
    regex: /\b(?:sk|rk)_live_[0-9A-Za-z]{16,}\b/g,
    replace: () => '[REDACTED:STRIPE_KEY]'
  },
  {
    name: 'azure-sas-sig',
    regex: /([?&]sig=)([A-Za-z0-9%+/=_-]{20,})/gi,
    replace: (_m, prefix) => `${prefix}[REDACTED:AZURE_SAS]`
  },
  {
    name: 'bearer-or-basic-auth',
    regex: /\b(Authorization['"]?[ \t]*[:=][ \t]*['"]?(?:Bearer|Basic)[ \t]+)([A-Za-z0-9._~+/=-]{8,})/gi,
    replace: (_m, prefix) => `${prefix}[REDACTED:AUTH_CREDENTIAL]`
  },
  {
    name: 'url-credentials',
    regex: /\b((?:postgres|postgresql|mysql|mariadb|mongodb|mongodb\+srv|redis|rediss|amqp|amqps|https?):\/\/[^/\s:@]*:)([^/\s@]+)(@)/gi,
    replace: (_m, prefix, _secret, at) => `${prefix}[REDACTED:URI_PASSWORD]${at}`
  },
  {
    name: 'jwt',
    regex: /\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g,
    replace: () => '[REDACTED:JWT]'
  },
  {
    // Bounded prefix/suffix lengths (0..40) prevent quadratic ReDoS; supports JSON quotes & hyphenated headers
    name: 'env-or-json-secret-assignment',
    regex:
      /\b([A-Za-z0-9_-]{0,40}(?:SECRET|TOKEN|PASSWORD|PASSWD|PASSPHRASE|API[-_]?KEY|PRIVATE[-_]?KEY|ACCESS[-_]?KEY|AUTH[-_]?KEY|ACCOUNT[-_]?KEY)[A-Za-z0-9_-]{0,40}['"]?[ \t]*[:=][ \t]*['"]?)([^\s'",;}{]{8,})/gi,
    replace: (_m, prefix, val) => {
      if (
        val.startsWith('[REDACTED:') ||
        val.startsWith('$') ||
        val === 'undefined' ||
        val === 'null' ||
        val === 'REDACTED'
      ) {
        return `${prefix}${val}`;
      }
      return `${prefix}[REDACTED:SECRET_VALUE]`;
    }
  }
];

const SENSITIVE_FILENAME_RX =
  /(?:^|\/)(?:\.env(?:\.(?!example$|sample$|template$)[^/]+)?|\.envrc|id_rsa|id_ed25519|id_ecdsa|id_dsa|.*\.pem|.*\.key|.*\.p12|.*\.pfx|.*\.jks|.*\.keystore|.*\.tfvars|terraform\.tfstate(?:\.backup)?|\.npmrc|\.pypirc|\.netrc|\.pgpass|\.git-credentials|credentials\.json|service[-_]?account[^/]*\.json|\.aws\/credentials|\.kube\/config|\.docker\/config\.json)$/i;

/**
 * Returns true if the relative path is a known secret/credential file whose raw contents
 * must NEVER be captured into stream diffs, fallback blobs, or dynamic officer probes.
 */
export function isSensitiveSecretFile(relPath: string): boolean {
  const normalized = relPath.replace(/\\/g, '/').replace(/^\.\//, '');
  return SENSITIVE_FILENAME_RX.test(normalized);
}

export function redactSecrets(input: string): string {
  if (!input) return input;
  let out = input;
  for (const rule of REDACTION_RULES) {
    rule.regex.lastIndex = 0;
    out = out.replace(rule.regex, rule.replace as (...args: string[]) => string);
  }
  return out;
}

/**
 * Recursively redacts all string values in an arbitrary JSON-compatible payload.
 * Enforces maxDepth cleanly (redacting beyond maxDepth instead of returning raw data),
 * preserves Date ISO values, guards against circular refs, and strips prototype-pollution keys.
 */
export function redactObjectDeep<T>(value: T, maxDepth = 12): T {
  const seen = new WeakSet<object>();

  function walk(node: unknown, depth: number): unknown {
    if (typeof node === 'string') return redactSecrets(node);
    if (node === null || typeof node !== 'object') return node;
    if (node instanceof Date) return node.toISOString();
    if (depth >= maxDepth) return '[REDACTED:MAX_DEPTH]';
    if (seen.has(node)) return '[Circular]';
    seen.add(node);

    if (Array.isArray(node)) {
      return node.map((item) => walk(item, depth + 1));
    }

    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(node as Record<string, unknown>)) {
      if (!isSafeRecordKey(k)) continue;
      out[k] = walk(v, depth + 1);
    }
    return out;
  }

  return walk(value, 0) as T;
}

const ALLOWED_CHILD_ENV_KEYS = new Set([
  'PATH',
  'HOME',
  'USER',
  'LOGNAME',
  'SHELL',
  'LANG',
  'TZ',
  'TERM',
  'NODE_ENV',
  'TMPDIR',
  'TEMP',
  'TMP',
  'SYSTEMROOT',
  'COMSPEC',
  'PATHEXT'
]);

/**
 * Strict allowlist environment sanitizer for benchmark child processes.
 * Only forwards standard POSIX/Node runtime variables (never tokens, URLs, sockets, or DSNs).
 */
export function buildSanitizedChildEnv(baseEnv: NodeJS.ProcessEnv = process.env): NodeJS.ProcessEnv {
  const sanitized: NodeJS.ProcessEnv = {};
  for (const [k, v] of Object.entries(baseEnv)) {
    if (v === undefined) continue;
    const upper = k.toUpperCase();
    if (ALLOWED_CHILD_ENV_KEYS.has(upper) || upper.startsWith('LC_')) {
      sanitized[k] = v;
    }
  }
  return sanitized;
}

/**
 * ReDoS-resistant regex validator, safe compiler, and linear-time DP glob matcher
 * (OWASP ASVS V5.1.4 / CWE-1333).
 */

export const MAX_REGEX_LENGTH = 512;
export const MAX_REGEX_INPUT_LENGTH = 100_000;
export const MAX_GLOB_LENGTH = 256;

export interface SafeRegexValidation {
  safe: boolean;
  reason?: string;
}

/**
 * Statically inspects a regex pattern for catastrophic backtracking risks:
 *  - Exceeds MAX_REGEX_LENGTH
 *  - Numeric (\1..\9) or named (\k<name>) backreferences
 *  - Lookarounds ((?=...), (?!...), (?<=...), (?<!...))
 *  - Nested quantifiers including optional `?` inside repeated groups (e.g., `(a+)+`, `(a?a?)+`, `([a-z]{1,5})+`)
 *  - Repeated alternation groups (`(a|b)+`)
 *  - Adjacent unbounded wildcards (`.*.*`, `.+.+`, `.*.+`, `.+.*`) or consecutive overlapping token quantifiers (`\w+\w+`)
 */
export function validateRegexSafety(pattern: string): SafeRegexValidation {
  if (!pattern || typeof pattern !== 'string') {
    return { safe: false, reason: 'Regex pattern must be a non-empty string.' };
  }
  if (pattern.length > MAX_REGEX_LENGTH) {
    return { safe: false, reason: `Regex pattern exceeds max length (${MAX_REGEX_LENGTH}).` };
  }
  if (/\\[1-9]|\\k<[^>]+>/.test(pattern)) {
    return {
      safe: false,
      reason: 'Numeric or named backreferences (\\1..\\9, \\k<name>) are disallowed due to backtracking risk.'
    };
  }
  if (/\(\?[=!<]/.test(pattern)) {
    return {
      safe: false,
      reason: 'Lookahead and lookbehind assertions are disallowed in dynamic regex patterns.'
    };
  }
  if (/\.[*+]\s*\.[*+]/.test(pattern)) {
    return { safe: false, reason: 'Adjacent unbounded wildcards (.*.*, .+.*, etc.) are disallowed.' };
  }
  if (/(\\[wdsWDS])[*+]\s*\1[*+]/.test(pattern)) {
    return {
      safe: false,
      reason: 'Adjacent identical unbounded character-class quantifiers are disallowed (polynomial ReDoS risk).'
    };
  }

  interface GroupFrame {
    hasQuantifier: boolean;
    hasAlternation: boolean;
  }
  const stack: GroupFrame[] = [];
  let inCharClass = false;
  let escaped = false;

  for (let i = 0; i < pattern.length; i++) {
    const ch = pattern[i]!;
    if (escaped) {
      escaped = false;
      continue;
    }
    if (ch === '\\') {
      escaped = true;
      continue;
    }
    if (inCharClass) {
      if (ch === ']') inCharClass = false;
      continue;
    }
    if (ch === '[') {
      inCharClass = true;
      continue;
    }
    if (ch === '(') {
      stack.push({ hasQuantifier: false, hasAlternation: false });
      continue;
    }
    if (ch === '|') {
      if (stack.length > 0) {
        stack[stack.length - 1]!.hasAlternation = true;
      }
      continue;
    }
    if (ch === ')') {
      const frame = stack.pop();
      if (!frame) continue;
      const next = pattern[i + 1];
      const isRepeatedGroup =
        next === '+' || next === '*' || (next === '{' && /^\{\d+(?:,\d*)?\}/.test(pattern.slice(i + 1)));
      if (isRepeatedGroup && frame.hasQuantifier) {
        return {
          safe: false,
          reason: 'Nested quantifiers inside repeated group detected (ReDoS risk).'
        };
      }
      if (isRepeatedGroup && frame.hasAlternation) {
        return {
          safe: false,
          reason: 'Repeated alternation group detected (potential polynomial/exponential ReDoS risk).'
        };
      }
      if (stack.length > 0 && (frame.hasQuantifier || isRepeatedGroup || next === '?')) {
        stack[stack.length - 1]!.hasQuantifier = true;
      }
      continue;
    }

    if (ch === '+' || ch === '*' || ch === '?' || ch === '{') {
      const prev = i > 0 ? pattern[i - 1] : '';
      // Ignore `(?:` non-capturing group prefix and lazy `?` immediately following `+`/`*`/`}`/`?`
      if (ch === '?' && (prev === '(' || prev === '+' || prev === '*' || prev === '}' || prev === '?')) {
        continue;
      }
      const isQuantifier =
        ch === '+' ||
        ch === '*' ||
        ch === '?' ||
        /^\{\d+(?:,\d*)?\}/.test(pattern.slice(i));
      if (isQuantifier && stack.length > 0) {
        stack[stack.length - 1]!.hasQuantifier = true;
      }
    }
  }

  try {
    new RegExp(pattern, 'i');
  } catch (err) {
    return {
      safe: false,
      reason: `Invalid regex syntax: ${err instanceof Error ? err.message : String(err)}`
    };
  }

  return { safe: true };
}

export function compileSafeRegex(pattern: string, flags = 'i'): RegExp | null {
  const check = validateRegexSafety(pattern);
  if (!check.safe) return null;
  return new RegExp(pattern, flags);
}

export function testSafeRegex(pattern: string, input: string, flags = 'i'): boolean {
  const rx = compileSafeRegex(pattern, flags);
  if (!rx) return false;
  const bounded =
    input.length > MAX_REGEX_INPUT_LENGTH ? input.slice(0, MAX_REGEX_INPUT_LENGTH) : input;
  return rx.test(bounded);
}

/**
 * Linear-time O(N * M) dynamic-programming path glob matcher (zero regex backtracking).
 * Supports:
 *  - `**\/` (zero or more directory segments)
 *  - `**` (any characters including `/`)
 *  - `*` (any characters except `/`)
 *  - `?` (single character except `/`)
 */
export function matchGlobLinear(inputPath: string, rawGlob: string, caseInsensitive = false): boolean {
  if (!rawGlob || rawGlob.length > MAX_GLOB_LENGTH) return false;
  const normPath = inputPath.replace(/\\/g, '/').replace(/^\.\//, '');
  const normGlob = rawGlob.replace(/\\/g, '/').replace(/^\.\//, '');
  const text = caseInsensitive ? normPath.toLowerCase() : normPath;
  const pat = caseInsensitive ? normGlob.toLowerCase() : normGlob;

  // Tokenize glob into linear atoms: 'GLOBSTAR_SLASH' | 'GLOBSTAR' | 'STAR' | 'QMARK' | literal char
  type Atom =
    | { kind: 'globstar_slash' }
    | { kind: 'globstar' }
    | { kind: 'star' }
    | { kind: 'qmark' }
    | { kind: 'lit'; ch: string };

  const atoms: Atom[] = [];
  for (let i = 0; i < pat.length; i++) {
    const ch = pat[i]!;
    if (ch === '*' && pat[i + 1] === '*') {
      // Collapse consecutive **
      while (pat[i + 1] === '*') i++;
      if (pat[i + 1] === '/') {
        if (atoms[atoms.length - 1]?.kind !== 'globstar_slash') {
          atoms.push({ kind: 'globstar_slash' });
        }
        i++;
      } else if (atoms[atoms.length - 1]?.kind !== 'globstar') {
        atoms.push({ kind: 'globstar' });
      }
    } else if (ch === '*') {
      if (atoms[atoms.length - 1]?.kind !== 'star' && atoms[atoms.length - 1]?.kind !== 'globstar') {
        atoms.push({ kind: 'star' });
      }
    } else if (ch === '?') {
      atoms.push({ kind: 'qmark' });
    } else {
      atoms.push({ kind: 'lit', ch });
    }
  }

  const m = atoms.length;
  const n = text.length;
  // dp[j] = whether atoms[0..i-1] matches text[0..j-1]
  let prev = new Uint8Array(n + 1);
  prev[0] = 1;

  for (let i = 0; i < m; i++) {
    const atom = atoms[i]!;
    const curr = new Uint8Array(n + 1);

    if (atom.kind === 'globstar') {
      let seen = 0;
      for (let j = 0; j <= n; j++) {
        if (prev[j]) seen = 1;
        curr[j] = seen;
      }
    } else if (atom.kind === 'globstar_slash') {
      // Matches empty string OR any prefix ending at a '/'
      let anyReachable = 0;
      for (let j = 0; j <= n; j++) {
        if (prev[j]) {
          curr[j] = 1;
          anyReachable = 1;
        }
        if (j > 0 && text[j - 1] === '/' && anyReachable) {
          curr[j] = 1;
        }
      }
    } else if (atom.kind === 'star') {
      for (let j = 0; j <= n; j++) {
        if (prev[j]) {
          curr[j] = 1;
        } else if (j > 0 && curr[j - 1] && text[j - 1] !== '/') {
          curr[j] = 1;
        }
      }
    } else if (atom.kind === 'qmark') {
      for (let j = 1; j <= n; j++) {
        if (prev[j - 1] && text[j - 1] !== '/') {
          curr[j] = 1;
        }
      }
    } else {
      for (let j = 1; j <= n; j++) {
        if (prev[j - 1] && text[j - 1] === atom.ch) {
          curr[j] = 1;
        }
      }
    }
    prev = curr;
  }

  return prev[n] === 1;
}

import { spawn } from 'node:child_process';
import { StringDecoder } from 'node:string_decoder';
import { LessonEngine } from '../core/lesson-engine.js';
import { StreamStore } from '../core/stream-store.js';
import { StreamEvent } from '../core/types.js';
import { redactSecrets } from '../utils/redactor.js';
import { shellSingleQuote } from './git-hooks.js';

export interface CommandRunOptions {
  /** Human-readable command string (and shell command when `argv` is not provided). */
  command: string;
  /**
   * Optional direct executable + argument vector (spawns with `shell: false`,
   * avoiding double-shell quoting bugs and shell metacharacter injection).
   */
  argv?: string[];
  cwd?: string;
  harness?: string;
  sessionId?: string;
  actorId?: string;
  tags?: string[];
  silent?: boolean;
  env?: NodeJS.ProcessEnv;
  /** Maximum bytes buffered in memory per stream (stdout/stderr). Default 2 MB. */
  maxCaptureBytes?: number;
  /** Optional command timeout in milliseconds (sends SIGTERM then SIGKILL). */
  timeoutMs?: number;
}

export interface CommandRunResult {
  exitCode: number | null;
  signal: string | null;
  timedOut: boolean;
  durationMs: number;
  stdout: string;
  stderr: string;
  stdoutTruncatedBytes: number;
  stderrTruncatedBytes: number;
  startEvent: StreamEvent;
  endEvent: StreamEvent;
  autoCapturedLesson?: StreamEvent;
}

/**
 * O(1)-amortized byte-bounded head+tail accumulator using Buffers + UTF-8 StringDecoder
 * so noisy commands emitting hundreds of megabytes never trigger OOM or O(N^2) byte counts.
 */
class BoundedOutputBuffer {
  private readonly maxBytes: number;
  private readonly headLimit: number;
  private readonly tailLimit: number;
  private headChunks: Buffer[] = [];
  private headBytes = 0;
  private tailChunks: Buffer[] = [];
  private tailBytes = 0;
  private totalBytes = 0;
  private overflowed = false;

  constructor(maxBytes: number) {
    this.maxBytes = Math.max(4096, maxBytes);
    this.headLimit = Math.floor(this.maxBytes * 0.4);
    this.tailLimit = this.maxBytes - this.headLimit;
  }

  public appendBuffer(buf: Buffer): void {
    if (buf.length === 0) return;
    this.totalBytes += buf.length;

    if (!this.overflowed) {
      if (this.headBytes + buf.length <= this.maxBytes) {
        this.headChunks.push(buf);
        this.headBytes += buf.length;
        return;
      }
      // Transition cleanly into head + rolling tail mode
      this.overflowed = true;
      const combined = Buffer.concat([...this.headChunks, buf], this.headBytes + buf.length);
      const headSlice = combined.subarray(0, this.headLimit);
      const tailSlice = combined.subarray(Math.max(this.headLimit, combined.length - this.tailLimit));
      this.headChunks = [Buffer.from(headSlice)];
      this.headBytes = headSlice.length;
      this.tailChunks = [Buffer.from(tailSlice)];
      this.tailBytes = tailSlice.length;
      return;
    }

    this.tailChunks.push(buf);
    this.tailBytes += buf.length;
    if (this.tailBytes > this.tailLimit * 2) {
      const merged = Buffer.concat(this.tailChunks, this.tailBytes);
      const trimmed = Buffer.from(merged.subarray(merged.length - this.tailLimit));
      this.tailChunks = [trimmed];
      this.tailBytes = trimmed.length;
    }
  }

  public appendText(text: string): void {
    if (!text) return;
    this.appendBuffer(Buffer.from(text, 'utf8'));
  }

  public get omittedBytes(): number {
    if (!this.overflowed) return 0;
    const keptTail = Math.min(this.tailBytes, this.tailLimit);
    return Math.max(0, this.totalBytes - (this.headBytes + keptTail));
  }

  public toString(): string {
    const decoder = new StringDecoder('utf8');
    if (!this.overflowed) {
      const buf = Buffer.concat(this.headChunks, this.headBytes);
      return decoder.write(buf) + decoder.end();
    }
    const headBuf = Buffer.concat(this.headChunks, this.headBytes);
    const tailFull = Buffer.concat(this.tailChunks, this.tailBytes);
    const tailBuf =
      tailFull.length > this.tailLimit
        ? tailFull.subarray(tailFull.length - this.tailLimit)
        : tailFull;
    const headText = new StringDecoder('utf8').end(headBuf);
    const tailText = new StringDecoder('utf8').end(tailBuf);
    return `${headText}\n... [${this.omittedBytes} bytes omitted due to capture limit] ...\n${tailText}`;
  }
}

function extractErrorSignature(stderr: string, stdout: string, command: string): string {
  const combined = `${stderr}\n${stdout}`;
  const lines = combined
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter(Boolean);
  const errorLine = lines.find((l) =>
    /(error|exception|failed|fatal|panic|syntaxerror|typeerror|referenceerror|enoent|eaddrinuse|assertion)/i.test(
      l
    )
  );
  return (errorLine ?? lines[lines.length - 1] ?? `Command failed: ${command}`).slice(0, 200);
}

function extractReferencedPaths(output: string): string[] {
  const matches =
    output.match(
      /(?:^|[\s("'])([a-zA-Z0-9_./-]+\.(?:ts|tsx|js|jsx|py|go|rs|java|yml|yaml|json|sh|dockerfile))/gi
    ) ?? [];
  const cleaned = matches
    .map((m) => m.replace(/^[\s("']+/, '').replace(/^\.\//, ''))
    .filter((p) => !p.startsWith('node_modules/') && !p.startsWith('/usr/') && !p.startsWith('/opt/'));
  return Array.from(new Set(cleaned)).slice(0, 15);
}

/**
 * Executes a workspace command with bounded stdout/stderr memory capture, optional timeout,
 * parent signal forwarding, shell-free `argv` support, automatic secret redaction,
 * and crash -> fix lesson correlation.
 */
export async function runWatchedCommand(
  store: StreamStore,
  options: CommandRunOptions
): Promise<CommandRunResult> {
  const cwd = options.cwd ?? store.workspaceRoot;
  const harness = options.harness ?? 'cli';
  const sessionId = options.sessionId ?? `exec-${Date.now()}`;
  const actor = { kind: 'human' as const, id: options.actorId ?? process.env.USER ?? 'operator' };
  const safeCommand = redactSecrets(options.command);
  const maxCaptureBytes = options.maxCaptureBytes ?? 2_000_000;

  const startEvent = store.append({
    type: 'exec.started',
    actor,
    harness,
    sessionId,
    summary: `Running command: ${safeCommand}`,
    tags: ['exec', ...(options.tags ?? [])],
    payload: { command: safeCommand, cwd }
  });

  const startedAt = Date.now();
  const stdoutBuf = new BoundedOutputBuffer(maxCaptureBytes);
  const stderrBuf = new BoundedOutputBuffer(maxCaptureBytes);
  let timedOut = false;

  const useProcessGroup = Boolean(options.timeoutMs && options.timeoutMs > 0 && process.platform !== 'win32');
  const useDirectArgv = Boolean(options.argv && options.argv.length > 0);

  const { exitCode, signal } = await new Promise<{ exitCode: number | null; signal: string | null }>(
    (resolve) => {
      const spawnOpts = {
        cwd,
        detached: useProcessGroup,
        env: options.env ?? process.env,
        stdio: [useProcessGroup ? 'ignore' : 'inherit', 'pipe', 'pipe'] as ['ignore' | 'inherit', 'pipe', 'pipe']
      };
      const child = useDirectArgv
        ? spawn(options.argv![0]!, options.argv!.slice(1), { ...spawnOpts, shell: false })
        : spawn(options.command, { ...spawnOpts, shell: true });

      const killTree = (sig: NodeJS.Signals) => {
        if (useProcessGroup && child.pid) {
          try {
            process.kill(-child.pid, sig);
            return;
          } catch {
            // fall through to direct kill
          }
        }
        try {
          child.kill(sig);
        } catch {
          // ignore
        }
      };

      const onParentSigInt = () => killTree('SIGINT');
      const onParentSigTerm = () => killTree('SIGTERM');
      process.on('SIGINT', onParentSigInt);
      process.on('SIGTERM', onParentSigTerm);

      let timeoutHandle: NodeJS.Timeout | null = null;
      let killHandle: NodeJS.Timeout | null = null;
      if (options.timeoutMs && options.timeoutMs > 0) {
        timeoutHandle = setTimeout(() => {
          timedOut = true;
          killTree('SIGTERM');
          killHandle = setTimeout(() => {
            killTree('SIGKILL');
          }, 1500);
        }, options.timeoutMs);
      }

      const cleanup = () => {
        if (timeoutHandle) clearTimeout(timeoutHandle);
        if (killHandle) clearTimeout(killHandle);
        process.removeListener('SIGINT', onParentSigInt);
        process.removeListener('SIGTERM', onParentSigTerm);
      };

      child.stdout?.on('data', (chunk: Buffer) => {
        stdoutBuf.appendBuffer(chunk);
        if (!options.silent) process.stdout.write(chunk);
      });

      child.stderr?.on('data', (chunk: Buffer) => {
        stderrBuf.appendBuffer(chunk);
        if (!options.silent) process.stderr.write(chunk);
      });

      child.on('close', (code, sig) => {
        cleanup();
        resolve({ exitCode: code, signal: sig });
      });

      child.on('error', (err) => {
        cleanup();
        stderrBuf.appendText(`\nSpawn error: ${err.message}`);
        resolve({ exitCode: 127, signal: null });
      });
    }
  );

  const durationMs = Date.now() - startedAt;
  const stdout = redactSecrets(stdoutBuf.toString());
  const stderr = redactSecrets(stderrBuf.toString());

  const succeeded = exitCode === 0 && !signal && !timedOut;
  const crashed = timedOut || Boolean(signal) || (exitCode !== null && exitCode >= 128);
  const type = succeeded ? 'exec.completed' : crashed ? 'exec.crashed' : 'exec.failed';
  const affectedPaths = extractReferencedPaths(`${stderr}\n${stdout}`);
  const errorSignature = succeeded
    ? ''
    : timedOut
      ? `Command timed out after ${options.timeoutMs}ms: ${safeCommand}`
      : extractErrorSignature(stderr, stdout, safeCommand);

  const fallbackBlobs: Array<{ key: string; content: string; contentType: string }> = [];
  if (stdout.length > 2000) {
    fallbackBlobs.push({ key: 'stdout', content: stdout, contentType: 'text/plain; charset=utf-8' });
  }
  if (stderr.length > 1000) {
    fallbackBlobs.push({ key: 'stderr', content: stderr, contentType: 'text/plain; charset=utf-8' });
  }

  const endEvent = store.append({
    type,
    actor,
    harness,
    sessionId,
    causationId: startEvent.id,
    correlationId: startEvent.id,
    summary: succeeded
      ? `Succeeded (${durationMs}ms): ${safeCommand}`
      : `${crashed ? 'Crashed' : 'Failed'} (exit ${exitCode ?? signal ?? 'timeout'}, ${durationMs}ms): ${safeCommand} — ${errorSignature.slice(0, 100)}`,
    affectedPaths,
    tags: [
      'exec',
      succeeded ? 'success' : crashed ? 'crash' : 'failure',
      ...(timedOut ? ['timeout'] : []),
      ...(options.tags ?? [])
    ],
    payload: {
      command: safeCommand,
      exitCode,
      signal,
      timedOut: timedOut || undefined,
      durationMs,
      stdoutTruncatedBytes: stdoutBuf.omittedBytes || undefined,
      stderrTruncatedBytes: stderrBuf.omittedBytes || undefined,
      errorSignature: errorSignature || undefined,
      stdoutExcerpt: stdout.slice(-1500),
      stderrExcerpt: stderr.slice(-1500)
    },
    fallbackBlobs
  });

  let autoCapturedLesson: StreamEvent | undefined;
  if (succeeded) {
    const lessonEngine = new LessonEngine(store);
    const correlation = lessonEngine.detectFailureToFixCorrelation(endEvent);
    if (correlation) {
      autoCapturedLesson = store.append({
        type: 'lesson.captured',
        actor: { kind: 'numberone', id: 'lesson-engine', name: 'Number One Curator' },
        harness,
        sessionId,
        causationId: endEvent.id,
        correlationId: correlation.crashEvent.id,
        summary: correlation.suggestedLesson.title,
        affectedPaths: correlation.suggestedLesson.affectedPaths,
        tags: correlation.suggestedLesson.tags,
        payload: {
          ...correlation.suggestedLesson,
          severity: 'medium',
          verified: true
        }
      });
    }
  }

  return {
    exitCode,
    signal,
    timedOut,
    durationMs,
    stdout,
    stderr,
    stdoutTruncatedBytes: stdoutBuf.omittedBytes,
    stderrTruncatedBytes: stderrBuf.omittedBytes,
    startEvent,
    endEvent,
    autoCapturedLesson
  };
}

function formatSafeShellHookCommand(cliCommand: string | string[]): string {
  if (Array.isArray(cliCommand)) {
    if (cliCommand.length === 0) {
      throw new Error('CLI command array for shell hook cannot be empty.');
    }
    for (const part of cliCommand) {
      if (!part || /[\r\n\0]/.test(part)) {
        throw new Error(`Unsafe CLI command token for shell hook: ${part}`);
      }
    }
    return cliCommand.map((p) => shellSingleQuote(p)).join(' ');
  }
  if (!/^[A-Za-z0-9._/-]+$/.test(cliCommand)) {
    throw new Error(`Unsafe CLI command for shell hook: ${cliCommand}`);
  }
  return shellSingleQuote(cliCommand);
}

/**
 * Generates injection-safe bash/zsh shell hooks using environment variables
 * (`N1_SHELL_CMD` and `N1_SHELL_EXIT`), strict POSIX single-quoting, and command-activity guards.
 */
export function generateShellHook(
  shell: 'bash' | 'zsh' = 'bash',
  cliCommand: string | string[] = 'numberone'
): string {
  const safeInvocation = formatSafeShellHookCommand(cliCommand);
  if (shell === 'zsh') {
    return [
      '# Number One Zsh Integration — add to ~/.zshrc',
      '__N1_CMD_ACTIVE=0',
      '__N1_LAST_CMD=""',
      '__n1_preexec() {',
      '  __N1_LAST_CMD="$1"',
      '  __N1_CMD_ACTIVE=1',
      '}',
      '__n1_precmd() {',
      '  local ec=$?',
      '  if [ "$__N1_CMD_ACTIVE" -eq 1 ] && [ "$ec" -ne 0 ] && [ -n "$__N1_LAST_CMD" ] && [ -d ".numberone" ]; then',
      `    N1_SHELL_CMD="$__N1_LAST_CMD" N1_SHELL_EXIT="$ec" N1_SHELL_NAME="zsh" ${safeInvocation} record-shell-failure >/dev/null 2>&1 || true`,
      '  fi',
      '  __N1_CMD_ACTIVE=0',
      '  __N1_LAST_CMD=""',
      '}',
      'autoload -Uz add-zsh-hook',
      'add-zsh-hook preexec __n1_preexec',
      'add-zsh-hook precmd __n1_precmd'
    ].join('\n');
  }
  return [
    '# Number One Bash Integration — add to ~/.bashrc',
    '__N1_CMD_ACTIVE=0',
    '__N1_LAST_CMD=""',
    '__n1_preexec() {',
    '  case "$1" in',
    '    __n1_prompt_command*|__n1_preexec*) return 0 ;;',
    '  esac',
    '  __N1_LAST_CMD="$1"',
    '  __N1_CMD_ACTIVE=1',
    '}',
    '__n1_prompt_command() {',
    '  local ec=$?',
    '  if [ "$__N1_CMD_ACTIVE" -eq 1 ] && [ "$ec" -ne 0 ] && [ -n "$__N1_LAST_CMD" ] && [ -d ".numberone" ]; then',
    `    N1_SHELL_CMD="$__N1_LAST_CMD" N1_SHELL_EXIT="$ec" N1_SHELL_NAME="bash" ${safeInvocation} record-shell-failure >/dev/null 2>&1 || true`,
    '  fi',
    '  __N1_CMD_ACTIVE=0',
    '  __N1_LAST_CMD=""',
    '}',
    'trap \'__n1_preexec "$BASH_COMMAND"\' DEBUG',
    'PROMPT_COMMAND="__n1_prompt_command${PROMPT_COMMAND:+; $PROMPT_COMMAND}"'
  ].join('\n');
}

import { spawn } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { StreamStore } from '../core/stream-store.js';
import { atomicWriteJsonSync, ensureDir, readJsonSafe } from '../utils/fs-helpers.js';
import { isProcessAlive, readProcStartTicks, withFileLockSync } from '../utils/lock.js';

export interface DaemonPidRecord {
  pid: number;
  startedAt: string;
  workspaceRoot: string;
  cliEntryScript: string;
  procStartTicks?: string | null;
}

export interface DaemonStatus {
  running: boolean;
  pid: number | null;
  startedAt: string | null;
  pidFile: string;
  logFile: string;
}

const MAX_LOG_BYTES = 5 * 1024 * 1024;
const SLEEP_ARR = new Int32Array(new SharedArrayBuffer(4));

function sleepSyncMs(ms: number): void {
  Atomics.wait(SLEEP_ARR, 0, 0, Math.max(1, ms));
}

/**
 * Verifies on Linux (`/proc/<pid>/cmdline` and `/proc/<pid>/stat` start ticks) that a PID
 * still belongs to our Number One watcher process for the EXACT `workspaceRoot`
 * (preventing prefix collisions like `/workspace` matching `/workspace-other` and OS PID reuse).
 */
function verifyPidMatchesWatcher(
  pid: number,
  workspaceRoot: string,
  expectedStartTicks?: string | null
): boolean {
  if (!isProcessAlive(pid)) return false;

  if (expectedStartTicks) {
    const liveTicks = readProcStartTicks(pid);
    if (liveTicks !== null && liveTicks !== expectedStartTicks) {
      return false;
    }
  }

  const cmdlinePath = `/proc/${pid}/cmdline`;
  if (fs.existsSync(cmdlinePath)) {
    try {
      const raw = fs.readFileSync(cmdlinePath, 'utf8');
      const args = raw.split('\0').filter((s) => s.length > 0);
      const hasWatch = args.includes('watch');
      const wsIdx = args.indexOf('--workspace');
      const exactWsMatch =
        (wsIdx !== -1 && args[wsIdx + 1] === workspaceRoot) ||
        args.includes(`--workspace=${workspaceRoot}`);
      return hasWatch && exactWsMatch;
    } catch {
      return false;
    }
  }
  // On non-Linux platforms without /proc, fall back to process existence check
  return true;
}

export class WatcherDaemonManager {
  private readonly pidFile: string;
  private readonly logFile: string;
  private readonly lockFile: string;
  private readonly workspaceRoot: string;

  constructor(store: StreamStore) {
    this.workspaceRoot = store.workspaceRoot;
    this.pidFile = path.join(store.rootDir, 'daemon.pid');
    this.logFile = path.join(store.rootDir, 'daemon.log');
    this.lockFile = path.join(store.rootDir, '.daemon.lock');
  }

  private readPidRecord(): DaemonPidRecord | null {
    const json = readJsonSafe<DaemonPidRecord>(this.pidFile);
    if (json && typeof json.pid === 'number' && Number.isFinite(json.pid)) {
      return json;
    }
    // Backward compatibility with legacy bare-integer pidfile
    try {
      if (!fs.existsSync(this.pidFile)) return null;
      const raw = fs.readFileSync(this.pidFile, 'utf8').trim();
      const pid = Number.parseInt(raw, 10);
      if (Number.isFinite(pid)) {
        return {
          pid,
          startedAt: '',
          workspaceRoot: this.workspaceRoot,
          cliEntryScript: ''
        };
      }
    } catch {
      // ignore
    }
    return null;
  }

  private rotateLogIfOversized(): void {
    try {
      const stat = fs.lstatSync(this.logFile);
      if (stat.isSymbolicLink()) {
        throw new Error(`Refusing to write daemon log to symlink: ${this.logFile}`);
      }
      if (stat.isFile() && stat.size > MAX_LOG_BYTES) {
        fs.renameSync(this.logFile, `${this.logFile}.1`);
      }
    } catch (err) {
      if ((err as NodeJS.ErrnoException)?.code === 'ENOENT') return;
      throw err;
    }
  }

  public getStatus(): DaemonStatus {
    const record = this.readPidRecord();
    if (!record) {
      return {
        running: false,
        pid: null,
        startedAt: null,
        pidFile: this.pidFile,
        logFile: this.logFile
      };
    }

    if (verifyPidMatchesWatcher(record.pid, this.workspaceRoot, record.procStartTicks)) {
      return {
        running: true,
        pid: record.pid,
        startedAt: record.startedAt || null,
        pidFile: this.pidFile,
        logFile: this.logFile
      };
    }

    return {
      running: false,
      pid: null,
      startedAt: null,
      pidFile: this.pidFile,
      logFile: this.logFile
    };
  }

  public startDetached(cliEntryScript: string): DaemonStatus {
    ensureDir(path.dirname(this.logFile), 0o700);
    return withFileLockSync(this.lockFile, () => {
      const existing = this.getStatus();
      if (existing.running) return existing;

      this.rotateLogIfOversized();

      const openFlags =
        fs.constants.O_WRONLY |
        fs.constants.O_CREAT |
        fs.constants.O_APPEND |
        (fs.constants.O_NOFOLLOW ?? 0);
      const outFd = fs.openSync(this.logFile, openFlags, 0o600);
      let childPid: number | undefined;
      try {
        const child = spawn(
          process.execPath,
          [cliEntryScript, 'watch', '--foreground', '--workspace', this.workspaceRoot],
          {
            cwd: this.workspaceRoot,
            detached: true,
            stdio: ['ignore', outFd, outFd]
          }
        );
        child.unref();
        childPid = child.pid;
      } finally {
        // Always close inherited FD in parent process to prevent FD leak
        try {
          fs.closeSync(outFd);
        } catch {
          // ignore
        }
      }

      const startedAt = new Date().toISOString();
      if (childPid) {
        const record: DaemonPidRecord = {
          pid: childPid,
          startedAt,
          workspaceRoot: this.workspaceRoot,
          cliEntryScript,
          procStartTicks: readProcStartTicks(childPid)
        };
        atomicWriteJsonSync(this.pidFile, record, 0o600);
      }

      return {
        running: Boolean(childPid && isProcessAlive(childPid)),
        pid: childPid ?? null,
        startedAt: childPid ? startedAt : null,
        pidFile: this.pidFile,
        logFile: this.logFile
      };
    });
  }

  public stop(): { stopped: boolean; pid: number | null; reason?: string } {
    ensureDir(path.dirname(this.lockFile), 0o700);
    return withFileLockSync(this.lockFile, () => {
      const record = this.readPidRecord();
      if (!record) {
        return { stopped: false, pid: null, reason: 'No daemon PID file found.' };
      }
      if (!verifyPidMatchesWatcher(record.pid, this.workspaceRoot, record.procStartTicks)) {
        if (fs.existsSync(this.pidFile)) {
          try {
            fs.unlinkSync(this.pidFile);
          } catch {
            // ignore
          }
        }
        const alive = isProcessAlive(record.pid);
        return {
          stopped: false,
          pid: null,
          reason: alive
            ? `PID ${record.pid} is alive but is not a Number One watcher for ${this.workspaceRoot}; refused to kill (PID reuse guard).`
            : `Stale PID ${record.pid} is no longer running; cleaned up daemon.pid.`
        };
      }

      try {
        process.kill(record.pid, 'SIGTERM');
      } catch {
        // already stopped
      }

      // Wait briefly (up to 3s) for graceful flush & exit before removing daemon.pid
      const deadline = Date.now() + 3000;
      while (Date.now() < deadline && verifyPidMatchesWatcher(record.pid, this.workspaceRoot, record.procStartTicks)) {
        sleepSyncMs(50);
      }

      const stillRunning = verifyPidMatchesWatcher(
        record.pid,
        this.workspaceRoot,
        record.procStartTicks
      );
      if (!stillRunning) {
        try {
          if (fs.existsSync(this.pidFile)) fs.unlinkSync(this.pidFile);
        } catch {
          // ignore
        }
      }
      return {
        stopped: !stillRunning,
        pid: record.pid,
        reason: stillRunning ? `Sent SIGTERM to PID ${record.pid}, still flushing.` : undefined
      };
    });
  }
}

import fs from 'node:fs';
import path from 'node:path';
import { sha256Hex } from '../core/hash.js';
import { StreamStore } from '../core/stream-store.js';
import { StreamEvent, WorkspaceProjection } from '../core/types.js';
import { computeUnifiedDiff } from '../utils/diff.js';
import {
  isBinaryBuffer,
  readFileBufferSafe,
  readTextFileSafe,
  walkWorkspaceFiles
} from '../utils/fs-helpers.js';
import { WorkspaceIgnore } from '../utils/ignore.js';
import { isSensitiveSecretFile, redactSecrets } from '../utils/redactor.js';

interface CachedFile {
  hash: string;
  size: number;
  text: string | null;
  sensitiveRedacted: boolean;
}

const CRASH_FILE_PATTERNS = [
  /^hs_err_pid\d+\.log$/i,
  /crash[-_.]?.*\.log$/i,
  /npm-debug\.log$/i,
  /yarn-error\.log$/i,
  /panic\.log$/i
];

function isCrashLogFile(relPath: string): boolean {
  const base = path.basename(relPath);
  return CRASH_FILE_PATTERNS.some((rx) => rx.test(base));
}

export interface FsWatcherOptions {
  debounceMs?: number;
  maxInlineDiffBytes?: number;
  maxWatchedDirs?: number;
  /** Whether fs.watch handles keep the Node.js event loop alive (default false for embedded use, true for daemon). */
  persistent?: boolean;
  extraIgnore?: string[];
  sessionId?: string;
  onEvent?: (event: StreamEvent) => void;
}

const MAX_TOTAL_CACHED_TEXT_BYTES = 64 * 1024 * 1024;

/**
 * Hardened recursive workspace filesystem watcher:
 *  - Symlink-escape & non-regular file safe (rejects symlinks leaving workspaceRoot & FIFOs)
 *  - Never captures raw diffs or blobs for sensitive secret files (.env, *.pem, *.key, id_rsa, etc.)
 *  - Caps max inotify directory watches to avoid OS ENOSPC exhaustion and caps cached text at 64 MB
 *  - Prunes full deleted directory subtrees and schedules descendant deletion events
 *  - Flushes debounced changes cleanly on shutdown without crashing on transient store errors
 */
export class WorkspaceFsWatcher {
  private readonly store: StreamStore;
  private readonly ignore: WorkspaceIgnore;
  private readonly debounceMs: number;
  private readonly maxInlineDiffBytes: number;
  private readonly maxWatchedDirs: number;
  private readonly persistent: boolean;
  private readonly sessionId: string;
  private readonly onEvent?: (event: StreamEvent) => void;

  private readonly snapshot = new Map<string, CachedFile>();
  private cachedTextBytes = 0;
  private readonly dirWatchers = new Map<string, fs.FSWatcher>();
  private readonly pendingPaths = new Set<string>();
  private flushTimer: NodeJS.Timeout | null = null;
  private running = false;

  constructor(store: StreamStore, options: FsWatcherOptions = {}) {
    this.store = store;
    const cfg = store.readConfig();
    this.debounceMs = options.debounceMs ?? cfg?.watcher.debounceMs ?? 200;
    this.maxInlineDiffBytes =
      options.maxInlineDiffBytes ?? cfg?.watcher.maxInlineDiffBytes ?? 16_384;
    this.maxWatchedDirs = options.maxWatchedDirs ?? 2_000;
    this.persistent = options.persistent ?? false;
    this.ignore = new WorkspaceIgnore(store.workspaceRoot, [
      ...(cfg?.watcher.ignore ?? []),
      ...(options.extraIgnore ?? [])
    ]);
    this.sessionId = options.sessionId ?? `watcher-${Date.now()}`;
    this.onEvent = options.onEvent;
  }

  private setSnapshotEntry(relPath: string, entry: CachedFile): void {
    const prev = this.snapshot.get(relPath);
    if (prev?.text !== null && prev?.text !== undefined) {
      this.cachedTextBytes = Math.max(0, this.cachedTextBytes - Buffer.byteLength(prev.text, 'utf8'));
    }
    let stored = entry;
    if (entry.text !== null) {
      const nextBytes = Buffer.byteLength(entry.text, 'utf8');
      if (this.cachedTextBytes + nextBytes > MAX_TOTAL_CACHED_TEXT_BYTES) {
        // Retain metadata/hash so changes & deletions are still detected without OOM
        stored = { ...entry, text: null };
      } else {
        this.cachedTextBytes += nextBytes;
      }
    }
    this.snapshot.set(relPath, stored);
  }

  private deleteSnapshotEntry(relPath: string): void {
    const prev = this.snapshot.get(relPath);
    if (prev?.text !== null && prev?.text !== undefined) {
      this.cachedTextBytes = Math.max(0, this.cachedTextBytes - Buffer.byteLength(prev.text, 'utf8'));
    }
    this.snapshot.delete(relPath);
  }

  private readFileState(relPath: string): CachedFile | null {
    const abs = path.join(this.store.workspaceRoot, relPath);
    const buf = readFileBufferSafe(abs, 512_000, this.store.workspaceRoot);
    if (!buf) return null;

    const hash = sha256Hex(buf);
    const sensitive = isSensitiveSecretFile(relPath);
    if (sensitive) {
      // Never retain plaintext content of secret files in memory, diffs, or blobs!
      return { hash, size: buf.length, text: null, sensitiveRedacted: true };
    }
    const text = !isBinaryBuffer(buf) ? buf.toString('utf8') : null;
    return { hash, size: buf.length, text, sensitiveRedacted: false };
  }

  public primeSnapshot(): number {
    this.snapshot.clear();
    this.cachedTextBytes = 0;
    const files = walkWorkspaceFiles(this.store.workspaceRoot, (p, d) =>
      this.ignore.shouldIgnore(p, d)
    );
    for (const rel of files) {
      const info = this.readFileState(rel);
      if (info) {
        this.setSnapshotEntry(rel, info);
      }
    }
    return this.snapshot.size;
  }

  public recordBaselineSnapshot(causationId?: string, harness = 'cli'): StreamEvent {
    this.primeSnapshot();
    const fileEntries: Array<{
      path: string;
      contentHash: string;
      sizeBytes: number;
      snapshotBlobHash?: string;
      sensitiveRedacted?: boolean;
    }> = [];

    for (const [rel, info] of Array.from(this.snapshot.entries()).sort((a, b) =>
      a[0].localeCompare(b[0])
    )) {
      let snapshotBlobHash: string | undefined;
      if (!info.sensitiveRedacted && info.text !== null && info.size <= 256_000) {
        const blob = this.store.storeBlob('snapshot', info.text, 'text/plain; charset=utf-8');
        snapshotBlobHash = blob.sha256;
      }
      fileEntries.push({
        path: rel,
        contentHash: info.hash,
        sizeBytes: info.size,
        snapshotBlobHash,
        sensitiveRedacted: info.sensitiveRedacted || undefined
      });
    }

    return this.store.append({
      type: 'workspace.snapshot',
      actor: { kind: 'watcher', id: 'fs-watcher', name: 'Workspace Watcher' },
      harness,
      sessionId: this.sessionId,
      causationId,
      summary: `Indexed workspace baseline (${fileEntries.length} files)`,
      affectedPaths: fileEntries.map((f) => f.path).slice(0, 200),
      tags: ['snapshot', 'baseline'],
      payload: {
        fileCount: fileEntries.length,
        files: fileEntries
      }
    });
  }

  public reconcileOfflineChanges(projection: WorkspaceProjection): StreamEvent[] {
    const emitted: StreamEvent[] = [];
    const currentFiles = new Set(
      walkWorkspaceFiles(this.store.workspaceRoot, (p, d) => this.ignore.shouldIgnore(p, d))
    );

    const newlyAppeared = new Map<string, CachedFile>();
    const modifiedFiles: Array<{ rel: string; prev: CachedFile | null; curr: CachedFile }> = [];

    for (const rel of currentFiles) {
      const disk = this.readFileState(rel);
      if (!disk) continue;
      this.setSnapshotEntry(rel, disk);

      const projected = projection.files[rel];
      if (!projected || projected.status === 'deleted') {
        newlyAppeared.set(rel, disk);
      } else if (projected.lastHash && projected.lastHash !== disk.hash) {
        const prevText =
          !disk.sensitiveRedacted && projected.lastSnapshotBlobHash
            ? this.store.readBlobUtf8(projected.lastSnapshotBlobHash)
            : null;
        const prevCached: CachedFile | null =
          prevText !== null
            ? {
                hash: projected.lastHash,
                size: Buffer.byteLength(prevText, 'utf8'),
                text: prevText,
                sensitiveRedacted: false
              }
            : null;
        modifiedFiles.push({ rel, prev: prevCached, curr: disk });
      }
    }

    const disappeared = new Map<string, { lastHash?: string }>();
    for (const [rel, rec] of Object.entries(projection.files)) {
      if (rec.status === 'exists' && !currentFiles.has(rel) && !this.ignore.shouldIgnore(rel, false)) {
        // Confirm entry is genuinely absent on disk before recording fs.deleted
        const abs = path.join(this.store.workspaceRoot, rel);
        if (fs.existsSync(abs)) continue;
        this.deleteSnapshotEntry(rel);
        disappeared.set(rel, { lastHash: rec.lastHash });
      }
    }

    for (const [oldPath, oldInfo] of Array.from(disappeared.entries())) {
      if (!oldInfo.lastHash) continue;
      const matchingNew = Array.from(newlyAppeared.entries()).find(
        ([, newInfo]) => newInfo.hash === oldInfo.lastHash
      );
      if (matchingNew) {
        const [newPath, newInfo] = matchingNew;
        disappeared.delete(oldPath);
        newlyAppeared.delete(newPath);
        emitted.push(this.emitRenameEvent(oldPath, newPath, newInfo, 'offline-reconcile'));
      }
    }

    for (const [rel, disk] of newlyAppeared.entries()) {
      emitted.push(this.emitFileEvent('fs.created', rel, null, disk, 'offline-reconcile'));
    }

    for (const mod of modifiedFiles) {
      emitted.push(this.emitFileEvent('fs.modified', mod.rel, mod.prev, mod.curr, 'offline-reconcile'));
    }

    for (const [rel, rec] of disappeared.entries()) {
      const ev = this.store.append({
        type: 'fs.deleted',
        actor: { kind: 'watcher', id: 'fs-watcher', name: 'Workspace Watcher' },
        harness: 'manual',
        sessionId: this.sessionId,
        summary: `Deleted ${rel} (detected on offline reconciliation)`,
        affectedPaths: [rel],
        tags: ['fs', 'offline-reconcile'],
        payload: { path: rel, previousHash: rec.lastHash }
      });
      emitted.push(ev);
      this.onEvent?.(ev);
    }

    return emitted;
  }

  public start(): void {
    if (this.running) return;
    this.running = true;
    if (this.snapshot.size === 0) {
      this.primeSnapshot();
    }
    this.watchDirectoryRecursive('');
  }

  public stop(flush = true): void {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = null;
    }
    if (flush && this.pendingPaths.size > 0) {
      try {
        this.flushPending();
      } catch {
        // best-effort final flush on shutdown
      }
    }
    this.running = false;
    for (const watcher of this.dirWatchers.values()) {
      try {
        watcher.close();
      } catch {
        // ignore
      }
    }
    this.dirWatchers.clear();
  }

  private pruneDeletedDirWatcher(relDir: string): void {
    const prefix = relDir ? `${relDir}/` : '';
    for (const [dirKey, watcher] of Array.from(this.dirWatchers.entries())) {
      if (dirKey === relDir || (prefix && dirKey.startsWith(prefix))) {
        try {
          watcher.close();
        } catch {
          // ignore
        }
        this.dirWatchers.delete(dirKey);
      }
    }
    // Schedule all snapshot files that lived inside the removed/renamed directory
    if (prefix) {
      for (const fileKey of this.snapshot.keys()) {
        if (fileKey === relDir || fileKey.startsWith(prefix)) {
          this.schedulePath(fileKey);
        }
      }
    }
  }

  private watchDirectoryRecursive(relDir: string): void {
    if (!this.running) return;
    if (relDir && this.ignore.shouldIgnore(relDir, true)) return;
    if (this.dirWatchers.has(relDir)) return;
    if (this.dirWatchers.size >= this.maxWatchedDirs) return;

    const absDir = relDir ? path.join(this.store.workspaceRoot, relDir) : this.store.workspaceRoot;
    try {
      const lstat = fs.lstatSync(absDir);
      if (lstat.isSymbolicLink() || !lstat.isDirectory()) return;
    } catch {
      return;
    }

    try {
      const watcher = fs.watch(absDir, { persistent: this.persistent }, (_eventType, filename) => {
        if (!filename) return;
        const name = filename.toString();
        const childRel = relDir ? `${relDir}/${name}` : name;
        const normalized = childRel.replace(/\\/g, '/');
        const absChild = path.join(this.store.workspaceRoot, normalized);

        let isDir = false;
        let isSymlink = false;
        try {
          const st = fs.lstatSync(absChild);
          isSymlink = st.isSymbolicLink();
          isDir = !isSymlink && st.isDirectory();
        } catch {
          // Entry vanished: prune its entire watched directory subtree and schedule child deletions
          this.pruneDeletedDirWatcher(normalized);
        }

        if (isSymlink || this.ignore.shouldIgnore(normalized, isDir)) return;

        if (isDir) {
          this.watchDirectoryRecursive(normalized);
          const nested = walkWorkspaceFiles(absChild, (p, d) =>
            this.ignore.shouldIgnore(`${normalized}/${p}`, d)
          );
          for (const f of nested) {
            this.schedulePath(`${normalized}/${f}`);
          }
          return;
        }

        this.schedulePath(normalized);
      });

      watcher.on('error', () => {
        this.pruneDeletedDirWatcher(relDir);
      });
      this.dirWatchers.set(relDir, watcher);

      const entries = fs.readdirSync(absDir, { withFileTypes: true });
      for (const entry of entries) {
        if (entry.isSymbolicLink() || !entry.isDirectory()) continue;
        const childRel = relDir ? `${relDir}/${entry.name}` : entry.name;
        this.watchDirectoryRecursive(childRel);
      }
    } catch {
      // Directory vanished or inaccessible
    }
  }

  private schedulePath(relPath: string): void {
    this.pendingPaths.add(relPath);
    if (this.flushTimer) clearTimeout(this.flushTimer);
    this.flushTimer = setTimeout(() => {
      this.flushTimer = null;
      try {
        this.flushPending();
      } catch (err) {
        // Keep long-running daemon alive on transient I/O or lock errors
        console.error(
          `[numberone-watcher] Flush error: ${err instanceof Error ? err.message : String(err)}`
        );
      }
    }, this.debounceMs);
  }

  public flushPending(): StreamEvent[] {
    const paths = Array.from(this.pendingPaths).sort();
    this.pendingPaths.clear();
    const emitted: StreamEvent[] = [];

    const created = new Map<string, CachedFile>();
    const deleted = new Map<string, CachedFile>();
    const modified: Array<{ rel: string; prev: CachedFile; curr: CachedFile }> = [];

    for (const rel of paths) {
      if (this.ignore.shouldIgnore(rel, false)) continue;
      const prev = this.snapshot.get(rel) ?? null;
      const curr = this.readFileState(rel);

      if (!prev && curr) {
        created.set(rel, curr);
      } else if (prev && !curr) {
        deleted.set(rel, prev);
      } else if (prev && curr && prev.hash !== curr.hash) {
        modified.push({ rel, prev, curr });
      }
    }

    for (const [oldPath, oldInfo] of Array.from(deleted.entries())) {
      const match = Array.from(created.entries()).find(([, newInfo]) => newInfo.hash === oldInfo.hash);
      if (match) {
        const [newPath, newInfo] = match;
        deleted.delete(oldPath);
        created.delete(newPath);
        const ev = this.emitRenameEvent(oldPath, newPath, newInfo, 'live-watch');
        // Mutate snapshot ONLY after store.append() succeeded
        this.deleteSnapshotEntry(oldPath);
        this.setSnapshotEntry(newPath, newInfo);
        emitted.push(ev);
      }
    }

    for (const [rel, curr] of created.entries()) {
      const ev = this.emitFileEvent('fs.created', rel, null, curr, 'live-watch');
      this.setSnapshotEntry(rel, curr);
      emitted.push(ev);
    }

    for (const mod of modified) {
      const ev = this.emitFileEvent('fs.modified', mod.rel, mod.prev, mod.curr, 'live-watch');
      this.setSnapshotEntry(mod.rel, mod.curr);
      emitted.push(ev);
    }

    for (const [rel, prev] of deleted.entries()) {
      const ev = this.store.append({
        type: 'fs.deleted',
        actor: { kind: 'watcher', id: 'fs-watcher', name: 'Workspace Watcher' },
        harness: 'watcher',
        sessionId: this.sessionId,
        summary: `Deleted ${rel}`,
        affectedPaths: [rel],
        tags: ['fs', 'live-watch'],
        payload: { path: rel, previousHash: prev.hash, previousSize: prev.size }
      });
      this.deleteSnapshotEntry(rel);
      emitted.push(ev);
      this.onEvent?.(ev);
    }

    return emitted;
  }

  private emitRenameEvent(
    fromPath: string,
    toPath: string,
    curr: CachedFile,
    sourceTag: string
  ): StreamEvent {
    const fallbackBlobs: Array<{ key: string; content: string | Buffer; contentType?: string }> = [];
    if (!curr.sensitiveRedacted && curr.text !== null && curr.size <= 256_000) {
      fallbackBlobs.push({
        key: 'snapshot',
        content: curr.text,
        contentType: 'text/plain; charset=utf-8'
      });
    }
    const ev = this.store.append({
      type: 'fs.renamed',
      actor: { kind: 'watcher', id: 'fs-watcher', name: 'Workspace Watcher' },
      harness: sourceTag === 'offline-reconcile' ? 'manual' : 'watcher',
      sessionId: this.sessionId,
      summary: `Renamed ${fromPath} -> ${toPath}`,
      affectedPaths: [fromPath, toPath],
      tags: ['fs', 'rename', sourceTag],
      payload: {
        fromPath,
        toPath,
        contentHash: curr.hash,
        sizeBytes: curr.size,
        sensitiveRedacted: curr.sensitiveRedacted || undefined
      },
      fallbackBlobs
    });
    this.onEvent?.(ev);
    return ev;
  }

  private emitFileEvent(
    type: 'fs.created' | 'fs.modified',
    relPath: string,
    prev: CachedFile | null,
    curr: CachedFile,
    sourceTag: string
  ): StreamEvent {
    const fallbackBlobs: Array<{ key: string; content: string | Buffer; contentType?: string }> = [];
    const payload: Record<string, unknown> = {
      path: relPath,
      contentHash: curr.hash,
      sizeBytes: curr.size,
      previousHash: prev?.hash ?? null
    };

    if (curr.sensitiveRedacted) {
      payload.sensitiveRedacted = true;
      payload.note = 'Sensitive credential/key file content excluded from stream diffs and blobs.';
    } else if (curr.text !== null) {
      if (type === 'fs.created' || prev !== null) {
        const beforeText = prev?.text ?? '';
        const diff = computeUnifiedDiff(relPath, beforeText, curr.text);
        const safeDiff = redactSecrets(diff.unified);
        payload.linesAdded = diff.added;
        payload.linesRemoved = diff.removed;
        if (Buffer.byteLength(safeDiff, 'utf8') <= this.maxInlineDiffBytes) {
          payload.diff = safeDiff;
        } else {
          payload.diffTruncated = true;
          fallbackBlobs.push({
            key: 'diff',
            content: safeDiff,
            contentType: 'text/x-diff; charset=utf-8'
          });
        }
      }
      if (curr.size <= 256_000) {
        fallbackBlobs.push({
          key: 'snapshot',
          content: curr.text,
          contentType: 'text/plain; charset=utf-8'
        });
      }
    }

    const verb = type === 'fs.created' ? 'Created' : 'Modified';
    const delta = curr.sensitiveRedacted
      ? ' (metadata only; sensitive file redacted)'
      : typeof payload.linesAdded === 'number'
        ? ` (+${payload.linesAdded}/-${payload.linesRemoved})`
        : ` (${curr.size}B)`;

    const ev = this.store.append({
      type,
      actor: { kind: 'watcher', id: 'fs-watcher', name: 'Workspace Watcher' },
      harness: sourceTag === 'offline-reconcile' ? 'manual' : 'watcher',
      sessionId: this.sessionId,
      summary: `${verb} ${relPath}${delta}`,
      affectedPaths: [relPath],
      tags: ['fs', sourceTag, ...(curr.sensitiveRedacted ? ['sensitive-redacted'] : [])],
      payload,
      fallbackBlobs
    });
    this.onEvent?.(ev);

    if (!curr.sensitiveRedacted && isCrashLogFile(relPath)) {
      const content =
        readTextFileSafe(path.join(this.store.workspaceRoot, relPath), 512_000, this.store.workspaceRoot) ?? '';
      const safeContent = redactSecrets(content);
      const firstErrorLine =
        safeContent
          .split(/\r?\n/)
          .find((l) => /error|exception|fatal|panic|segfault/i.test(l))
          ?.trim() ?? `Crash log detected: ${relPath}`;
      const crashEv = this.store.append({
        type: 'exec.crashed',
        actor: { kind: 'watcher', id: 'fs-watcher', name: 'Workspace Watcher' },
        harness: 'watcher',
        sessionId: this.sessionId,
        causationId: ev.id,
        summary: `Crash log detected in ${relPath}: ${firstErrorLine.slice(0, 120)}`,
        affectedPaths: [relPath],
        tags: ['crash', 'crash-log'],
        payload: {
          command: `crash-log:${relPath}`,
          exitCode: null,
          errorSignature: firstErrorLine.slice(0, 180),
          stderrExcerpt: safeContent.slice(0, 1000)
        },
        fallbackBlobs: safeContent
          ? [{ key: 'crashLog', content: safeContent, contentType: 'text/plain; charset=utf-8' }]
          : []
      });
      this.onEvent?.(crashEv);
    }

    return ev;
  }
}

import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { StreamStore } from '../core/stream-store.js';
import { StreamEvent } from '../core/types.js';
import { atomicWriteFileSync, isWritablePathConfinedToRoot } from '../utils/fs-helpers.js';

const HOOK_MARKER = '# NUMBERONE-MANAGED-HOOK';
const SUPPORTED_HOOKS = ['post-commit', 'post-checkout', 'post-merge', 'pre-push'] as const;
export type SupportedGitHook = (typeof SUPPORTED_HOOKS)[number];

/**
 * Strict POSIX single-quote escaping: neutralizes $, backticks, quotes, newlines, and globs.
 */
export function shellSingleQuote(value: string): string {
  return `'${value.replace(/'/g, "'\\''")}'`;
}

function assertSafeCliCommand(cliCommand: string): string {
  if (!/^[A-Za-z0-9._/-]+$/.test(cliCommand)) {
    throw new Error(`Unsafe CLI command name for hook generation: ${cliCommand}`);
  }
  return cliCommand;
}

function runGit(workspaceRoot: string, args: string[]): string | null {
  try {
    return execFileSync('git', args, {
      cwd: workspaceRoot,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore']
    }).trim();
  } catch {
    return null;
  }
}

export function isGitRepository(workspaceRoot: string): boolean {
  return runGit(workspaceRoot, ['rev-parse', '--is-inside-work-tree']) === 'true';
}

function resolveLocalCliInvocation(): string | null {
  const thisDir = path.dirname(fileURLToPath(import.meta.url));
  // Check compiled dist/cli.js relative to dist/watchers/git-hooks.js or package root
  const candidates = [
    path.resolve(thisDir, '../cli.js'),
    path.resolve(thisDir, '../../dist/cli.js')
  ];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) {
      return `${shellSingleQuote(process.execPath)} ${shellSingleQuote(candidate)}`;
    }
  }
  return null;
}

/**
 * Installs non-destructive Git hooks that forward commit, checkout, merge, and push
 * events to Number One while preserving any pre-existing user hooks.
 * Uses `git rev-parse --git-path hooks` (worktree & core.hooksPath safe),
 * refuses symlink hook targets, and uses strict POSIX single-quoting with `--workspace` before `-- "$@"`.
 */
export function installGitHooks(workspaceRoot: string, cliCommand = 'numberone'): {
  installed: string[];
  skippedReason?: string;
} {
  const safeCli = assertSafeCliCommand(cliCommand);
  const hooksPathRel =
    runGit(workspaceRoot, ['rev-parse', '--git-path', 'hooks']) ??
    (() => {
      const gitDirRel = runGit(workspaceRoot, ['rev-parse', '--git-dir']);
      return gitDirRel ? path.join(gitDirRel, 'hooks') : null;
    })();
  if (!hooksPathRel) {
    return { installed: [], skippedReason: 'Workspace is not a git repository' };
  }
  const hooksDir = path.resolve(workspaceRoot, hooksPathRel);
  const resolvedRoot = path.resolve(workspaceRoot);
  const hooksInsideWorkspace =
    hooksDir === resolvedRoot || hooksDir.startsWith(`${resolvedRoot}${path.sep}`);

  if (hooksInsideWorkspace && !isWritablePathConfinedToRoot(resolvedRoot, hooksDir)) {
    throw new Error(`Refusing to write git hooks through symlinked path: ${hooksDir}`);
  }
  if (fs.existsSync(hooksDir) && fs.lstatSync(hooksDir).isSymbolicLink()) {
    throw new Error(`Refusing to write into symlinked hooks directory: ${hooksDir}`);
  }

  fs.mkdirSync(hooksDir, { recursive: true });

  const localFallback = resolveLocalCliInvocation();
  const quotedWorkspace = shellSingleQuote(workspaceRoot);
  const quotedCli = shellSingleQuote(safeCli);

  const installed: string[] = [];
  for (const hook of SUPPORTED_HOOKS) {
    const hookPath = path.join(hooksDir, hook);
    if (hooksInsideWorkspace && !isWritablePathConfinedToRoot(resolvedRoot, hookPath)) {
      throw new Error(`Refusing to write git hook outside workspace confinement: ${hookPath}`);
    }
    try {
      if (fs.lstatSync(hookPath).isSymbolicLink()) {
        throw new Error(`Refusing to overwrite symlinked git hook: ${hookPath}`);
      }
    } catch (err) {
      if ((err as NodeJS.ErrnoException)?.code !== 'ENOENT') throw err;
    }

    const runnerLines = localFallback
      ? [
          `if command -v ${quotedCli} >/dev/null 2>&1; then`,
          `  ${quotedCli} git-hook ${hook} --workspace ${quotedWorkspace} -- "$@" >/dev/null 2>&1 || true`,
          `else`,
          `  ${localFallback} git-hook ${hook} --workspace ${quotedWorkspace} -- "$@" >/dev/null 2>&1 || true`,
          `fi`
        ]
      : [
          `if command -v ${quotedCli} >/dev/null 2>&1; then`,
          `  ${quotedCli} git-hook ${hook} --workspace ${quotedWorkspace} -- "$@" >/dev/null 2>&1 || true`,
          `fi`
        ];

    const snippet = ['', HOOK_MARKER, ...runnerLines, ''].join('\n');

    if (fs.existsSync(hookPath)) {
      const existing = fs.readFileSync(hookPath, 'utf8');
      if (!existing.includes(HOOK_MARKER)) {
        atomicWriteFileSync(hookPath, existing.trimEnd() + '\n' + snippet, 0o755);
      }
    } else {
      atomicWriteFileSync(hookPath, `#!/usr/bin/env sh\n${snippet}`, 0o755);
    }
    fs.chmodSync(hookPath, 0o755);
    installed.push(hook);
  }

  return { installed };
}

/**
 * Records a live Git hook invocation as an atomic Number One stream event.
 */
export function recordGitHookEvent(
  store: StreamStore,
  hook: SupportedGitHook,
  hookArgs: string[] = []
): StreamEvent | null {
  const root = store.workspaceRoot;
  if (!isGitRepository(root)) return null;

  const branch = runGit(root, ['rev-parse', '--abbrev-ref', 'HEAD']) ?? 'detached';
  const sha = runGit(root, ['rev-parse', 'HEAD']) ?? '';
  const authorName = runGit(root, ['log', '-1', '--format=%an']) ?? 'git-user';
  const authorEmail = runGit(root, ['log', '-1', '--format=%ae']) ?? '';

  if (hook === 'post-commit') {
    const subject = runGit(root, ['log', '-1', '--format=%s']) ?? 'Commit';
    const body = runGit(root, ['log', '-1', '--format=%b']) ?? '';
    // `--root` handles initial commit in a brand-new repository as well as subsequent commits
    const filesRaw = runGit(root, ['diff-tree', '--root', '--no-commit-id', '--name-only', '-r', sha]) ?? '';
    const changedFiles = filesRaw
      .split(/\r?\n/)
      .map((s) => s.trim())
      .filter(Boolean);
    const diffStat = runGit(root, ['show', '--stat', '--format=', sha]) ?? '';

    return store.append({
      type: 'git.commit',
      actor: { kind: 'git-hook', id: authorEmail || authorName, name: authorName },
      harness: 'git',
      summary: `Commit ${sha.slice(0, 8)} on ${branch}: ${subject}`,
      affectedPaths: changedFiles,
      tags: ['git', 'commit', branch],
      payload: {
        sha,
        branch,
        subject,
        body,
        authorName,
        authorEmail,
        changedFiles,
        diffStat
      }
    });
  }

  if (hook === 'post-checkout') {
    const [prevHead, newHead, branchFlag] = hookArgs;
    if (branchFlag === '0') return null;
    return store.append({
      type: 'git.checkout',
      actor: { kind: 'git-hook', id: authorEmail || authorName, name: authorName },
      harness: 'git',
      summary: `Checked out branch ${branch} (${(newHead ?? sha).slice(0, 8)})`,
      tags: ['git', 'checkout', branch],
      payload: {
        branch,
        fromSha: prevHead ?? null,
        toSha: newHead ?? sha
      }
    });
  }

  if (hook === 'post-merge') {
    const subject = runGit(root, ['log', '-1', '--format=%s']) ?? 'Merge';
    return store.append({
      type: 'git.merge',
      actor: { kind: 'git-hook', id: authorEmail || authorName, name: authorName },
      harness: 'git',
      summary: `Merged into ${branch}: ${subject}`,
      tags: ['git', 'merge', branch],
      payload: {
        branch,
        sha,
        subject,
        isSquash: hookArgs[0] === '1'
      }
    });
  }

  if (hook === 'pre-push') {
    const [remoteName, remoteUrl] = hookArgs;
    return store.append({
      type: 'git.push',
      actor: { kind: 'git-hook', id: authorEmail || authorName, name: authorName },
      harness: 'git',
      summary: `Pushing ${branch} (${sha.slice(0, 8)}) to ${remoteName ?? 'origin'}`,
      tags: ['git', 'push', branch],
      payload: {
        branch,
        sha,
        remoteName: remoteName ?? 'origin',
        remoteUrl: remoteUrl ?? ''
      }
    });
  }

  return null;
}

/**
 * Backfills existing Git commit history into the Number One stream on initial attachment.
 */
export function importGitHistory(store: StreamStore, limit = 50): StreamEvent[] {
  const root = store.workspaceRoot;
  if (!isGitRepository(root)) return [];

  const existingShas = new Set(
    store
      .query({ types: ['git.commit'] })
      .map((e) => String(e.payload.sha ?? ''))
      .filter(Boolean)
  );

  const raw = runGit(root, [
    'log',
    '-n',
    String(limit),
    '--reverse',
    '--format=%H%x1f%aI%x1f%an%x1f%ae%x1f%s'
  ]);
  if (!raw) return [];

  const branch = runGit(root, ['rev-parse', '--abbrev-ref', 'HEAD']) ?? 'main';
  const imported: StreamEvent[] = [];

  for (const line of raw.split(/\r?\n/)) {
    if (!line.trim()) continue;
    const [sha, isoDate, authorName, authorEmail, subject] = line.split('\x1f');
    if (!sha || existingShas.has(sha)) continue;

    const filesRaw = runGit(root, ['diff-tree', '--root', '--no-commit-id', '--name-only', '-r', sha]) ?? '';
    const changedFiles = filesRaw
      .split(/\r?\n/)
      .map((s) => s.trim())
      .filter(Boolean);

    const ev = store.append({
      type: 'git.commit',
      actor: { kind: 'git-hook', id: authorEmail || authorName || 'git', name: authorName },
      harness: 'git-backfill',
      summary: `Historical commit ${sha.slice(0, 8)}: ${subject ?? ''}`,
      affectedPaths: changedFiles,
      tags: ['git', 'commit', 'backfill'],
      timestamp: isoDate || undefined,
      payload: {
        sha,
        branch,
        subject: subject ?? '',
        authorName,
        authorEmail,
        changedFiles
      }
    });
    imported.push(ev);
  }

  return imported;
}

import path from 'node:path';
import { StreamStore } from '../core/stream-store.js';
import { StreamEvent } from '../core/types.js';
import { readTextFileSafe } from '../utils/fs-helpers.js';
import { isSensitiveSecretFile, redactSecrets } from '../utils/redactor.js';

export interface IngestTranscriptOptions {
  filePath: string;
  harness?: string;
  sessionId?: string;
  maxFileBytes?: number;
}

export interface IngestResult {
  filePath: string;
  detectedFormat: 'jsonl' | 'markdown';
  eventsIngested: StreamEvent[];
  thinkingCount: number;
  failedAttemptCount: number;
  lessonCount: number;
  decisionCount: number;
}

const THINKING_HINTS = /\b(thinking|hypothesis|tried|investigat|root cause|dead[- ]end|turns out|realized|wait,)\b/i;
const FAILED_HINTS = /\b(failed|didn't work|did not work|dead end|broke|crashed|reverted|abandoned)\b/i;
const LESSON_HINTS = /\b(lesson learned|never do|always ensure|note to self|takeaway|invariant|root cause was)\b/i;
const DECISION_HINTS = /(?:\bdecided to\b|\bdecision:|\bwe chose\b|\barchitecture decision\b|\bgoing with\b)/i;

function extractPathsFromText(text: string): string[] {
  const matches = text.match(/\b[a-zA-Z0-9_./-]+\.(?:ts|tsx|js|jsx|py|go|rs|java|yml|yaml|json|md|tf|dockerfile)\b/gi) ?? [];
  return Array.from(new Set(matches.map((m) => m.replace(/^\.\//, '')))).slice(0, 10);
}

function normalizeIsoTimestamp(rawTs: unknown): string | undefined {
  if (typeof rawTs !== 'string' || !rawTs.trim()) return undefined;
  const parsed = Date.parse(rawTs);
  if (Number.isNaN(parsed)) return undefined;
  return new Date(parsed).toISOString();
}

function parseJsonTranscriptObjects(raw: string): Record<string, unknown>[] {
  const objects: Record<string, unknown>[] = [];
  const lines = raw.split(/\r?\n/).filter((l) => l.trim().startsWith('{'));
  for (const line of lines) {
    try {
      const parsed = JSON.parse(line) as unknown;
      if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
        objects.push(parsed as Record<string, unknown>);
      }
    } catch {
      // May be pretty-printed multi-line JSON — handled by whole-document fallback below
    }
  }
  if (objects.length > 0) return objects;

  // Fallback: whole-document JSON (single object, array of turns, or { messages/events: [...] })
  try {
    const doc = JSON.parse(raw) as unknown;
    if (Array.isArray(doc)) {
      return doc.filter((item): item is Record<string, unknown> => Boolean(item && typeof item === 'object' && !Array.isArray(item)));
    }
    if (doc && typeof doc === 'object') {
      const rec = doc as Record<string, unknown>;
      const nestedList = Array.isArray(rec.messages)
        ? rec.messages
        : Array.isArray(rec.turns)
          ? rec.turns
          : Array.isArray(rec.events)
            ? rec.events
            : null;
      if (nestedList) {
        return nestedList.filter(
          (item): item is Record<string, unknown> => Boolean(item && typeof item === 'object' && !Array.isArray(item))
        );
      }
      return [rec];
    }
  } catch {
    // not valid JSON
  }
  return [];
}

/**
 * Harness-agnostic transcript & chat log ingestor.
 * Preserves intermediate thinking, dead-ends, decisions, and lessons learned across
 * Claude Code, Cursor, Antigravity/Gemini, Codex, Copilot, and raw human markdown notes.
 */
export function ingestTranscriptFile(store: StreamStore, options: IngestTranscriptOptions): IngestResult {
  const absPath = path.resolve(options.filePath);
  if (isSensitiveSecretFile(absPath)) {
    throw new Error(`Refusing to ingest sensitive secret/credential file as transcript: ${absPath}`);
  }
  const maxBytes = options.maxFileBytes ?? 25 * 1024 * 1024;
  // FD-based safe read (O_NOFOLLOW | O_NONBLOCK): blocks symlinks, FIFOs, and oversized files atomically
  const raw = readTextFileSafe(absPath, maxBytes);
  if (raw === null) {
    throw new Error(
      `Transcript path could not be read as a regular non-symlink UTF-8 file within ${maxBytes} bytes: ${absPath}`
    );
  }

  const sessionId = options.sessionId ?? `transcript-${path.basename(absPath, path.extname(absPath))}`;
  const harness = options.harness ?? detectHarnessFromPath(absPath);

  const trimmedStart = raw.trimStart();
  const isJsonLike =
    absPath.endsWith('.jsonl') ||
    absPath.endsWith('.json') ||
    trimmedStart.startsWith('{') ||
    trimmedStart.startsWith('[');
  const eventsIngested: StreamEvent[] = [];
  let thinkingCount = 0;
  let failedAttemptCount = 0;
  let lessonCount = 0;
  let decisionCount = 0;

  if (isJsonLike) {
    const objects = parseJsonTranscriptObjects(raw);
    if (objects.length > 0 || absPath.endsWith('.jsonl') || absPath.endsWith('.json')) {
      for (const obj of objects) {
        const role = String(obj.role ?? obj.source ?? obj.type ?? 'unknown').toLowerCase();
        const timestamp = normalizeIsoTimestamp(obj.created_at ?? obj.timestamp);

        // 1. Capture explicit intermediate thinking block (redact BEFORE slicing!)
        const rawThinking = typeof obj.thinking === 'string' ? obj.thinking.trim() : '';
        const thinkingText = rawThinking ? redactSecrets(rawThinking) : '';
        if (thinkingText) {
          const ev = store.append({
            type: 'chat.thinking',
            actor: { kind: 'ai-agent', id: harness, name: harness },
            harness,
            sessionId,
            timestamp,
            summary: `Thinking: ${thinkingText.slice(0, 140)}`,
            affectedPaths: extractPathsFromText(thinkingText),
            tags: ['transcript', 'thinking'],
            payload: { thought: thinkingText.slice(0, 4000), sourceFile: absPath },
            fallbackBlobs:
              thinkingText.length > 4000
                ? [{ key: 'fullThinking', content: thinkingText, contentType: 'text/plain; charset=utf-8' }]
                : []
          });
          eventsIngested.push(ev);
          thinkingCount++;
        }

        const rawContent = extractContentField(obj);
        if (!rawContent) continue;
        const contentText = redactSecrets(rawContent);
        const paths = extractPathsFromText(contentText);

        // 2. Detect explicit failed attempts
        if (FAILED_HINTS.test(contentText) && contentText.length < 3000) {
          const ev = store.append({
            type: 'attempt.failed',
            actor: role.includes('user')
              ? { kind: 'human', id: 'user' }
              : { kind: 'ai-agent', id: harness },
            harness,
            sessionId,
            timestamp,
            summary: `Failed approach noted: ${contentText.slice(0, 140)}`,
            affectedPaths: paths,
            tags: ['transcript', 'failed-attempt'],
            payload: { approach: contentText.slice(0, 500), reason: contentText.slice(0, 1000) }
          });
          eventsIngested.push(ev);
          failedAttemptCount++;
        }

        // 3. Detect explicit lessons learned
        if (LESSON_HINTS.test(contentText)) {
          const ev = store.append({
            type: 'lesson.captured',
            actor: { kind: 'numberone', id: 'transcript-ingestor', name: 'Number One Ingestor' },
            harness,
            sessionId,
            timestamp,
            summary: `Lesson from ${harness}: ${contentText.slice(0, 120)}`,
            affectedPaths: paths,
            tags: ['transcript', 'lesson', harness],
            payload: {
              title: `Lesson from ${harness} (${sessionId})`,
              problem: contentText.slice(0, 600),
              rootCause: thinkingText ? thinkingText.slice(0, 600) : 'Extracted from session transcript',
              resolution: contentText.slice(0, 600),
              preventionRule: contentText.slice(0, 400),
              severity: 'medium',
              verified: false
            }
          });
          eventsIngested.push(ev);
          lessonCount++;
        }

        // 4. Detect decisions
        if (DECISION_HINTS.test(contentText)) {
          const ev = store.append({
            type: 'decision.recorded',
            actor: role.includes('user')
              ? { kind: 'human', id: 'user' }
              : { kind: 'ai-agent', id: harness },
            harness,
            sessionId,
            timestamp,
            summary: `Decision from ${harness}: ${contentText.slice(0, 120)}`,
            affectedPaths: paths,
            tags: ['transcript', 'decision', harness],
            payload: {
              title: contentText.slice(0, 100),
              decision: contentText.slice(0, 800),
              rationale: thinkingText.slice(0, 600) || 'Recorded during conversation'
            }
          });
          eventsIngested.push(ev);
          decisionCount++;
        }

        // 5. Record conversational turn
        const turnEv = store.append({
          type: 'chat.turn',
          actor: role.includes('user')
            ? { kind: 'human', id: 'user' }
            : { kind: 'ai-agent', id: harness },
          harness,
          sessionId,
          timestamp,
          summary: `[${role}] ${contentText.slice(0, 140)}`,
          affectedPaths: paths,
          tags: ['transcript', 'chat', harness],
          payload: { role, contentExcerpt: contentText.slice(0, 2000) },
          fallbackBlobs:
            contentText.length > 2000
              ? [{ key: 'fullTurn', content: contentText, contentType: 'text/plain; charset=utf-8' }]
              : []
        });
        eventsIngested.push(turnEv);
      }

      return {
        filePath: absPath,
        detectedFormat: 'jsonl',
        eventsIngested,
        thinkingCount,
        failedAttemptCount,
        lessonCount,
        decisionCount
      };
    }
  }

  // Markdown / Plain text transcript ingestion (redact entire blocks BEFORE slicing!)
  const blocks = raw.split(/\n{2,}/).map((b) => redactSecrets(b.trim())).filter(Boolean);
  for (const block of blocks) {
    const paths = extractPathsFromText(block);
    if (/^(thinking|thought|analysis):/i.test(block) || THINKING_HINTS.test(block)) {
      const ev = store.append({
        type: 'chat.thinking',
        actor: { kind: 'ai-agent', id: harness },
        harness,
        sessionId,
        summary: `Thinking: ${block.slice(0, 140)}`,
        affectedPaths: paths,
        tags: ['transcript', 'thinking'],
        payload: { thought: block.slice(0, 4000) }
      });
      eventsIngested.push(ev);
      thinkingCount++;
    }
    if (/^(failed|dead[- ]end):/i.test(block) || FAILED_HINTS.test(block)) {
      const ev = store.append({
        type: 'attempt.failed',
        actor: { kind: 'human', id: 'operator' },
        harness,
        sessionId,
        summary: `Failed attempt: ${block.slice(0, 140)}`,
        affectedPaths: paths,
        tags: ['transcript', 'failed-attempt'],
        payload: { approach: block.slice(0, 400), reason: block.slice(0, 800) }
      });
      eventsIngested.push(ev);
      failedAttemptCount++;
    }
    if (/^(lesson|lesson learned):/i.test(block) || LESSON_HINTS.test(block)) {
      const ev = store.append({
        type: 'lesson.captured',
        actor: { kind: 'numberone', id: 'transcript-ingestor' },
        harness,
        sessionId,
        summary: `Lesson: ${block.slice(0, 120)}`,
        affectedPaths: paths,
        tags: ['transcript', 'lesson'],
        payload: {
          title: block.slice(0, 90),
          problem: block.slice(0, 500),
          rootCause: 'Extracted from markdown session notes',
          resolution: block.slice(0, 500),
          preventionRule: block.slice(0, 400),
          severity: 'medium',
          verified: false
        }
      });
      eventsIngested.push(ev);
      lessonCount++;
    }
    if (/^(decision|adr):/i.test(block) || DECISION_HINTS.test(block)) {
      const ev = store.append({
        type: 'decision.recorded',
        actor: { kind: 'human', id: 'operator' },
        harness,
        sessionId,
        summary: `Decision: ${block.slice(0, 120)}`,
        affectedPaths: paths,
        tags: ['transcript', 'decision'],
        payload: {
          title: block.slice(0, 90),
          decision: block.slice(0, 600),
          rationale: 'Extracted from session transcript'
        }
      });
      eventsIngested.push(ev);
      decisionCount++;
    }
  }

  return {
    filePath: absPath,
    detectedFormat: 'markdown',
    eventsIngested,
    thinkingCount,
    failedAttemptCount,
    lessonCount,
    decisionCount
  };
}

function detectHarnessFromPath(filePath: string): string {
  const lower = filePath.toLowerCase();
  if (lower.includes('claude')) return 'claude-code';
  if (lower.includes('cursor')) return 'cursor';
  if (lower.includes('gemini') || lower.includes('jetski') || lower.includes('antigravity')) return 'antigravity';
  if (lower.includes('windsurf')) return 'windsurf';
  if (lower.includes('copilot')) return 'copilot';
  if (lower.includes('codex')) return 'codex';
  return 'transcript';
}

function extractContentField(obj: Record<string, unknown>): string {
  if (typeof obj.content === 'string') return obj.content.trim();
  if (Array.isArray(obj.content)) {
    return obj.content
      .map((part) => {
        if (typeof part === 'string') return part;
        if (part && typeof part === 'object' && typeof (part as { text?: unknown }).text === 'string') {
          return (part as { text: string }).text;
        }
        return '';
      })
      .filter(Boolean)
      .join('\n')
      .trim();
  }
  if (typeof obj.message === 'string') return obj.message.trim();
  if (obj.message && typeof obj.message === 'object') {
    return extractContentField(obj.message as Record<string, unknown>);
  }
  return '';
}

