      const issuedEvent = JSON.parse(issuedText) as { actor: { kind: string }; payload: { severity: string } };
      expect(issuedEvent.actor.kind).toBe('ai-agent');
      expect(issuedEvent.payload.severity).toBe('advisory');
    } finally {
      rl.close();
      child.kill('SIGTERM');
    }
  });

