    // Intentionally insecure Dockerfile (runs as root) + unpinned GHA workflow -> triggers HOLD + blocking directive!
    fs.writeFileSync(path.join(ws, 'Dockerfile'), 'FROM node:22-alpine\nCMD ["node", "index.js"]\n');
